    private static void AssertLearnRelatedToolOpenedWithoutRun(
        OpenVisionShellHostView shellHost,
        int expectedRunCount,
        int expectedLayerDocumentCount,
        string expectedWorkspaceLayerTitle,
        string expectedViewType,
        VISION_MENU expectedMenu,
        string scenario)
    {
        string expectedTitle = OpenVisionLanguageService.T("VisionMenu." + expectedMenu);
        if (!shellHost.IsNativeDocumentActive
            || !shellHost.IsActiveWpfToolWindowVisibleForTest
            || !shellHost.ActiveNativeDocumentTypeName.Contains(expectedViewType, StringComparison.Ordinal)
            || !string.Equals(shellHost.ActiveWpfToolWindowTitle, expectedTitle, StringComparison.Ordinal))
        {
            throw new InvalidOperationException(
                scenario + " did not open the expected Tool View. "
                + $"Type='{shellHost.ActiveNativeDocumentTypeName}', Title='{shellHost.ActiveWpfToolWindowTitle}', ExpectedTitle='{expectedTitle}'.");
        }

        if (shellHost.NativePreviewRunCount != expectedRunCount
            || shellHost.HasNativePreviewResult
            || shellHost.LayerDocumentCount != expectedLayerDocumentCount
            || !string.Equals(shellHost.WorkspaceLayerTitle, expectedWorkspaceLayerTitle, StringComparison.Ordinal))
        {
            throw new InvalidOperationException(
                scenario + " changed Preview/Run or layer state. "
                + $"Runs={shellHost.NativePreviewRunCount}, HasResult={shellHost.HasNativePreviewResult}, "
                + $"Layers={shellHost.LayerDocumentCount}, Workspace='{shellHost.WorkspaceLayerTitle}'.");
        }
    }

    private static CaptureResult CaptureShellHostLlmDependencyPlaceholder(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        OpenVisionShellHostView shellHost = CreateShellHost("Smoke_WpfShellHostLlmDependencyPlaceholder", seedMainLayer: false);
        return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
        {
            if (shellHost.RecipeCommands.LlmXmlDraftDependencyRows.Count == 0)
            {
                throw new InvalidOperationException("LLM dependency path review did not expose an initial placeholder row.");
            }

            OpenVisionRecipeDependencyReviewRow row = shellHost.RecipeCommands.LlmXmlDraftDependencyRows[0];
            if (!ContainsAny(row.Status, "대기", "Waiting")
                || !ContainsAny(row.Action, "XML 초안", "XML draft"))
            {
                throw new InvalidOperationException(
                    "LLM dependency path review placeholder row did not explain the next action. "
                    + $"Status='{row.Status}', Action='{row.Action}'");
            }

            ToggleButton? recipeManagerButton = FindNamedVisualChild<ToggleButton>(shellHost, "btnHostRecipeManager");
            if (recipeManagerButton == null)
            {
                throw new InvalidOperationException("Recipe manager button was not found.");
            }

            recipeManagerButton.IsChecked = true;
            Pump(80);
            TabItem? llmXmlTab = FindNamedVisualChild<TabItem>(shellHost, "tabRecipeLlmXml");
            if (llmXmlTab == null)
            {
                throw new InvalidOperationException("Recipe manager LLM XML tab was not found.");
            }

            llmXmlTab.IsSelected = true;
            Pump(80);
            AssertVisibleAutomationIds(
                shellHost,
                "WPF recipe manager initial LLM dependency rows",
                "HostRecipeLlmXmlTab",
                "HostRecipeLlmDependencyPathList");
            AssertVisibleTextContains(
                shellHost,
                "WPF recipe manager initial LLM dependency rows",
                "대기",
                "XML 초안");
            AssertVisibleAutomationIds(
                shellHost,
                "WPF recipe manager LLM inspection setup entry",
                "HostRecipeOpenGuidedSetupButton");
            AssertVisibleTextContains(
                shellHost,
                "WPF recipe manager LLM inspection setup entry",
                "\uAC80\uC0AC \uC124\uC815",
                "\uD544\uC694\uD55C \uAC12");
            SaveVisibleAutomationElementPng(
                shellHost,
                "HostRecipeLlmXmlDraftPanel",
                outputPath,
                "llm-xml-draft-panel.png");

            int previewRunsBeforeGuidedSetup = shellHost.NativePreviewRunCount;
            int layerCountBeforeGuidedSetup = shellHost.LayerDocumentCount;
            string draftBeforeGuidedSetup = shellHost.RecipeCommands.LlmXmlDraftText;
            ClickVisibleButtonByAutomationId(
                shellHost,
                "HostRecipeOpenGuidedSetupButton",
                "LLM XML inspection setup button");
            Pump(40);
            TabItem? guidedSetupTab = FindNamedVisualChild<TabItem>(shellHost, "tabRecipeGuidedSetup");
            if (guidedSetupTab?.IsSelected != true
                || shellHost.NativePreviewRunCount != previewRunsBeforeGuidedSetup
                || shellHost.LayerDocumentCount != layerCountBeforeGuidedSetup
                || shellHost.HasNativePreviewResult
                || !string.Equals(shellHost.RecipeCommands.LlmXmlDraftText, draftBeforeGuidedSetup, StringComparison.Ordinal))
            {
                throw new InvalidOperationException(
                    "LLM XML inspection setup button did not open Build inspection without changing runtime state. "
                    + $"Tab={guidedSetupTab?.IsSelected}, Runs={shellHost.NativePreviewRunCount}, Layers={shellHost.LayerDocumentCount}, "
                    + $"DraftChanged={!string.Equals(shellHost.RecipeCommands.LlmXmlDraftText, draftBeforeGuidedSetup, StringComparison.Ordinal)}.");
            }

            ToggleButton? advancedReviewToggle = FindVisualChildren<ToggleButton>(shellHost)
                .FirstOrDefault(item => string.Equals(
                    AutomationProperties.GetAutomationId(item),
                    "HostRecipeAdvancedReviewToggle",
                    StringComparison.Ordinal));
            if (advancedReviewToggle?.IsChecked == true)
            {
                advancedReviewToggle.IsChecked = false;
                Pump(40);
            }

            llmXmlTab.IsSelected = true;
            Pump(40);
        }, captureFloatingToolWindow: false);
    }

    private static CaptureResult CaptureShellHostOuterCornerLlmReview(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.English, false);
        CleanupTransientRecipeWorkspaces();

        string recipe = "Smoke_OuterCornerLlmReview_" + Guid.NewGuid().ToString("N");
        VisionPipelineStorage.Save(recipe, CreateRecipeContextSmokePipeline("OuterCorner_Source", 1));
        VisionPipelineStorage.SaveActivePipelineName(recipe, "OuterCorner_Source");

        OpenVisionShellHostView shellHost = CreateShellHost(recipe, seedMainLayer: true);
        return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
        {
            ToggleButton recipeManagerButton = FindNamedVisualChild<ToggleButton>(shellHost, "btnHostRecipeManager")
                ?? throw new InvalidOperationException("Outer-corner LLM review recipe manager button was not found.");
            int previewRunsBefore = shellHost.NativePreviewRunCount;
            int layerCountBefore = shellHost.LayerDocumentCount;
            recipeManagerButton.IsChecked = true;
            Pump(80);

            ToggleButton advancedToggle = FindNamedVisualChild<ToggleButton>(shellHost, "recipeAdvancedReviewToggle")
                ?? throw new InvalidOperationException("Outer-corner LLM review advanced toggle was not found.");
            advancedToggle.IsChecked = true;
            Pump(40);
            TabItem llmXmlTab = FindNamedVisualChild<TabItem>(shellHost, "tabRecipeLlmXml")
                ?? throw new InvalidOperationException("Outer-corner LLM review XML tab was not found.");
            llmXmlTab.IsSelected = true;
            Pump(40);

            VisionPipeline draft = CreateRecipeContextSmokePipeline("OuterCorner_Llm_Draft", 1);
            VisionPipelineStep step = draft.Steps[0];
            step.Name = "01 Verify Card Bottom Right Corner";
            step.ToolType = "OuterCornerIntersection";
            step.InputLayer = "Main";
            step.OutputLayer = "CardCornerEvidence";
            step.Parameters.Clear();
            step.Parameters["ForegroundThreshold"] = "45";
            step.Parameters["MinComponentArea"] = "10000";
            step.Parameters["EdgeFitEndPercent"] = "0.80";
            step.Parameters["SampleStep"] = "4";
            step.UseAcceptance = true;
            step.ExpectedSuccess = true;
            step.AcceptanceMetricName = VisionPipelineKnownMetrics.IntersectionX;
            step.UseAcceptanceMetricMinimum = true;
            step.AcceptanceMetricMinimum = 300;

            string draftPath = Path.Combine(Path.GetTempPath(), "OpenVisionLab_outer_corner_llm_review_" + Guid.NewGuid().ToString("N") + ".xml");
            SerializeHelper.SaveXmlFile(draftPath, draft);
            shellHost.RecipeCommands.LlmXmlDraftText = File.ReadAllText(draftPath);
            if (!shellHost.RecipeCommands.ValidateLlmXmlDraftTextForTest()
                || !shellHost.RecipeCommands.LlmXmlDraftValidationReport.Contains("Corner WAIT: same image; red/green + hough/projection/outer vs mark; no gate if fallback.", StringComparison.Ordinal)
                || shellHost.NativePreviewRunCount != previewRunsBefore
                || shellHost.LayerDocumentCount != layerCountBefore
                || shellHost.HasNativePreviewResult)
            {
                throw new InvalidOperationException(
                    "Outer-corner LLM draft validation did not expose the required visual-review WAIT state without execution. "
                    + $"Validation='{shellHost.RecipeCommands.LlmXmlDraftValidationReport}', Runs={shellHost.NativePreviewRunCount}/{previewRunsBefore}, Layers={shellHost.LayerDocumentCount}/{layerCountBefore}.");
            }

            AssertVisibleAutomationIds(
                shellHost,
                "Outer-corner LLM visual-review evidence",
                "HostRecipeLlmXmlDraftPanel",
                "HostRecipeLlmDraftValidationReport",
                "HostRecipeImportLlmXmlDraftButton");
        }, captureFloatingToolWindow: false, captureScreen: true);
    }

    private static OpenVisionLearnWindow GetVisibleLearnWindow(string source)
    {
        OpenVisionLearnWindow? learnWindow = Application.Current.Windows
            .OfType<OpenVisionLearnWindow>()
            .FirstOrDefault(item => item.IsVisible);
        if (learnWindow == null)
        {
            throw new InvalidOperationException(source + " did not open OpenVisionLab Learn.");
        }

        return learnWindow;
    }

    private static string ClickPracticeSamplesAndCaptureSelectedLearnPath(OpenVisionLearnWindow learnWindow, string name)
    {
        string? capturedLearnPathId = null;
        string? capturedError = null;
        Application.Current.Dispatcher.BeginInvoke(new Action(() =>
        {
            try
            {
                OpenVisionWorkspaceSamplePickerWindow? pickerWindow = Application.Current.Windows
                    .OfType<OpenVisionWorkspaceSamplePickerWindow>()
                    .FirstOrDefault(item => item.IsVisible);
                if (pickerWindow == null)
                {
                    capturedError = name + " did not open Sample Picker.";
                    return;
                }

                capturedLearnPathId = pickerWindow.ViewModel.SelectedLearnPathOption?.Id;
                pickerWindow.Close();
            }
            catch (Exception ex)
            {
                capturedError = ex.Message;
            }
        }), System.Windows.Threading.DispatcherPriority.ContextIdle);

        ClickVisibleButtonByAutomationId(learnWindow, "OpenVisionLearnPracticeSamplesButton", name);
        Pump(12);
        if (!string.IsNullOrWhiteSpace(capturedError))
        {
            throw new InvalidOperationException(capturedError);
        }

        if (string.IsNullOrWhiteSpace(capturedLearnPathId))
        {
            throw new InvalidOperationException(name + " opened Sample Picker without a selected Learn path.");
        }

        return capturedLearnPathId;
    }

    private static void ClickVisibleButtonByAutomationId(DependencyObject root, string automationId, string name)
    {
        Button? button = FindVisualChildren<Button>(root)
            .FirstOrDefault(item => item.IsVisible
                && string.Equals(AutomationProperties.GetAutomationId(item), automationId, StringComparison.Ordinal));
        if (button == null)
        {
            throw new InvalidOperationException(name + " was not visible.");
        }

        if (button.Command != null)
        {
            object parameter = button.CommandParameter;
            if (!button.Command.CanExecute(parameter))
            {
                throw new InvalidOperationException(name + " command was disabled.");
            }

            button.Command.Execute(parameter);
            return;
        }

        button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent, button));
    }

    private static string ReadVisibleTextByAutomationId(DependencyObject root, string automationId)
    {
        TextBlock textBlock = FindVisualChildren<TextBlock>(root)
            .FirstOrDefault(item => item.IsVisible
                && string.Equals(AutomationProperties.GetAutomationId(item), automationId, StringComparison.Ordinal))
            ?? throw new InvalidOperationException($"Visible text was not found: {automationId}");

        return textBlock.Text ?? string.Empty;
    }

    private static void AssertToolHeaderLearnOpensTopic(
        OpenVisionShellHostView shellHost,
        int expectedTopicIndex,
        string name)
    {
        Window toolWindow = GetActiveFloatingToolWindow(name);
        Button? learnButton = FindVisualChildren<Button>(toolWindow)
            .FirstOrDefault(item => item.IsVisible
                && string.Equals(
                    AutomationProperties.GetAutomationId(item),
                    "VisionToolHeaderLearnButton",
                    StringComparison.Ordinal));
        if (learnButton == null)
        {
            throw new InvalidOperationException(name + " Learn button was not visible.");
        }

        int beforeRuns = shellHost.NativePreviewRunCount;
        learnButton.RaiseEvent(new RoutedEventArgs(Button.ClickEvent, learnButton));
        Pump(12);

        OpenVisionLearnWindow learnWindow = GetVisibleLearnWindow(name + " Learn button");
        if (learnWindow.SelectedTopicIndexForTest != expectedTopicIndex)
        {
            throw new InvalidOperationException(
                name + " opened the wrong Learn topic. "
                + $"Expected={expectedTopicIndex}, Actual={learnWindow.SelectedTopicIndexForTest}");
        }

        learnButton.RaiseEvent(new RoutedEventArgs(Button.ClickEvent, learnButton));
        Pump(6);
        OpenVisionLearnWindow[] visibleLearnWindows = Application.Current.Windows
            .OfType<OpenVisionLearnWindow>()
            .Where(window => window.IsVisible)
            .ToArray();
        if (visibleLearnWindows.Length != 1 || !ReferenceEquals(visibleLearnWindows[0], learnWindow))
        {
            throw new InvalidOperationException(
                name + " repeated Learn click did not reactivate the existing window. "
                + $"Visible={visibleLearnWindows.Length}");
        }

        learnWindow.Close();
        Pump(6);
        learnButton.RaiseEvent(new RoutedEventArgs(Button.ClickEvent, learnButton));
        Pump(8);
        OpenVisionLearnWindow reopenedLearnWindow = GetVisibleLearnWindow(name + " reopened Learn button");
        if (ReferenceEquals(reopenedLearnWindow, learnWindow)
            || reopenedLearnWindow.SelectedTopicIndexForTest != expectedTopicIndex)
        {
            throw new InvalidOperationException(
                name + " did not create a fresh Learn window after close. "
                + $"ExpectedTopic={expectedTopicIndex}, ActualTopic={reopenedLearnWindow.SelectedTopicIndexForTest}");
        }

        reopenedLearnWindow.Close();
        Pump(6);
        if (shellHost.NativePreviewRunCount != beforeRuns)
        {
            throw new InvalidOperationException(
                name + " Learn button triggered Preview/Run. "
                + $"RunsBefore={beforeRuns}, RunsAfter={shellHost.NativePreviewRunCount}");
        }
    }

    private static CaptureResult CaptureShellHostToolSearch(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        OpenVisionShellHostView shellHost = CreateShellHost("Smoke_WpfShellHostToolSearch");
        return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
        {
            Pump(12);
            TextBox? searchBox = FindVisualChildren<TextBox>(shellHost)
                .FirstOrDefault(item => string.Equals(
                    AutomationProperties.GetAutomationId(item),
                    "HostToolSearchTextBox",
                    StringComparison.Ordinal));
            Button? clearButton = FindVisualChildren<Button>(shellHost)
                .FirstOrDefault(item => string.Equals(
                    AutomationProperties.GetAutomationId(item),
                    "HostToolSearchClearButton",
                    StringComparison.Ordinal));
            TextBlock? summary = FindVisualChildren<TextBlock>(shellHost)
                .FirstOrDefault(item => string.Equals(
                    AutomationProperties.GetAutomationId(item),
                    "HostToolSearchSummary",
                    StringComparison.Ordinal));
            if (searchBox == null || clearButton == null || summary == null)
            {
                throw new InvalidOperationException("Tool search controls were not available in the expanded Tool rail.");
            }

            int previewRunsBefore = shellHost.NativePreviewRunCount;
            int layerCountBefore = shellHost.LayerDocumentCount;
            string workspaceLayerBefore = shellHost.WorkspaceLayerTitle;
            string inputRouteBefore = shellHost.ActiveNativeRouteInputLayerNameForTest;
            string outputRouteBefore = shellHost.ActiveNativeRouteOutputLayerNameForTest;
            string llmXmlDraftBefore = shellHost.RecipeCommands.LlmXmlDraftText;

            AssertToolLearnTopicCatalog();
            AssertToolGuidedSetupCatalog();
            AssertToolSearchResult(shellHost, "InputLayerB", 1, "Arithmetic");
            AssertToolSearchResult(shellHost, "DistanceMmRange", 1, "Line");
            AssertToolSearchResult(shellHost, "템플릿 ScoreMax", 1, "Matching");

            shellHost.ClearToolSearchForTest();
            Pump(8);
            if (!string.IsNullOrEmpty(shellHost.ToolSearchTextForTest)
                || shellHost.VisibleToolSearchItemCountForTest != 16)
            {
                throw new InvalidOperationException(
                    "Clearing Tool search did not restore the full palette. "
                    + $"Text='{shellHost.ToolSearchTextForTest}', Visible={shellHost.VisibleToolSearchItemCountForTest}");
            }

            AssertToolSearchResult(shellHost, "핀 간격 mm", 1, "Line");
            if (!string.Equals(searchBox.Text, "핀 간격 mm", StringComparison.Ordinal)
                || !summary.Text.Contains("1", StringComparison.Ordinal)
                || !clearButton.IsVisible)
            {
                throw new InvalidOperationException(
                    "Tool search did not expose the final query, result count, and clear action. "
                    + $"Text='{searchBox.Text}', Summary='{summary.Text}', ClearVisible={clearButton.IsVisible}");
            }

            Button? guidedSetupShortcut = FindVisualChildren<Button>(shellHost)
                .FirstOrDefault(item => item.IsVisible
                    && string.Equals(
                        AutomationProperties.GetAutomationId(item),
                        "HostToolSearchGuidedSetupButton",
                        StringComparison.Ordinal));
            FrameworkElement? toolRail = FindNamedVisualChild<FrameworkElement>(shellHost, "toolRailBorder");
            if (guidedSetupShortcut == null || toolRail == null)
            {
                throw new InvalidOperationException("Line search result did not expose a Guided Setup shortcut inside the Tool rail.");
            }

            Point guidedSetupPosition = guidedSetupShortcut.TranslatePoint(new Point(0D, 0D), toolRail);
            if (guidedSetupPosition.X < 0D
                || guidedSetupPosition.X + guidedSetupShortcut.ActualWidth > toolRail.ActualWidth + 0.5D)
            {
                throw new InvalidOperationException(
                    "Guided Setup shortcut was clipped by the Tool rail. "
                    + $"X={guidedSetupPosition.X:0.0}, Width={guidedSetupShortcut.ActualWidth:0.0}, RailWidth={toolRail.ActualWidth:0.0}");
            }

            ClickVisibleButtonByAutomationId(shellHost, "HostToolSearchLearnButton", "Line search result Learn button");
            Pump(12);
            OpenVisionLearnWindow learnWindow = GetVisibleLearnWindow("Line search result Learn button");
            if (learnWindow.SelectedTopicIndexForTest != (int)OpenVisionLearnTopicIndex.LineDistance)
            {
                throw new InvalidOperationException(
                    "Line search result opened the wrong Learn topic. "
                    + $"Expected={(int)OpenVisionLearnTopicIndex.LineDistance}, Actual={learnWindow.SelectedTopicIndexForTest}");
            }

            learnWindow.SelectTopic(OpenVisionLearnTopicIndex.Curriculum);
            ClickVisibleButtonByAutomationId(shellHost, "HostToolSearchLearnButton", "Line search result Learn reuse button");
            Pump(8);
            if (!ReferenceEquals(learnWindow, GetVisibleLearnWindow("Line search result Learn reuse button"))
                || learnWindow.SelectedTopicIndexForTest != (int)OpenVisionLearnTopicIndex.LineDistance)
            {
                throw new InvalidOperationException("Tool search did not reuse the Learn window at the requested topic.");
            }

            learnWindow.Close();
            Pump(8);

            string? selectedSamplePathId = null;
            string? samplePickerError = null;
            Application.Current.Dispatcher.BeginInvoke(new Action(() =>
            {
                OpenVisionWorkspaceSamplePickerWindow? pickerWindow = Application.Current.Windows
                    .OfType<OpenVisionWorkspaceSamplePickerWindow>()
                    .FirstOrDefault(item => item.IsVisible);
                if (pickerWindow == null)
                {
                    samplePickerError = "Line search result did not open Sample Picker.";
                    return;
                }

                selectedSamplePathId = pickerWindow.ViewModel.SelectedLearnPathOption?.Id;
                if (pickerWindow.ViewModel.VisibleSampleCount <= 0)
                {
                    samplePickerError = "Line Sample Picker path did not contain a visible public sample.";
                }

                pickerWindow.Close();
            }), System.Windows.Threading.DispatcherPriority.ContextIdle);

            ClickVisibleButtonByAutomationId(shellHost, "HostToolSearchSamplesButton", "Line search result samples button");
            Pump(12);
            if (!string.IsNullOrWhiteSpace(samplePickerError)
                || !string.Equals(selectedSamplePathId, "line", StringComparison.OrdinalIgnoreCase))
            {
                throw new InvalidOperationException(
                    samplePickerError
                    ?? $"Line search result opened the wrong sample path. Expected=line, Actual={selectedSamplePathId}");
            }

            ClickVisibleButtonByAutomationId(shellHost, "HostToolSearchGuidedSetupButton", "Line search result Guided Setup button");
            Pump(12);
            ToggleButton? recipeManagerButton = FindNamedVisualChild<ToggleButton>(shellHost, "btnHostRecipeManager");
            TabItem? guidedSetupTab = FindNamedVisualChild<TabItem>(shellHost, "tabRecipeGuidedSetup");
            if (recipeManagerButton?.IsChecked != true
                || guidedSetupTab?.IsSelected != true
                || !string.Equals(
                    shellHost.RecipeCommands.SelectedLlmToolTemplate,
                    OpenVisionGuidedSetupCatalog.PinGapTemplate,
                    StringComparison.Ordinal)
                || !string.Equals(shellHost.RecipeCommands.LlmXmlDraftText, llmXmlDraftBefore, StringComparison.Ordinal))
            {
                throw new InvalidOperationException(
                    "Line search result did not navigate to the existing pin-gap Guided Setup without generating XML. "
                    + $"Manager={recipeManagerButton?.IsChecked}, Tab={guidedSetupTab?.IsSelected}, "
                    + $"Intent='{shellHost.RecipeCommands.SelectedLlmToolTemplate}', "
                    + $"DraftChanged={!string.Equals(shellHost.RecipeCommands.LlmXmlDraftText, llmXmlDraftBefore, StringComparison.Ordinal)}");
            }

            recipeManagerButton.IsChecked = false;
            AssertToolSearchResult(shellHost, "Threshold", 1, "Threshold");
            Pump(8);
            if (FindVisualChildren<Button>(shellHost).Any(item =>
                    item.IsVisible
                    && string.Equals(
                        AutomationProperties.GetAutomationId(item),
                        "HostToolSearchGuidedSetupButton",
                        StringComparison.Ordinal)))
            {
                throw new InvalidOperationException("Threshold search result must not expose an unsupported Guided Setup shortcut.");
            }

            AssertToolSearchResult(shellHost, "핀 간격 mm", 1, "Line");
            Pump(8);

            Window.GetWindow(shellHost)?.Activate();
            shellHost.InvalidateVisual();
            shellHost.UpdateLayout();
            Pump(12);

            if (shellHost.NativePreviewRunCount != previewRunsBefore
                || shellHost.LayerDocumentCount != layerCountBefore
                || !string.Equals(shellHost.WorkspaceLayerTitle, workspaceLayerBefore, StringComparison.Ordinal)
                || !string.Equals(shellHost.ActiveNativeRouteInputLayerNameForTest, inputRouteBefore, StringComparison.Ordinal)
                || !string.Equals(shellHost.ActiveNativeRouteOutputLayerNameForTest, outputRouteBefore, StringComparison.Ordinal)
                || !string.Equals(shellHost.RecipeCommands.LlmXmlDraftText, llmXmlDraftBefore, StringComparison.Ordinal)
                || shellHost.IsActiveWpfToolWindowVisibleForTest
                || shellHost.IsNativeDocumentActive
                || shellHost.HasNativePreviewResult)
            {
                throw new InvalidOperationException(
                    "Tool search must filter display only. "
                    + $"Runs={previewRunsBefore}->{shellHost.NativePreviewRunCount}, "
                    + $"Layers={layerCountBefore}->{shellHost.LayerDocumentCount}, "
                    + $"Workspace='{workspaceLayerBefore}'->'{shellHost.WorkspaceLayerTitle}', "
                    + $"Input='{inputRouteBefore}'->'{shellHost.ActiveNativeRouteInputLayerNameForTest}', "
                    + $"Output='{outputRouteBefore}'->'{shellHost.ActiveNativeRouteOutputLayerNameForTest}', "
                    + $"ToolVisible={shellHost.IsActiveWpfToolWindowVisibleForTest}, NativeActive={shellHost.IsNativeDocumentActive}, Preview={shellHost.HasNativePreviewResult}");
            }
        }, captureFloatingToolWindow: false, captureScreen: true);
    }

    private static void AssertToolLearnTopicCatalog()
    {
        (VISION_MENU Menu, OpenVisionLearnTopicIndex Topic, string PracticePath)[] expected =
        {
            (VISION_MENU.Morphology, OpenVisionLearnTopicIndex.Morphology, "morphology"),
            (VISION_MENU.Filter, OpenVisionLearnTopicIndex.Filtering, "filter"),
            (VISION_MENU.Arithmetic, OpenVisionLearnTopicIndex.Arithmetic, "preprocess"),
            (VISION_MENU.EdgeDetection, OpenVisionLearnTopicIndex.EdgeDetection, "edge-detection"),
            (VISION_MENU.Blob, OpenVisionLearnTopicIndex.Blob, "blob"),
            (VISION_MENU.Contour, OpenVisionLearnTopicIndex.Contour, "contour"),
            (VISION_MENU.Matching, OpenVisionLearnTopicIndex.Matching, "template-matching"),
            (VISION_MENU.EdgeBasedMatching, OpenVisionLearnTopicIndex.EdgeBasedMatching, "edge-matching"),
            (VISION_MENU.Line, OpenVisionLearnTopicIndex.LineDistance, "line"),
            (VISION_MENU.RotateAndScale, OpenVisionLearnTopicIndex.GeometryTransform, "geometry"),
            (VISION_MENU.Histogram, OpenVisionLearnTopicIndex.Histogram, "mean"),
            (VISION_MENU.Mean, OpenVisionLearnTopicIndex.Mean, "mean"),
            (VISION_MENU.HSV, OpenVisionLearnTopicIndex.ColorHsv, "color-hsv"),
            (VISION_MENU.FeatureMatching, OpenVisionLearnTopicIndex.FeatureMatching, "feature-matching"),
            (VISION_MENU.Pipeline, OpenVisionLearnTopicIndex.LayerRecipe, "all"),
            (VISION_MENU.Threshold, OpenVisionLearnTopicIndex.Threshold, "threshold"),
        };

        if (expected.Length != Enum.GetValues(typeof(VISION_MENU)).Length)
        {
            throw new InvalidOperationException("Tool Learn topic catalog smoke does not cover every Tool rail menu.");
        }

        foreach ((VISION_MENU menu, OpenVisionLearnTopicIndex topic, string practicePath) in expected)
        {
            if (!OpenVisionLearnTopicCatalog.TryResolveForTool(menu, out OpenVisionLearnTopicIndex actual)
                || actual != topic
                || !string.Equals(
                    OpenVisionLearnTopicCatalog.Resolve(actual).PracticePathId,
                    practicePath,
                    StringComparison.OrdinalIgnoreCase))
            {
                throw new InvalidOperationException(
                    $"Tool Learn/sample mapping is invalid. Menu={menu}, Expected={topic}:{practicePath}, "
                    + $"Actual={actual}:{OpenVisionLearnTopicCatalog.Resolve(actual).PracticePathId}");
            }
        }
    }

    private static void AssertToolGuidedSetupCatalog()
    {
        Dictionary<VISION_MENU, string> expected = new Dictionary<VISION_MENU, string>
        {
            [VISION_MENU.Line] = OpenVisionGuidedSetupCatalog.PinGapTemplate,
            [VISION_MENU.Blob] = OpenVisionGuidedSetupCatalog.BlobTemplate,
            [VISION_MENU.Contour] = OpenVisionGuidedSetupCatalog.ContourTemplate,
            [VISION_MENU.Matching] = OpenVisionGuidedSetupCatalog.MatchingTemplate,
            [VISION_MENU.FeatureMatching] = OpenVisionGuidedSetupCatalog.FeatureMatchingTemplate,
            [VISION_MENU.EdgeBasedMatching] = OpenVisionGuidedSetupCatalog.EdgeBasedMatchingTemplate,
            [VISION_MENU.Mean] = OpenVisionGuidedSetupCatalog.MeanTemplate,
        };

        foreach (VISION_MENU menu in Enum.GetValues(typeof(VISION_MENU)))
        {
            bool resolved = OpenVisionGuidedSetupCatalog.TryResolveTemplate(menu, out string actualTemplate);
            if (expected.TryGetValue(menu, out string? expectedTemplate))
            {
                if (!resolved || !string.Equals(actualTemplate, expectedTemplate, StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        $"Guided Setup mapping is invalid. Menu={menu}, Expected='{expectedTemplate}', Actual='{actualTemplate}'");
                }
            }
            else if (resolved)
            {
                throw new InvalidOperationException(
                    $"Unsupported tool unexpectedly exposes Guided Setup. Menu={menu}, Template='{actualTemplate}'");
            }
        }
    }

    private static void AssertToolSearchResult(
        OpenVisionShellHostView shellHost,
        string query,
        int expectedCount,
        string expectedCommandIds)
    {
        shellHost.SetToolSearchTextForTest(query);
        Pump(8);
        if (shellHost.VisibleToolSearchItemCountForTest != expectedCount
            || !string.Equals(shellHost.VisibleToolSearchCommandIdsForTest, expectedCommandIds, StringComparison.Ordinal))
        {
            throw new InvalidOperationException(
                $"Tool search '{query}' returned an unexpected palette. "
                + $"Expected={expectedCount}:{expectedCommandIds}, "
                + $"Actual={shellHost.VisibleToolSearchItemCountForTest}:{shellHost.VisibleToolSearchCommandIdsForTest}");
        }
    }

    private static CaptureResult CaptureShellHostWorkspaceImageLoad(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        OpenVisionShellHostView shellHost = CreateShellHost("Smoke_WpfShellHostWorkspaceImageLoad", seedMainLayer: false);
        string imagePath = CreateWorkspaceLoadSmokeImageFile();
        try
        {
            return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
            {
                int previewRunsBefore = shellHost.NativePreviewRunCount;
                if (!shellHost.IsWorkspaceEmptyPromptVisible)
                {
                    throw new InvalidOperationException("WPF workspace image load test must start from the empty prompt.");
                }

                if (!shellHost.HasWorkspaceLoadImageMenu
                    || !shellHost.WorkspaceLoadImageMenuText.Contains(OpenVisionLanguageService.T("Shell.WorkspaceLoadImageButton"), StringComparison.Ordinal))
                {
                    throw new InvalidOperationException("WPF workspace does not expose the right-click image load menu.");
                }

                if (!shellHost.LoadMainImageFromFileForTest(imagePath))
                {
                    throw new InvalidOperationException("WPF workspace image load test helper failed.");
                }

                Pump(16);
                if (!shellHost.HasWorkspaceLayerPreview
                    || shellHost.IsWorkspaceEmptyPromptVisible
                    || !string.Equals(shellHost.WorkspaceLayerTitle, "Main", StringComparison.OrdinalIgnoreCase)
                    || !shellHost.WorkspaceLayerMeta.Contains("640x360", StringComparison.Ordinal))
                {
                    throw new InvalidOperationException("WPF workspace did not load the selected image into Main. Title='"
                        + shellHost.WorkspaceLayerTitle
                        + "', Meta='"
                        + shellHost.WorkspaceLayerMeta
                        + "'.");
                }

                if (shellHost.IsActiveWpfToolWindowVisibleForTest
                    || shellHost.IsNativeDocumentActive
                    || shellHost.NativePreviewRunCount != previewRunsBefore
                    || shellHost.HasNativePreviewResult)
                {
                    throw new InvalidOperationException(
                        "Workspace image load/readiness refresh must not open a tool or run Preview. "
                        + $"ToolVisible={shellHost.IsActiveWpfToolWindowVisibleForTest}, NativeActive={shellHost.IsNativeDocumentActive}, "
                        + $"Runs={previewRunsBefore}->{shellHost.NativePreviewRunCount}, Preview={shellHost.HasNativePreviewResult}");
                }

                AssertButtonTextContrast(
                    shellHost,
                    "WorkspaceMainActionThresholdButton",
                    "Workspace quick Threshold button");
                AssertButtonTextContrast(
                    shellHost,
                    "WorkspaceMainActionMatchingButton",
                    "Workspace quick Matching button");
                AssertButtonTextContrast(
                    shellHost,
                    "WorkspaceMainActionLineButton",
                    "Workspace quick Line button");

                VisionToolRepository repository = shellHost.VisionToolRepositoryForTest;
                if (repository == null)
                {
                    throw new InvalidOperationException("Matching-family readiness repository was not available.");
                }

                LineGaugeProperty lineA = repository.Lines_L.FirstOrDefault()
                    ?? new LineGaugeProperty("Line(L)_1");
                if (!repository.Lines_L.Contains(lineA))
                {
                    repository.Lines_L.Add(lineA);
                }

                LineGaugeProperty lineB = repository.Lines_R.FirstOrDefault()
                    ?? new LineGaugeProperty("Line(R)_1");
                if (!repository.Lines_R.Contains(lineB))
                {
                    repository.Lines_R.Add(lineB);
                }

                int lineScaleReadinessRunsBefore = shellHost.NativePreviewRunCount;
                int lineScaleLayerCountBefore = shellHost.LayerDocumentCount;
                string lineScaleInputRouteBefore = shellHost.ActiveNativeRouteInputLayerNameForTest;
                string lineScaleOutputRouteBefore = shellHost.ActiveNativeRouteOutputLayerNameForTest;
                lineA.PIXELPERMM = 0D;
                lineB.PIXELPERMM = 0D;
                OpenVisionNativeToolPropertySessionStore.Save("Line(L)_1", lineA);
                OpenVisionNativeToolPropertySessionStore.Save("Line(R)_1", lineB);
                Pump(8);
                AssertToolRailItemReadiness(
                    shellHost,
                    VISION_MENU.Line,
                    OpenVisionLanguageService.T("Shell.ToolReadiness.LineScalePixelOnlyBadge"),
                    OpenVisionLanguageService.T("Shell.ToolReadiness.LineScalePixelOnlyDescription"));

                lineA.PIXELPERMM = 0.006D;
                lineB.PIXELPERMM = 0.007D;
                OpenVisionNativeToolPropertySessionStore.Save("Line(L)_1", lineA);
                OpenVisionNativeToolPropertySessionStore.Save("Line(R)_1", lineB);
                Pump(8);
                AssertToolRailItemReadiness(
                    shellHost,
                    VISION_MENU.Line,
                    OpenVisionLanguageService.T("Shell.ToolReadiness.LineScaleReviewBadge"),
                    OpenVisionLanguageService.T("Shell.ToolReadiness.LineScaleReviewDescription"));

                lineB.PIXELPERMM = 0.006D;
                OpenVisionNativeToolPropertySessionStore.Save("Line(L)_1", lineA);
                OpenVisionNativeToolPropertySessionStore.Save("Line(R)_1", lineB);
                Pump(8);
                string lineScaleText = lineA.PIXELPERMM.ToString("0.######", CultureInfo.InvariantCulture);
                AssertToolRailItemReadiness(
                    shellHost,
                    VISION_MENU.Line,
                    string.Format(
                        CultureInfo.CurrentCulture,
                        OpenVisionLanguageService.T("Shell.ToolReadiness.LineScaleConfiguredBadgeFormat"),
                        lineScaleText),
                    string.Format(
                        CultureInfo.CurrentCulture,
                        OpenVisionLanguageService.T("Shell.ToolReadiness.LineScaleConfiguredDescriptionFormat"),
                        lineScaleText));
                if (shellHost.NativePreviewRunCount != lineScaleReadinessRunsBefore
                    || shellHost.LayerDocumentCount != lineScaleLayerCountBefore
                    || !string.Equals(shellHost.ActiveNativeRouteInputLayerNameForTest, lineScaleInputRouteBefore, StringComparison.Ordinal)
                    || !string.Equals(shellHost.ActiveNativeRouteOutputLayerNameForTest, lineScaleOutputRouteBefore, StringComparison.Ordinal)
                    || shellHost.IsActiveWpfToolWindowVisibleForTest
                    || shellHost.IsNativeDocumentActive
                    || shellHost.HasNativePreviewResult)
                {
                    throw new InvalidOperationException(
                        "Line scale readiness changes must be display-only. "
                        + $"Runs={lineScaleReadinessRunsBefore}->{shellHost.NativePreviewRunCount}, "
                        + $"Layers={lineScaleLayerCountBefore}->{shellHost.LayerDocumentCount}, "
                        + $"Input='{lineScaleInputRouteBefore}'->'{shellHost.ActiveNativeRouteInputLayerNameForTest}', "
                        + $"Output='{lineScaleOutputRouteBefore}'->'{shellHost.ActiveNativeRouteOutputLayerNameForTest}', "
                        + $"ToolVisible={shellHost.IsActiveWpfToolWindowVisibleForTest}, NativeActive={shellHost.IsNativeDocumentActive}, Preview={shellHost.HasNativePreviewResult}");
                }

                string arithmeticSettingsName = OpenVisionNativeToolSettingsStore.CreateConfigName("Arithmetic");
                ArithmeticToolSettings arithmeticSettings = new ArithmeticToolSettings
                {
                    SelectedOperation = "Bitwise_AND",
                    UseConstantInput = false,
                    UseOffsetMode = false
                };
                int arithmeticReadinessRunsBefore = shellHost.NativePreviewRunCount;
                OpenVisionNativeToolSettingsStore.Save(arithmeticSettingsName, arithmeticSettings);
                Pump(8);
                AssertToolRailItemReadiness(
                    shellHost,
                    VISION_MENU.Arithmetic,
                    OpenVisionLanguageService.T("Shell.ToolReadiness.InputBMissingBadge"),
                    OpenVisionLanguageService.T("Shell.ToolReadiness.InputBMissingDescription"));

                arithmeticSettings.SelectedOperation = "Bitwise_NOT";
                OpenVisionNativeToolSettingsStore.Save(arithmeticSettingsName, arithmeticSettings);
                Pump(8);
                AssertToolRailItemReadiness(
                    shellHost,
                    VISION_MENU.Arithmetic,
                    OpenVisionLanguageService.T("Shell.ToolReadiness.ConfigureBadge"),
                    OpenVisionLanguageService.T("Shell.ToolReadiness.ConfigureDescription"));

                arithmeticSettings.SelectedOperation = "Bitwise_AND";
                arithmeticSettings.UseConstantInput = true;
                OpenVisionNativeToolSettingsStore.Save(arithmeticSettingsName, arithmeticSettings);
                Pump(8);
                AssertToolRailItemReadiness(
                    shellHost,
                    VISION_MENU.Arithmetic,
                    OpenVisionLanguageService.T("Shell.ToolReadiness.ConfigureBadge"),
                    OpenVisionLanguageService.T("Shell.ToolReadiness.ConfigureDescription"));

                arithmeticSettings.UseConstantInput = false;
                arithmeticSettings.UseOffsetMode = true;
                OpenVisionNativeToolSettingsStore.Save(arithmeticSettingsName, arithmeticSettings);
                Pump(8);
                AssertToolRailItemReadiness(
                    shellHost,
                    VISION_MENU.Arithmetic,
                    OpenVisionLanguageService.T("Shell.ToolReadiness.ConfigureBadge"),
                    OpenVisionLanguageService.T("Shell.ToolReadiness.ConfigureDescription"));

                arithmeticSettings.UseOffsetMode = false;
                OpenVisionNativeToolSettingsStore.Save(arithmeticSettingsName, arithmeticSettings);
                Pump(8);
                AssertToolRailItemReadiness(
                    shellHost,
                    VISION_MENU.Arithmetic,
                    OpenVisionLanguageService.T("Shell.ToolReadiness.InputBMissingBadge"),
                    OpenVisionLanguageService.T("Shell.ToolReadiness.InputBMissingDescription"));

                using (Bitmap arithmeticInputB = new Bitmap(imagePath))
                {
                    if (!shellHost.AddLayerImageForTest("Arithmetic_InputB", arithmeticInputB))
                    {
                        throw new InvalidOperationException("Arithmetic readiness test could not add the Input B image layer.");
                    }
                }
                Pump(8);
                AssertToolRailItemReadiness(
                    shellHost,
                    VISION_MENU.Arithmetic,
                    OpenVisionLanguageService.T("Shell.ToolReadiness.ConfigureBadge"),
                    OpenVisionLanguageService.T("Shell.ToolReadiness.ConfigureDescription"));

                if (!shellHost.DeleteLayerForTest("Arithmetic_InputB"))
                {
                    throw new InvalidOperationException("Arithmetic readiness test could not remove the Input B image layer.");
                }
                Pump(8);
                AssertToolRailItemReadiness(
                    shellHost,
                    VISION_MENU.Arithmetic,
                    OpenVisionLanguageService.T("Shell.ToolReadiness.InputBMissingBadge"),
                    OpenVisionLanguageService.T("Shell.ToolReadiness.InputBMissingDescription"));
                if (shellHost.NativePreviewRunCount != arithmeticReadinessRunsBefore
                    || shellHost.IsActiveWpfToolWindowVisibleForTest
                    || shellHost.IsNativeDocumentActive
                    || shellHost.HasNativePreviewResult)
                {
                    throw new InvalidOperationException(
                        "Arithmetic Input B readiness changes must be display-only. "
                        + $"Runs={arithmeticReadinessRunsBefore}->{shellHost.NativePreviewRunCount}, "
                        + $"ToolVisible={shellHost.IsActiveWpfToolWindowVisibleForTest}, NativeActive={shellHost.IsNativeDocumentActive}, Preview={shellHost.HasNativePreviewResult}");
                }

                MatchingProperty matching = repository.Matchings.FirstOrDefault()
                    ?? new MatchingProperty("Matching_1");
                if (!repository.Matchings.Contains(matching))
                {
                    repository.Matchings.Add(matching);
                }

                EdgeBasedMatchingProperty edgeBasedMatching = repository.EdgeBasedMatchings.FirstOrDefault()
                    ?? new EdgeBasedMatchingProperty("EdgeBasedMatching_1");
                if (!repository.EdgeBasedMatchings.Contains(edgeBasedMatching))
                {
                    repository.EdgeBasedMatchings.Add(edgeBasedMatching);
                }

                FeatureMatchingProperty featureMatching = repository.Features.FirstOrDefault()
                    ?? new FeatureMatchingProperty("Feature_1");
                if (!repository.Features.Contains(featureMatching))
                {
                    repository.Features.Add(featureMatching);
                }

                int readinessResetRunsBefore = shellHost.NativePreviewRunCount;
                matching.PATTERN_PATH = string.Empty;
                matching.ReloadTemplateImage();
                OpenVisionNativeToolPropertySessionStore.Save("Matching", matching);
                edgeBasedMatching.PATTERN_PATH = string.Empty;
                edgeBasedMatching.ReloadTemplateImage();
                OpenVisionNativeToolPropertySessionStore.Save("EdgeBasedMatching", edgeBasedMatching);
                featureMatching.PATTERN_PATH = string.Empty;
                featureMatching.ReloadTemplateImage();
                OpenVisionNativeToolPropertySessionStore.Save("FeatureMatching", featureMatching);
                Pump(8);
                if (shellHost.NativePreviewRunCount != readinessResetRunsBefore
                    || shellHost.IsActiveWpfToolWindowVisibleForTest
                    || shellHost.IsNativeDocumentActive
                    || shellHost.HasNativePreviewResult)
                {
                    throw new InvalidOperationException(
                        "Matching-family readiness baseline reset must be display-only. "
                        + $"Runs={readinessResetRunsBefore}->{shellHost.NativePreviewRunCount}, "
                        + $"ToolVisible={shellHost.IsActiveWpfToolWindowVisibleForTest}, NativeActive={shellHost.IsNativeDocumentActive}, Preview={shellHost.HasNativePreviewResult}");
                }

                AssertToolRailReadiness(
                    shellHost,
                    OpenVisionLanguageService.T("Shell.ToolReadiness.ConfigureBadge"),
                    OpenVisionLanguageService.T("Shell.ToolReadiness.ConfigureDescription"),
                    VISION_MENU.Arithmetic,
                    VISION_MENU.Line,
                    VISION_MENU.Matching,
                    VISION_MENU.EdgeBasedMatching,
                    VISION_MENU.FeatureMatching);
                AssertToolRailItemReadiness(
                    shellHost,
                    VISION_MENU.Matching,
                    OpenVisionLanguageService.T("Shell.ToolReadiness.TemplateMissingBadge"),
                    OpenVisionLanguageService.T("Shell.ToolReadiness.TemplateMissingDescription"));
                AssertToolRailItemReadiness(
                    shellHost,
                    VISION_MENU.EdgeBasedMatching,
                    OpenVisionLanguageService.T("Shell.ToolReadiness.TemplateMissingBadge"),
                    OpenVisionLanguageService.T("Shell.ToolReadiness.TemplateMissingDescription"));
                AssertToolRailItemReadiness(
                    shellHost,
                    VISION_MENU.FeatureMatching,
                    OpenVisionLanguageService.T("Shell.ToolReadiness.TemplateMissingBadge"),
                    OpenVisionLanguageService.T("Shell.ToolReadiness.TemplateMissingDescription"));

                int matchingFamilyRunsBefore = shellHost.NativePreviewRunCount;
                edgeBasedMatching.PATTERN_PATH = imagePath;
                edgeBasedMatching.ReloadTemplateImage();
                OpenVisionNativeToolPropertySessionStore.Save("EdgeBasedMatching", edgeBasedMatching);
                Pump(8);
                AssertToolRailItemReadiness(
                    shellHost,
                    VISION_MENU.EdgeBasedMatching,
                    OpenVisionLanguageService.T("Shell.ToolReadiness.ConfigureBadge"),
                    OpenVisionLanguageService.T("Shell.ToolReadiness.ConfigureDescription"));

                edgeBasedMatching.PATTERN_PATH = string.Empty;
                edgeBasedMatching.ReloadTemplateImage();
                OpenVisionNativeToolPropertySessionStore.Save("EdgeBasedMatching", edgeBasedMatching);
                Pump(8);
                AssertToolRailItemReadiness(
                    shellHost,
                    VISION_MENU.EdgeBasedMatching,
                    OpenVisionLanguageService.T("Shell.ToolReadiness.TemplateMissingBadge"),
                    OpenVisionLanguageService.T("Shell.ToolReadiness.TemplateMissingDescription"));

                featureMatching.PATTERN_PATH = imagePath;
                featureMatching.ReloadTemplateImage();
                OpenVisionNativeToolPropertySessionStore.Save("FeatureMatching", featureMatching);
                Pump(8);
                AssertToolRailItemReadiness(
                    shellHost,
                    VISION_MENU.FeatureMatching,
                    OpenVisionLanguageService.T("Shell.ToolReadiness.ConfigureBadge"),
                    OpenVisionLanguageService.T("Shell.ToolReadiness.ConfigureDescription"));

                featureMatching.PATTERN_PATH = string.Empty;
                featureMatching.ReloadTemplateImage();
                OpenVisionNativeToolPropertySessionStore.Save("FeatureMatching", featureMatching);
                Pump(8);
                AssertToolRailItemReadiness(
                    shellHost,
                    VISION_MENU.FeatureMatching,
                    OpenVisionLanguageService.T("Shell.ToolReadiness.TemplateMissingBadge"),
                    OpenVisionLanguageService.T("Shell.ToolReadiness.TemplateMissingDescription"));
                if (shellHost.NativePreviewRunCount != matchingFamilyRunsBefore
                    || shellHost.IsActiveWpfToolWindowVisibleForTest
                    || shellHost.IsNativeDocumentActive
                    || shellHost.HasNativePreviewResult)
                {
                    throw new InvalidOperationException(
                        "EdgeBasedMatching/FeatureMatching readiness changes must be display-only. "
                        + $"Runs={matchingFamilyRunsBefore}->{shellHost.NativePreviewRunCount}, "
                        + $"ToolVisible={shellHost.IsActiveWpfToolWindowVisibleForTest}, NativeActive={shellHost.IsNativeDocumentActive}, Preview={shellHost.HasNativePreviewResult}");
                }

                shellHost.SelectToolForTest(VISION_MENU.Matching);
                Pump(12);
                shellHost.ConfigureActiveMatchingForTest(property => property.AUTO_PREVIEW = false);
                int templateChangeRunsBefore = shellHost.NativePreviewRunCount;
                shellHost.SetActiveMatchingTemplatePathForTest(imagePath);
                Pump(8);
                AssertToolRailItemReadiness(
                    shellHost,
                    VISION_MENU.Matching,
                    OpenVisionLanguageService.T("Shell.ToolReadiness.ConfigureBadge"),
                    OpenVisionLanguageService.T("Shell.ToolReadiness.ConfigureDescription"));

                shellHost.SetActiveMatchingTemplatePathForTest(string.Empty);
                Pump(8);
                AssertToolRailItemReadiness(
                    shellHost,
                    VISION_MENU.Matching,
                    OpenVisionLanguageService.T("Shell.ToolReadiness.TemplateMissingBadge"),
                    OpenVisionLanguageService.T("Shell.ToolReadiness.TemplateMissingDescription"));
                if (shellHost.NativePreviewRunCount != templateChangeRunsBefore
                    || !shellHost.CloseActiveWpfToolWindowForTest())
                {
                    throw new InvalidOperationException(
                        "Matching template readiness changes must not run Preview and the test tool must close cleanly. "
                        + $"Runs={templateChangeRunsBefore}->{shellHost.NativePreviewRunCount}");
                }
                Pump(8);
                if (!shellHost.LoadMainImageFromFileForTest(imagePath)
                    || shellHost.NativePreviewRunCount != templateChangeRunsBefore)
                {
                    throw new InvalidOperationException(
                        "Restoring the image-ready workspace after the Matching readiness check must not run Preview. "
                        + $"Runs={templateChangeRunsBefore}->{shellHost.NativePreviewRunCount}");
                }
                Pump(8);

                if (!shellHost.IsWorkspaceMainActionVisibleForTest
                    || !shellHost.WorkspaceMainActionTitleForTest.Contains(OpenVisionLanguageService.T("Shell.MainAction.ImageReadyTitle"), StringComparison.Ordinal)
                    || !shellHost.WorkspaceMainActionDetailForTest.Contains(OpenVisionLanguageService.T("Shell.MainAction.ImageReadyDetail"), StringComparison.Ordinal)
                    || !shellHost.WorkspaceMainActionMetaForTest.Contains("Main", StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        "Workspace image-ready next-action bar was not visible after loading Main. "
                        + $"Visible={shellHost.IsWorkspaceMainActionVisibleForTest}, "
                        + $"Title='{shellHost.WorkspaceMainActionTitleForTest}', "
                        + $"Detail='{shellHost.WorkspaceMainActionDetailForTest}', "
                        + $"Meta='{shellHost.WorkspaceMainActionMetaForTest}'");
                }

                if (!shellHost.DirectResultTitleText.Contains(OpenVisionLanguageService.T("Shell.MainAction.ImageReadyTitle"), StringComparison.Ordinal)
                    || !shellHost.DirectResultRouteText.Contains(OpenVisionLanguageService.T("Shell.MainAction.ImageReadyRoute"), StringComparison.Ordinal)
                    || !shellHost.DirectResultStatusText.Contains(OpenVisionLanguageService.T("Shell.MainAction.ImageReadyStatus"), StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        "WPF workspace image-ready top status banner did not match the loaded-image state. "
                        + $"Title='{shellHost.DirectResultTitleText}', Route='{shellHost.DirectResultRouteText}', Status='{shellHost.DirectResultStatusText}'");
                }

                AssertVisibleAutomationIds(
                    shellHost,
                    "WPF workspace image-ready action bar",
                    "WorkspaceMainActionOverlay",
                    "WorkspaceMainActionThresholdButton",
                    "WorkspaceMainActionMatchingButton",
                    "WorkspaceMainActionLineButton");
                AssertVisibleTextContains(
                    shellHost,
                    "WPF workspace image-ready localized quick actions",
                    OpenVisionLanguageService.T("Shell.MainAction.ImageReadyDetail"),
                    OpenVisionLanguageService.T("VisionMenu.Threshold"),
                    OpenVisionLanguageService.T("VisionMenu.Matching"),
                    OpenVisionLanguageService.T("VisionMenu.Line"));

                OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.English, false);
                Pump(8);
                AssertVisibleTextContains(
                    shellHost,
                    "WPF workspace image-ready English copy",
                    OpenVisionLanguageService.T("Shell.MainAction.ImageReadyTitle"),
                    OpenVisionLanguageService.T("Shell.MainAction.ImageReadyDetail"),
                    OpenVisionLanguageService.T("VisionMenu.Threshold"),
                    OpenVisionLanguageService.T("VisionMenu.Matching"),
                    OpenVisionLanguageService.T("VisionMenu.Line"));
                if (shellHost.IsActiveWpfToolWindowVisibleForTest || shellHost.IsNativeDocumentActive)
                {
                    throw new InvalidOperationException("Changing image-ready language must not open or retarget a tool window.");
                }

                OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
                Pump(8);
                AssertVisibleTextContains(
                    shellHost,
                    "WPF workspace image-ready Korean copy after language restore",
                    OpenVisionLanguageService.T("Shell.MainAction.ImageReadyTitle"),
                    OpenVisionLanguageService.T("Shell.MainAction.ImageReadyDetail"),
                    OpenVisionLanguageService.T("VisionMenu.Threshold"),
                    OpenVisionLanguageService.T("VisionMenu.Matching"),
                    OpenVisionLanguageService.T("VisionMenu.Line"));

                if (!shellHost.UpdateWorkspacePointerAtCenterForTest()
                    || string.Equals(shellHost.WorkspaceCoordinatesTextForTest, "X:- Y:-", StringComparison.Ordinal)
                    || string.Equals(shellHost.WorkspacePixelTextForTest, "GV - | RGB -", StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        "Workspace fallback viewer did not update pointer coordinate/pixel status. "
                        + $"Coordinates={shellHost.WorkspaceCoordinatesTextForTest}, Pixel={shellHost.WorkspacePixelTextForTest}");
                }

                string coordinateBeforeZoom = shellHost.GetWorkspacePointerCoordinateForTest(0.62D, 0.54D);
                shellHost.ZoomWorkspaceAtForTest(0.62D, 0.54D, 1.25D);
                Pump(4);
                string coordinateAfterZoom = shellHost.GetWorkspacePointerCoordinateForTest(0.62D, 0.54D);
                if (string.IsNullOrWhiteSpace(coordinateBeforeZoom)
                    || !string.Equals(coordinateBeforeZoom, coordinateAfterZoom, StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        "Workspace zoom did not keep the cursor-anchored image coordinate stable. "
                        + $"Before={coordinateBeforeZoom}, After={coordinateAfterZoom}");
                }

                string coordinateBeforePan = shellHost.GetWorkspacePointerCoordinateForTest(0.5D, 0.5D);
                shellHost.PanWorkspaceByForTest(24D, -18D);
                Pump(4);
                string coordinateAfterPan = shellHost.GetWorkspacePointerCoordinateForTest(0.5D, 0.5D);
                if (string.IsNullOrWhiteSpace(coordinateBeforePan)
                    || string.Equals(coordinateBeforePan, coordinateAfterPan, StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        "Workspace pan did not move the image coordinate under the viewport point. "
                        + $"Before={coordinateBeforePan}, After={coordinateAfterPan}");
                }
            }, captureFloatingToolWindow: false, verifyCapture: AssertWorkspaceLoadImageVisibleInCapture);
        }
        finally
        {
            TryDeleteFile(imagePath);
        }
    }

    private static CaptureResult CaptureShellHostWorkspaceSampleOpen(string outputPath)
    {
        return CaptureShellHostWorkspaceSampleOpen(outputPath, OpenVisionLanguage.Korean);
    }

    private static CaptureResult CaptureShellHostWorkspaceSampleOpen(
        string outputPath,
        OpenVisionLanguage language)
    {
        OpenVisionLanguageService.SetLanguage(language, false);
        OpenVisionShellHostView shellHost = CreateShellHost("Smoke_WpfShellHostWorkspaceSampleOpen", seedMainLayer: false);
        OpenVisionLanguageService.SetLanguage(language, false);
        return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
        {
            if (!shellHost.IsWorkspaceEmptyPromptVisible)
            {
                throw new InvalidOperationException("WPF workspace sample-open test must start from the empty prompt.");
            }

            AssertVisibleAutomationIds(
                shellHost,
                "WPF workspace sample entry",
                "WorkspaceEmptySampleButton");

            if (!shellHost.HasRunnableWorkspaceSampleForTest)
            {
                throw new InvalidOperationException("WPF workspace sample entry did not find a runnable sample catalog item.");
            }

            shellHost.OpenFirstRunnableWorkspaceSampleForTest();
            Pump(60);
            OpenVisionLanguageService.SetLanguage(language, false);
            Pump(24);

            if (!shellHost.HasMainLayer
                || !shellHost.HasWorkspaceLayerPreview
                || shellHost.IsWorkspaceEmptyPromptVisible
                || !string.Equals(shellHost.WorkspaceLayerTitle, "Main", StringComparison.OrdinalIgnoreCase))
            {
                throw new InvalidOperationException(
                    "WPF workspace sample entry did not load the sample image into Main. "
                    + $"HasMain={shellHost.HasMainLayer}, HasPreview={shellHost.HasWorkspaceLayerPreview}, "
                    + $"Empty={shellHost.IsWorkspaceEmptyPromptVisible}, Title='{shellHost.WorkspaceLayerTitle}'");
            }

            if (!shellHost.ActivePipelineNameForTest.StartsWith("Sample_", StringComparison.Ordinal)
                || shellHost.ActivePipelineStepCountForTest <= 0)
            {
                throw new InvalidOperationException(
                    "WPF workspace sample entry did not activate a sample pipeline. "
                    + $"Pipeline='{shellHost.ActivePipelineNameForTest}', Steps={shellHost.ActivePipelineStepCountForTest}");
            }

            if (shellHost.IsWorkspaceMainActionVisibleForTest)
            {
                throw new InvalidOperationException("Sample workspace should show the sample workflow bar instead of the generic image-ready bar.");
            }

            string workflowDetail = shellHost.WorkspaceSampleWorkflowDetailForTest ?? string.Empty;
            string firstStepMenu = shellHost.WorkspaceSampleFirstStepMenuForTest ?? string.Empty;
            string activeSampleName = shellHost.ActivePipelineNameForTest.StartsWith("Sample_", StringComparison.Ordinal)
                ? shellHost.ActivePipelineNameForTest.Substring("Sample_".Length)
                : shellHost.ActivePipelineNameForTest;
            bool hasExpectedWorkflowCopy = language == OpenVisionLanguage.English
                ? shellHost.WorkspaceSampleWorkflowTitleForTest.Contains("Sample", StringComparison.OrdinalIgnoreCase)
                    && workflowDetail.Contains("product", StringComparison.OrdinalIgnoreCase)
                    && workflowDetail.Contains("criteria", StringComparison.OrdinalIgnoreCase)
                    && workflowDetail.Contains("next", StringComparison.OrdinalIgnoreCase)
                : shellHost.WorkspaceSampleWorkflowTitleForTest.Contains("\uC0D8\uD50C", StringComparison.Ordinal)
                    && workflowDetail.Contains("\uC81C\uD488\uAD70", StringComparison.Ordinal)
                    && workflowDetail.Contains("\uAE30\uC900", StringComparison.Ordinal)
                    && workflowDetail.Contains("\uB2E4\uC74C", StringComparison.Ordinal);
            if (!shellHost.IsWorkspaceSampleWorkflowVisibleForTest
                || !hasExpectedWorkflowCopy
                || !shellHost.WorkspaceSampleWorkflowMetaForTest.Contains(activeSampleName, StringComparison.Ordinal)
                || string.IsNullOrWhiteSpace(workflowDetail)
                || string.IsNullOrWhiteSpace(firstStepMenu)
                || !workflowDetail.Contains("Run Review", StringComparison.Ordinal)
                || !workflowDetail.Contains(firstStepMenu, StringComparison.Ordinal))
            {
                throw new InvalidOperationException(
                    "WPF workspace sample entry did not show the next-action workflow hint. "
                    + $"Visible={shellHost.IsWorkspaceSampleWorkflowVisibleForTest}, "
                    + $"Title='{shellHost.WorkspaceSampleWorkflowTitleForTest}', "
                    + $"Meta='{shellHost.WorkspaceSampleWorkflowMetaForTest}', "
                    + $"Detail='{shellHost.WorkspaceSampleWorkflowDetailForTest}'");
            }

            if (!shellHost.DirectResultTitleText.Contains(OpenVisionLanguageService.T("Shell.WorkspaceStatus.SampleTitle"), StringComparison.Ordinal)
                || !shellHost.DirectResultRouteText.Contains(OpenVisionLanguageService.T("Shell.WorkspaceStatus.SampleRoute"), StringComparison.Ordinal)
                || !shellHost.DirectResultStatusText.Contains(OpenVisionLanguageService.T("Shell.WorkspaceStatus.SampleStatus"), StringComparison.Ordinal))
            {
                throw new InvalidOperationException(
                    "WPF workspace sample top status banner did not match the sample-ready state. "
                    + $"Title='{shellHost.DirectResultTitleText}', Route='{shellHost.DirectResultRouteText}', Status='{shellHost.DirectResultStatusText}'");
            }

            AssertVisibleAutomationIds(
                shellHost,
                "WPF workspace sample workflow",
                "WorkspaceSampleWorkflowOverlay",
                "WorkspaceSamplePipelineButton",
                "WorkspaceSampleFirstStepButton",
                "ShellStatusRecipe",
                "ShellStatusLayer",
                "ShellStatusTool");

            AssertButtonTextContrast(shellHost, "WorkspaceSamplePipelineButton", "Workspace sample Pipeline button");
            AssertButtonTextContrast(shellHost, "WorkspaceSampleFirstStepButton", "Workspace sample first-step button");
            if (FindVisualChildren<TextBlock>(shellHost).Any(item =>
                string.Equals(item.Text, "27.7%", StringComparison.Ordinal)
                || string.Equals(item.Text, "C:", StringComparison.Ordinal)))
            {
                throw new InvalidOperationException("Workspace status bar still exposes generic drive-capacity UI.");
            }

            if (!shellHost.CanOpenSamplePipelineForTest
                || !shellHost.CanOpenSampleFirstStepToolForTest
                || string.IsNullOrWhiteSpace(shellHost.WorkspaceSampleFirstStepMenuForTest))
            {
                throw new InvalidOperationException(
                    "WPF workspace sample workflow commands were not ready. "
                    + $"Pipeline={shellHost.CanOpenSamplePipelineForTest}, "
                    + $"FirstStep={shellHost.CanOpenSampleFirstStepToolForTest}, "
                    + $"FirstMenu='{shellHost.WorkspaceSampleFirstStepMenuForTest}'");
            }

            if (shellHost.IsActiveWpfToolWindowVisibleForTest
                || shellHost.IsNativeDocumentActive
                || shellHost.HasNativePreviewResult)
            {
                throw new InvalidOperationException("WPF workspace sample entry must not auto-open a tool or run Preview.");
            }
        }, captureFloatingToolWindow: false, verifyCapture: AssertWorkspaceLoadImageVisibleInCapture);
    }

    private static CaptureResult CaptureShellHostRecipeContextSwitch(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);

        string recipeA = "Smoke_RecipeContext_A_" + Guid.NewGuid().ToString("N");
        string recipeB = "Smoke_RecipeContext_B_" + Guid.NewGuid().ToString("N");
        const string pipelineA = "Inspection_A";
        const string pipelineB = "Inspection_B";
        const int blobMinAreaA = 321;
        const int blobMaxAreaA = 6543;
        const int blobMinAreaB = 4321;
        const int blobMaxAreaB = 8765;
        const double thresholdValueA = 77D;
        const double thresholdMaxValueA = 240D;
        const int thresholdRangeMinB = 45;
        const int thresholdRangeMaxB = 168;

        VisionPipelineStorage.Save(recipeA, CreateRecipeContextSmokePipeline(pipelineA, 1));
        VisionPipelineStorage.SaveActivePipelineName(recipeA, pipelineA);
        VisionPipelineStorage.Save(recipeB, CreateRecipeContextSmokePipeline(pipelineB, 2));
        VisionPipelineStorage.SaveActivePipelineName(recipeB, pipelineB);
        new BlobProperty("Blob_1") { MIN_AREA = blobMinAreaA, MAX_AREA = blobMaxAreaA }.SaveConfig(recipeA);
        new BlobProperty("Blob_1") { MIN_AREA = blobMinAreaB, MAX_AREA = blobMaxAreaB }.SaveConfig(recipeB);
        SaveRecipeToolSettings(recipeA, "Threshold", new ThresholdToolSettings
        {
            Mode = ThresholdToolMode.Threshold,
            Threshold = thresholdValueA,
            MaxValue = thresholdMaxValueA,
            BasicInvert = true
        });
        SaveRecipeToolSettings(recipeB, "Threshold", new ThresholdToolSettings
        {
            Mode = ThresholdToolMode.Range,
            RangeMin = thresholdRangeMinB,
            RangeMax = thresholdRangeMaxB,
            RangeInvert = true
        });

        OpenVisionShellHostView shellHost = CreateShellHost(recipeA, seedMainLayer: false);
        return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
        {
            shellHost.SwitchRecipeContextForTest(recipeA);
            Pump(40);

            AssertRecipeContext(shellHost, recipeA, pipelineA);
            int beforeRuns = shellHost.NativePreviewRunCount;

            shellHost.SwitchRecipeContextForTest(recipeB);
            Pump(60);
            AssertRecipeContext(shellHost, recipeB, pipelineB);

            if (shellHost.NativePreviewRunCount != beforeRuns
                || shellHost.IsActiveWpfToolWindowVisibleForTest
                || shellHost.IsNativeDocumentActive
                || shellHost.HasNativePreviewResult)
            {
                throw new InvalidOperationException(
                    "Recipe context switching must not auto-open a tool or run Preview. "
                    + $"RunsBefore={beforeRuns}, RunsAfter={shellHost.NativePreviewRunCount}, "
                    + $"ToolVisible={shellHost.IsActiveWpfToolWindowVisibleForTest}, "
                    + $"NativeActive={shellHost.IsNativeDocumentActive}, Preview={shellHost.HasNativePreviewResult}");
            }

            shellHost.SwitchRecipeContextForTest(recipeA);
            Pump(40);
            AssertRecipeContext(shellHost, recipeA, pipelineA);

            shellHost.SelectToolForTest(VISION_MENU.Pipeline);
            Pump(80);
            if (!shellHost.IsActiveWpfToolWindowVisibleForTest
                || shellHost.PipelineReviewStepCount != 1
                || !string.Equals(shellHost.PipelineReviewRecipeContextNameForTest, recipeA, StringComparison.Ordinal)
                || !string.Equals(shellHost.PipelineReviewRecipeContextPipelineNameForTest, pipelineA, StringComparison.Ordinal)
                || shellHost.NativePreviewRunCount != beforeRuns
                || shellHost.HasNativePreviewResult)
            {
                throw new InvalidOperationException(
                    "Pipeline Review did not open against the active recipe context without running Preview. "
                    + $"Recipe={shellHost.PipelineReviewRecipeContextNameForTest}, "
                    + $"Pipeline={shellHost.PipelineReviewRecipeContextPipelineNameForTest}, "
                    + $"Steps={shellHost.PipelineReviewStepCount}, RunsBefore={beforeRuns}, "
                    + $"RunsAfter={shellHost.NativePreviewRunCount}, Preview={shellHost.HasNativePreviewResult}");
            }

            shellHost.CloseActiveWpfToolWindowForTest();
            Pump(40);

            int recipeAStepCountBeforeNativeAdd = VisionPipelineStorage.Load(recipeA, pipelineA).Steps.Count;
            int recipeBStepCountBeforeNativeAdd = VisionPipelineStorage.Load(recipeB, pipelineB).Steps.Count;

            shellHost.SwitchRecipeContextForTest(recipeB);
            Pump(40);
            AssertRecipeContext(shellHost, recipeB, pipelineB);

            shellHost.SelectToolForTest(VISION_MENU.Blob);
            Pump(80);
            if (!shellHost.IsNativeDocumentActive
                || !string.Equals(shellHost.ActiveNativeRecipeContextNameForTest, recipeB, StringComparison.Ordinal)
                || !string.Equals(shellHost.ActiveNativeRecipeContextPipelineNameForTest, pipelineB, StringComparison.Ordinal))
            {
                throw new InvalidOperationException(
                    "Native tool document did not receive the active recipe context. "
                    + $"Recipe={shellHost.ActiveNativeRecipeContextNameForTest}, "
                    + $"Pipeline={shellHost.ActiveNativeRecipeContextPipelineNameForTest}, "
                    + $"Expected={recipeB}/{pipelineB}");
            }

            int beforeNativeAddRuns = shellHost.NativePreviewRunCount;
            VisionPipelineStep addedStep = shellHost.AddActiveNativePipelineStepForTest();
            Pump(40);

            int recipeAStepCountAfterNativeAdd = VisionPipelineStorage.Load(recipeA, pipelineA).Steps.Count;
            int recipeBStepCountAfterNativeAdd = VisionPipelineStorage.Load(recipeB, pipelineB).Steps.Count;
            if (addedStep == null
                || recipeAStepCountAfterNativeAdd != recipeAStepCountBeforeNativeAdd
                || recipeBStepCountAfterNativeAdd != recipeBStepCountBeforeNativeAdd + 1
                || !string.Equals(VisionPipelineStorage.LoadActivePipelineName(recipeB, VisionPipelineAppendService.DefaultPipelineName), pipelineB, StringComparison.Ordinal)
                || shellHost.NativePreviewRunCount != beforeNativeAddRuns
                || shellHost.HasNativePreviewResult)
            {
                throw new InvalidOperationException(
                    "Native Add Pipeline did not stay scoped to the active recipe/pipeline context. "
                    + $"Added={(addedStep == null ? "<null>" : addedStep.Name)}, "
                    + $"A={recipeAStepCountBeforeNativeAdd}->{recipeAStepCountAfterNativeAdd}, "
                    + $"B={recipeBStepCountBeforeNativeAdd}->{recipeBStepCountAfterNativeAdd}, "
                    + $"ActiveB={VisionPipelineStorage.LoadActivePipelineName(recipeB, VisionPipelineAppendService.DefaultPipelineName)}, "
                    + $"RunsBefore={beforeNativeAddRuns}, RunsAfter={shellHost.NativePreviewRunCount}, "
                    + $"Preview={shellHost.HasNativePreviewResult}");
            }
            AssertStepParameter(addedStep, nameof(BlobProperty.MIN_AREA), blobMinAreaB, "Recipe B Blob Add Pipeline");
            AssertStepParameter(addedStep, nameof(BlobProperty.MAX_AREA), blobMaxAreaB, "Recipe B Blob Add Pipeline");

            shellHost.SwitchRecipeContextForTest(recipeA);
            Pump(60);
            AssertRecipeContext(shellHost, recipeA, pipelineA);

            if (shellHost.IsActiveWpfToolWindowVisibleForTest
                || shellHost.IsNativeDocumentActive
                || shellHost.HasNativePreviewResult)
            {
                throw new InvalidOperationException(
                    "Recipe switch after a native PropertyGrid tool must close active tool documents without leaving stale preview state. "
                    + $"ToolVisible={shellHost.IsActiveWpfToolWindowVisibleForTest}, "
                    + $"NativeActive={shellHost.IsNativeDocumentActive}, Preview={shellHost.HasNativePreviewResult}");
            }

            shellHost.SelectToolForTest(VISION_MENU.Blob);
            Pump(80);
            if (!shellHost.IsNativeDocumentActive
                || !string.Equals(shellHost.ActiveNativeRecipeContextNameForTest, recipeA, StringComparison.Ordinal)
                || !string.Equals(shellHost.ActiveNativeRecipeContextPipelineNameForTest, pipelineA, StringComparison.Ordinal))
            {
                throw new InvalidOperationException(
                    "Native tool document did not recreate against recipe A after switching back. "
                    + $"Recipe={shellHost.ActiveNativeRecipeContextNameForTest}, "
                    + $"Pipeline={shellHost.ActiveNativeRecipeContextPipelineNameForTest}, "
                    + $"Expected={recipeA}/{pipelineA}");
            }

            int beforeRecipeAAddRuns = shellHost.NativePreviewRunCount;
            VisionPipelineStep addedRecipeAStep = shellHost.AddActiveNativePipelineStepForTest();
            Pump(40);

            int recipeAStepCountAfterRecipeAAdd = VisionPipelineStorage.Load(recipeA, pipelineA).Steps.Count;
            int recipeBStepCountAfterRecipeAAdd = VisionPipelineStorage.Load(recipeB, pipelineB).Steps.Count;
            if (addedRecipeAStep == null
                || recipeAStepCountAfterRecipeAAdd != recipeAStepCountBeforeNativeAdd + 1
                || recipeBStepCountAfterRecipeAAdd != recipeBStepCountAfterNativeAdd
                || !string.Equals(VisionPipelineStorage.LoadActivePipelineName(recipeA, VisionPipelineAppendService.DefaultPipelineName), pipelineA, StringComparison.Ordinal)
                || shellHost.NativePreviewRunCount != beforeRecipeAAddRuns
                || shellHost.HasNativePreviewResult)
            {
                throw new InvalidOperationException(
                    "Native Add Pipeline after switching back to recipe A did not stay scoped to recipe A. "
                    + $"Added={(addedRecipeAStep == null ? "<null>" : addedRecipeAStep.Name)}, "
                    + $"A={recipeAStepCountBeforeNativeAdd}->{recipeAStepCountAfterRecipeAAdd}, "
                    + $"B={recipeBStepCountAfterNativeAdd}->{recipeBStepCountAfterRecipeAAdd}, "
                    + $"ActiveA={VisionPipelineStorage.LoadActivePipelineName(recipeA, VisionPipelineAppendService.DefaultPipelineName)}, "
                    + $"RunsBefore={beforeRecipeAAddRuns}, RunsAfter={shellHost.NativePreviewRunCount}, "
                    + $"Preview={shellHost.HasNativePreviewResult}");
            }
            AssertStepParameter(addedRecipeAStep, nameof(BlobProperty.MIN_AREA), blobMinAreaA, "Recipe A Blob Add Pipeline");
            AssertStepParameter(addedRecipeAStep, nameof(BlobProperty.MAX_AREA), blobMaxAreaA, "Recipe A Blob Add Pipeline");

            shellHost.SwitchRecipeContextForTest(recipeB);
            Pump(60);
            AssertRecipeContext(shellHost, recipeB, pipelineB);

            int recipeAStepCountBeforeThresholdBAdd = VisionPipelineStorage.Load(recipeA, pipelineA).Steps.Count;
            int recipeBStepCountBeforeThresholdBAdd = VisionPipelineStorage.Load(recipeB, pipelineB).Steps.Count;

            shellHost.SelectToolForTest(VISION_MENU.Threshold);
            Pump(80);
            if (!shellHost.IsNativeDocumentActive
                || !string.Equals(shellHost.ActiveNativeRecipeContextNameForTest, recipeB, StringComparison.Ordinal)
                || !string.Equals(shellHost.ActiveNativeRecipeContextPipelineNameForTest, pipelineB, StringComparison.Ordinal))
            {
                throw new InvalidOperationException(
                    "Threshold native tool document did not recreate against recipe B. "
                    + $"Recipe={shellHost.ActiveNativeRecipeContextNameForTest}, "
                    + $"Pipeline={shellHost.ActiveNativeRecipeContextPipelineNameForTest}, "
                    + $"Expected={recipeB}/{pipelineB}");
            }

            int beforeThresholdBAddRuns = shellHost.NativePreviewRunCount;
            VisionPipelineStep addedThresholdBStep = shellHost.AddActiveNativePipelineStepForTest();
            Pump(40);

            int recipeAStepCountAfterThresholdBAdd = VisionPipelineStorage.Load(recipeA, pipelineA).Steps.Count;
            int recipeBStepCountAfterThresholdBAdd = VisionPipelineStorage.Load(recipeB, pipelineB).Steps.Count;
            if (addedThresholdBStep == null
                || recipeAStepCountAfterThresholdBAdd != recipeAStepCountBeforeThresholdBAdd
                || recipeBStepCountAfterThresholdBAdd != recipeBStepCountBeforeThresholdBAdd + 1
                || shellHost.NativePreviewRunCount != beforeThresholdBAddRuns
                || shellHost.HasNativePreviewResult)
            {
                throw new InvalidOperationException(
                    "Recipe B Threshold Add Pipeline did not stay scoped to recipe B or triggered Preview. "
                    + $"Added={(addedThresholdBStep == null ? "<null>" : addedThresholdBStep.Name)}, "
                    + $"A={recipeAStepCountBeforeThresholdBAdd}->{recipeAStepCountAfterThresholdBAdd}, "
                    + $"B={recipeBStepCountBeforeThresholdBAdd}->{recipeBStepCountAfterThresholdBAdd}, "
                    + $"RunsBefore={beforeThresholdBAddRuns}, RunsAfter={shellHost.NativePreviewRunCount}, "
                    + $"Preview={shellHost.HasNativePreviewResult}");
            }
            AssertStepParameter(addedThresholdBStep, nameof(ThresholdToolProperty.Mode), ThresholdToolMode.Range, "Recipe B Threshold Add Pipeline");
            AssertStepParameter(addedThresholdBStep, nameof(ThresholdToolProperty.RangeMin), thresholdRangeMinB, "Recipe B Threshold Add Pipeline");
            AssertStepParameter(addedThresholdBStep, nameof(ThresholdToolProperty.RangeMax), thresholdRangeMaxB, "Recipe B Threshold Add Pipeline");

            shellHost.SwitchRecipeContextForTest(recipeA);
            Pump(60);
            AssertRecipeContext(shellHost, recipeA, pipelineA);

            int recipeAStepCountBeforeThresholdAAdd = VisionPipelineStorage.Load(recipeA, pipelineA).Steps.Count;
            int recipeBStepCountBeforeThresholdAAdd = VisionPipelineStorage.Load(recipeB, pipelineB).Steps.Count;

            shellHost.SelectToolForTest(VISION_MENU.Threshold);
            Pump(80);
            if (!shellHost.IsNativeDocumentActive
                || !string.Equals(shellHost.ActiveNativeRecipeContextNameForTest, recipeA, StringComparison.Ordinal)
                || !string.Equals(shellHost.ActiveNativeRecipeContextPipelineNameForTest, pipelineA, StringComparison.Ordinal))
            {
                throw new InvalidOperationException(
                    "Threshold native tool document did not recreate against recipe A. "
                    + $"Recipe={shellHost.ActiveNativeRecipeContextNameForTest}, "
                    + $"Pipeline={shellHost.ActiveNativeRecipeContextPipelineNameForTest}, "
                    + $"Expected={recipeA}/{pipelineA}");
            }

            int beforeThresholdAAddRuns = shellHost.NativePreviewRunCount;
            VisionPipelineStep addedThresholdAStep = shellHost.AddActiveNativePipelineStepForTest();
            Pump(40);

            int recipeAStepCountAfterThresholdAAdd = VisionPipelineStorage.Load(recipeA, pipelineA).Steps.Count;
            int recipeBStepCountAfterThresholdAAdd = VisionPipelineStorage.Load(recipeB, pipelineB).Steps.Count;
            if (addedThresholdAStep == null
                || recipeAStepCountAfterThresholdAAdd != recipeAStepCountBeforeThresholdAAdd + 1
                || recipeBStepCountAfterThresholdAAdd != recipeBStepCountBeforeThresholdAAdd
                || shellHost.NativePreviewRunCount != beforeThresholdAAddRuns
                || shellHost.HasNativePreviewResult)
            {
                throw new InvalidOperationException(
                    "Recipe A Threshold Add Pipeline did not stay scoped to recipe A or triggered Preview. "
                    + $"Added={(addedThresholdAStep == null ? "<null>" : addedThresholdAStep.Name)}, "
                    + $"A={recipeAStepCountBeforeThresholdAAdd}->{recipeAStepCountAfterThresholdAAdd}, "
                    + $"B={recipeBStepCountBeforeThresholdAAdd}->{recipeBStepCountAfterThresholdAAdd}, "
                    + $"RunsBefore={beforeThresholdAAddRuns}, RunsAfter={shellHost.NativePreviewRunCount}, "
                    + $"Preview={shellHost.HasNativePreviewResult}");
            }
            AssertStepParameter(addedThresholdAStep, nameof(ThresholdToolProperty.Mode), ThresholdToolMode.Threshold, "Recipe A Threshold Add Pipeline");
            AssertStepParameter(addedThresholdAStep, nameof(ThresholdToolProperty.Threshold), thresholdValueA, "Recipe A Threshold Add Pipeline");
            AssertStepParameter(addedThresholdAStep, nameof(ThresholdToolProperty.MaxValue), thresholdMaxValueA, "Recipe A Threshold Add Pipeline");

            AssertVisibleAutomationIds(
                shellHost,
                "WPF recipe context status",
                "HostRecipeSelector");
            AssertHiddenAutomationIds(shellHost, "WPF recipe context chip", "HostRecipeContext");
            AssertVisibleTextDoesNotContain(shellHost, "WPF recipe context scope hint", "범위:");
        }, captureFloatingToolWindow: false);
    }

    private static CaptureResult CaptureShellHostRecipeOutputRouteIsolation(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);

        string recipeA = "Smoke_RecipeRoute_A_" + Guid.NewGuid().ToString("N");
        string recipeB = "Smoke_RecipeRoute_B_" + Guid.NewGuid().ToString("N");
        const string pipelineA = "OutputRoute_A";
        const string pipelineB = "OutputRoute_B";
        const string outputA = "RecipeA_Output";
        const string outputB = "RecipeB_Output";

        VisionPipelineStorage.Save(recipeA, CreateRecipeContextSmokePipeline(pipelineA, 1));
        VisionPipelineStorage.SaveActivePipelineName(recipeA, pipelineA);
        VisionPipelineStorage.Save(recipeB, CreateRecipeContextSmokePipeline(pipelineB, 1));
        VisionPipelineStorage.SaveActivePipelineName(recipeB, pipelineB);

        OpenVisionShellHostView shellHost = CreateShellHost(recipeA, seedMainLayer: false);
        using Bitmap mainBitmap = CreateWorkspaceSeedSmokeBitmap();
        using Bitmap outputABitmap = CreateDockingPanelSmokeBitmap(5);
        using Bitmap outputBBitmap = CreateDockingPanelSmokeBitmap(6);

        return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
        {
            shellHost.SwitchRecipeContextForTest(recipeA);
            Pump(40);
            AssertRecipeContext(shellHost, recipeA, pipelineA);
            shellHost.SetMainLayerImageForTest(mainBitmap);
            EnsureRecipeRouteLayer(shellHost, outputA, outputABitmap);
            EnsureRecipeRouteLayer(shellHost, outputB, outputBBitmap);
            ActivateMainOrThrow(shellHost, "Recipe route isolation A setup");

            int previewRunsBefore = shellHost.NativePreviewRunCount;
            int recipeAStepsBefore = VisionPipelineStorage.Load(recipeA, pipelineA).Steps.Count;
            int recipeBStepsBefore = VisionPipelineStorage.Load(recipeB, pipelineB).Steps.Count;

            shellHost.SelectToolForTest(VISION_MENU.Threshold);
            Pump(80);
            SelectThresholdOutputLayerForRecipeSmoke(shellHost, outputA, recipeA);
            VisionPipelineStep addedA = shellHost.AddActiveNativePipelineStepForTest();
            Pump(30);

            int recipeAStepsAfterA = VisionPipelineStorage.Load(recipeA, pipelineA).Steps.Count;
            int recipeBStepsAfterA = VisionPipelineStorage.Load(recipeB, pipelineB).Steps.Count;
            if (addedA == null
                || !string.Equals(addedA.OutputLayer, outputA, StringComparison.Ordinal)
                || recipeAStepsAfterA != recipeAStepsBefore + 1
                || recipeBStepsAfterA != recipeBStepsBefore
                || shellHost.NativePreviewRunCount != previewRunsBefore
                || shellHost.HasNativePreviewResult)
            {
                throw new InvalidOperationException(
                    "Recipe A selected output route was not written to recipe A Add Pipeline without Preview side effects. "
                    + $"AddedOutput={addedA?.OutputLayer}, A={recipeAStepsBefore}->{recipeAStepsAfterA}, "
                    + $"B={recipeBStepsBefore}->{recipeBStepsAfterA}, RunsBefore={previewRunsBefore}, "
                    + $"RunsAfter={shellHost.NativePreviewRunCount}, Preview={shellHost.HasNativePreviewResult}");
            }

            shellHost.SwitchRecipeContextForTest(recipeB);
            Pump(60);
            AssertRecipeContext(shellHost, recipeB, pipelineB);
            if (shellHost.IsActiveWpfToolWindowVisibleForTest
                || shellHost.IsNativeDocumentActive
                || shellHost.HasNativePreviewResult)
            {
                throw new InvalidOperationException(
                    "Recipe switch after selecting an output route must close the active tool without stale Preview state. "
                    + $"ToolVisible={shellHost.IsActiveWpfToolWindowVisibleForTest}, NativeActive={shellHost.IsNativeDocumentActive}, Preview={shellHost.HasNativePreviewResult}");
            }

            shellHost.SetMainLayerImageForTest(mainBitmap);
            EnsureRecipeRouteLayer(shellHost, outputB, outputBBitmap);
            ActivateMainOrThrow(shellHost, "Recipe route isolation B setup");
            shellHost.SelectToolForTest(VISION_MENU.Threshold);
            Pump(80);

            ComboBox outputLayerCombo = FindFloatingComboBox("cbOutputLayer");
            if (string.Equals(GetComboBoxCurrentText(outputLayerCombo), outputA, StringComparison.OrdinalIgnoreCase)
                || string.Equals(shellHost.ActiveNativeRouteOutputLayerNameForTest, outputA, StringComparison.OrdinalIgnoreCase))
            {
                throw new InvalidOperationException(
                    "Recipe B opened with Recipe A's selected output route. "
                    + $"OutputCombo={GetComboBoxCurrentText(outputLayerCombo)}, Route={shellHost.ActiveNativeRouteOutputLayerNameForTest}");
            }

            int recipeAStepsBeforeB = VisionPipelineStorage.Load(recipeA, pipelineA).Steps.Count;
            int recipeBStepsBeforeB = VisionPipelineStorage.Load(recipeB, pipelineB).Steps.Count;
            SelectThresholdOutputLayerForRecipeSmoke(shellHost, outputB, recipeB);
            VisionPipelineStep addedB = shellHost.AddActiveNativePipelineStepForTest();
            Pump(30);

            int recipeAStepsAfterB = VisionPipelineStorage.Load(recipeA, pipelineA).Steps.Count;
            int recipeBStepsAfterB = VisionPipelineStorage.Load(recipeB, pipelineB).Steps.Count;
            if (addedB == null
                || !string.Equals(addedB.OutputLayer, outputB, StringComparison.Ordinal)
                || recipeAStepsAfterB != recipeAStepsBeforeB
                || recipeBStepsAfterB != recipeBStepsBeforeB + 1
                || shellHost.NativePreviewRunCount != previewRunsBefore
                || shellHost.HasNativePreviewResult)
            {
                throw new InvalidOperationException(
                    "Recipe B selected output route was not written to recipe B Add Pipeline without Preview side effects. "
                    + $"AddedOutput={addedB?.OutputLayer}, A={recipeAStepsBeforeB}->{recipeAStepsAfterB}, "
                    + $"B={recipeBStepsBeforeB}->{recipeBStepsAfterB}, RunsBefore={previewRunsBefore}, "
                    + $"RunsAfter={shellHost.NativePreviewRunCount}, Preview={shellHost.HasNativePreviewResult}");
            }

            shellHost.SwitchRecipeContextForTest(recipeA);
            Pump(60);
            AssertRecipeContext(shellHost, recipeA, pipelineA);
            shellHost.SelectToolForTest(VISION_MENU.Threshold);
            Pump(80);
            outputLayerCombo = FindFloatingComboBox("cbOutputLayer");
            if (string.Equals(GetComboBoxCurrentText(outputLayerCombo), outputB, StringComparison.OrdinalIgnoreCase)
                || string.Equals(shellHost.ActiveNativeRouteOutputLayerNameForTest, outputB, StringComparison.OrdinalIgnoreCase))
            {
                throw new InvalidOperationException(
                    "Recipe A reopened with Recipe B's selected output route. "
                    + $"OutputCombo={GetComboBoxCurrentText(outputLayerCombo)}, Route={shellHost.ActiveNativeRouteOutputLayerNameForTest}");
            }
        }, captureFloatingToolWindow: false);
    }

    private static void EnsureRecipeRouteLayer(OpenVisionShellHostView shellHost, string layerTitle, Bitmap image)
    {
        if (shellHost.HasLayerForTest(layerTitle))
        {
            if (!shellHost.SetLayerImageForTest(layerTitle, image))
            {
                throw new InvalidOperationException($"Recipe route layer {layerTitle} could not be refreshed.");
            }

            return;
        }

        if (!shellHost.AddLayerImageForTest(layerTitle, image))
        {
            throw new InvalidOperationException($"Recipe route layer {layerTitle} could not be created.");
        }
    }

    private static void ActivateMainOrThrow(OpenVisionShellHostView shellHost, string name)
    {
        if (!shellHost.ActivateHostLayerForTest("Main"))
        {
            throw new InvalidOperationException(name + " could not activate Main.");
        }
    }

    private static void SelectThresholdOutputLayerForRecipeSmoke(OpenVisionShellHostView shellHost, string outputLayer, string recipeName)
    {
        ComboBox inputLayerCombo = FindFloatingComboBox("cbInputLayer");
        ComboBox outputLayerCombo = FindFloatingComboBox("cbOutputLayer");
        if (!ComboBoxContainsText(outputLayerCombo, outputLayer))
        {
            throw new InvalidOperationException($"Threshold output combo for {recipeName} does not expose {outputLayer}.");
        }

        SelectComboBoxItemText(outputLayerCombo, outputLayer, recipeName + " Threshold output combo");
        Pump(20);
        inputLayerCombo = FindFloatingComboBox("cbInputLayer");
        outputLayerCombo = FindFloatingComboBox("cbOutputLayer");
        if (!string.Equals(GetComboBoxCurrentText(inputLayerCombo), "Main", StringComparison.OrdinalIgnoreCase)
            || !string.Equals(GetComboBoxCurrentText(outputLayerCombo), outputLayer, StringComparison.OrdinalIgnoreCase)
            || !string.Equals(shellHost.ActiveNativeRouteInputLayerNameForTest, "Main", StringComparison.OrdinalIgnoreCase)
            || !string.Equals(shellHost.ActiveNativeRouteOutputLayerNameForTest, outputLayer, StringComparison.OrdinalIgnoreCase)
            || !string.Equals(shellHost.ActiveHostLayerTitle, "Main", StringComparison.OrdinalIgnoreCase))
        {
            throw new InvalidOperationException(
                $"Threshold route selection for {recipeName} did not preserve Main input and selected output. "
                + $"InputCombo={GetComboBoxCurrentText(inputLayerCombo)}, OutputCombo={GetComboBoxCurrentText(outputLayerCombo)}, "
                + $"Input={shellHost.ActiveNativeRouteInputLayerNameForTest}, Output={shellHost.ActiveNativeRouteOutputLayerNameForTest}, "
                + $"Active={shellHost.ActiveHostLayerTitle}");
        }
    }

    private static VisionPipeline CreateRecipeContextSmokePipeline(string name, int stepCount)
    {
        VisionPipeline pipeline = new() { Name = name };
        for (int index = 0; index < stepCount; index++)
        {
            pipeline.Steps.Add(new VisionPipelineStep
            {
                Name = $"{name}_Step_{index + 1}",
                ToolType = "Threshold",
                InputLayer = index == 0 ? "Main" : $"{name}_Preview_{index}",
                OutputLayer = $"{name}_Preview_{index + 1}"
            });
        }

        return pipeline;
    }

    private static VisionPipeline CreateRecipeFixturePropertyPipeline()
    {
        VisionPipeline pipeline = new() { Name = "Fixture_PropertyGrid" };
        VisionPipelineStep matching = new()
        {
            Name = "01 Locate Fixture",
            ToolType = "Matching",
            InputLayer = "Main",
            OutputLayer = "FixtureMatch"
        };
        matching.Parameters["Name"] = "FixtureMatch";
        matching.Parameters["NUM_MATCH"] = "1";
        matching.Parameters["USE_FIND_ANGLE"] = "true";
        matching.Parameters["FIND_ANGLE_MIN"] = "-5";
        matching.Parameters["FIND_ANGLE_MAX"] = "5";
        matching.Parameters["FIND_ANGLE"] = "0.5";
        matching.Parameters["USE_FIND_SCALE"] = "true";
        matching.Parameters["FIND_SCALE_MIN"] = "0.75";
        matching.Parameters["FIND_SCALE_MAX"] = "1.35";
        matching.Parameters["FIND_SCALE_STEP"] = "0.05";
        matching.Parameters["USE_AS_FIXTURE_FRAME"] = "true";
        matching.Parameters["FIXTURE_FRAME_NAME"] = "PartFrame";
        matching.Parameters["FIXTURE_REFERENCE_X"] = "60";
        matching.Parameters["FIXTURE_REFERENCE_Y"] = "70";
        matching.Parameters["FIXTURE_REFERENCE_ANGLE"] = "0";
        matching.Parameters["FIXTURE_REFERENCE_SCALE"] = "1";
        matching.Parameters["FIXTURE_MAX_ANGLE_DELTA"] = "2";
        matching.Parameters["FIXTURE_MIN_SCALE_RATIO"] = "0.8";
        matching.Parameters["FIXTURE_MAX_SCALE_RATIO"] = "1.8";
        matching.Parameters["FIXTURE_REFERENCE_IMAGE_WIDTH"] = "640";
        matching.Parameters["FIXTURE_REFERENCE_IMAGE_HEIGHT"] = "480";
        pipeline.Steps.Add(matching);

        VisionPipelineStep normalize = new()
        {
            Name = "02 Normalize Device Image",
            ToolType = "RotateScale",
            InputLayer = "Main",
            OutputLayer = "DeviceAligned"
        };
        normalize.Parameters["Name"] = "DeviceNormalize";
        normalize.Parameters["Angle"] = "0";
        normalize.Parameters["ScaleXPercent"] = "100";
        normalize.Parameters["ScaleYPercent"] = "100";
        normalize.Parameters["Interpolation"] = "Linear";
        normalize.Parameters["BorderType"] = "Constant";
        normalize.Parameters["USE_FIXTURE_FRAME"] = "true";
        normalize.Parameters["FIXTURE_FRAME_NAME"] = "PartFrame";
        normalize.Parameters["FIXTURE_APPLY_MODE"] = "NormalizeImage";
        normalize.Parameters["FIXTURE_MIN_VALID_PIXEL_RATIO"] = "0.25";
        normalize.Parameters["ALLOW_BRANCH_INPUT"] = "true";
        pipeline.Steps.Add(normalize);
        return pipeline;
    }

    private static CaptureResult CaptureShellHostRecipeFixtureProperties(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        CleanupTransientRecipeWorkspaces();

        string recipeName = "Smoke_RecipeFixtureProperties_" + Guid.NewGuid().ToString("N").Substring(0, 12);
        VisionPipeline pipeline = CreateRecipeFixturePropertyPipeline();
        AssertFixturePropertyMapperRoundTrip(pipeline);
        VisionPipelineStorage.Save(recipeName, pipeline);
        VisionPipeline reloadedPipeline = VisionPipelineStorage.Load(recipeName, pipeline.Name)
            ?? throw new InvalidOperationException("Fixture PropertyGrid pipeline did not reload after XML save.");
        AssertFixturePropertyMapperRoundTrip(reloadedPipeline);
        VisionPipelineStorage.SaveActivePipelineName(recipeName, pipeline.Name);

        OpenVisionShellHostView shellHost = CreateShellHost(recipeName, seedMainLayer: false);
        return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
        {
            ToggleButton recipeManagerButton = FindNamedVisualChild<ToggleButton>(shellHost, "btnHostRecipeManager")
                ?? throw new InvalidOperationException("Fixture PropertyGrid smoke could not find Recipe Manager.");
            recipeManagerButton.IsChecked = true;
            Pump(100);

            TabItem pipelineTab = FindNamedVisualChild<TabItem>(shellHost, "tabRecipePipeline")
                ?? throw new InvalidOperationException("Fixture PropertyGrid smoke could not find the Pipeline tab.");
            pipelineTab.IsSelected = true;
            Pump(40);
            TabItem xmlStepsTab = FindNamedVisualChild<TabItem>(shellHost, "tabRecipePipelineXmlSteps")
                ?? throw new InvalidOperationException("Fixture PropertyGrid smoke could not find the XML/steps tab.");
            xmlStepsTab.IsSelected = true;
            Pump(40);

            IReadOnlyList<OpenVisionRecipePipelineStepPreview> steps = shellHost.RecipeCommands.SelectedRecipeSummary.PipelinePreviewSteps;
            if (steps.Count != 2)
            {
                throw new InvalidOperationException($"Fixture PropertyGrid smoke expected two steps but found {steps.Count}.");
            }

            int previewRunsBefore = shellHost.NativePreviewRunCount;
            CaptureRecipeFixturePropertyStep(shellHost, steps[1], outputPath, "normalize-image-fixture-property-grid.png");
            CaptureRecipeFixturePropertyStep(shellHost, steps[0], outputPath, "matching-fixture-property-grid.png");
            CaptureRecipeFixturePropertyStep(shellHost, steps[1], outputPath, "normalize-image-fixture-property-grid.png");
            if (shellHost.NativePreviewRunCount != previewRunsBefore)
            {
                throw new InvalidOperationException(
                    "Loading Fixture PropertyGrid parameters triggered Preview/Run. "
                    + $"RunsBefore={previewRunsBefore}, RunsAfter={shellHost.NativePreviewRunCount}");
            }
        }, captureFloatingToolWindow: false, captureScreen: true);
    }

    private static CaptureResult CaptureShellHostRecipeReferenceDifferenceProperties(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.English, false);
        CleanupTransientRecipeWorkspaces();

        string recipeName = "Smoke_RecipeReferenceDifference_" + Guid.NewGuid().ToString("N").Substring(0, 12);
        string referenceRoot = Path.Combine(Directory.GetCurrentDirectory(), "Sample", "EasyMatch");
        VisionPipeline pipeline = new() { Name = "ReferenceDifference_PropertyGrid" };
        VisionPipelineStep step = new()
        {
            Name = "01 Registered Good Reference Difference",
            ToolType = "ReferenceDifference",
            InputLayer = "Main",
            OutputLayer = "Reference_Difference_Review",
            UseAcceptance = true,
            AcceptanceMetricName = "ResultCount",
            UseAcceptanceMetricMinimum = true,
            AcceptanceMetricMinimum = 0,
            UseAcceptanceMetricMaximum = true,
            AcceptanceMetricMaximum = 0
        };
        for (int index = 1; index <= 4; index++)
        {
            step.Parameters["ReferencePath" + index.ToString(CultureInfo.InvariantCulture)] =
                Path.Combine(referenceRoot, "Die Pad " + index.ToString(CultureInfo.InvariantCulture) + ".bmp");
        }

        step.Parameters["DifferenceThreshold"] = "35";
        step.Parameters["MinimumDefectArea"] = "80";
        step.Parameters["MaximumDefectArea"] = "20000";
        step.Parameters["MorphologyKernel"] = "3";
        step.Parameters["IgnoreBorder"] = "8";
        step.Parameters["OrbFeatures"] = "1600";
        step.Parameters["MatchRatio"] = "0.75";
        step.Parameters["MinimumInliers"] = "12";
        step.Parameters["RansacThreshold"] = "3";
        pipeline.Steps.Add(step);

        object mappedProperty = VisionPipelineStepPropertyMapper.CreateProperty(step)
            ?? throw new InvalidOperationException("ReferenceDifference PropertyGrid mapper returned no property object.");
        VisionPipelineStep roundTrip = new()
        {
            Name = step.Name,
            ToolType = step.ToolType,
            InputLayer = step.InputLayer,
            OutputLayer = step.OutputLayer
        };
        if (!VisionPipelineStepPropertyMapper.ApplyProperty(roundTrip, mappedProperty)
            || !string.Equals(roundTrip.Parameters["ReferencePath4"], step.Parameters["ReferencePath4"], StringComparison.OrdinalIgnoreCase)
            || !string.Equals(roundTrip.Parameters["DifferenceThreshold"], "35", StringComparison.Ordinal))
        {
            throw new InvalidOperationException("ReferenceDifference PropertyGrid mapper did not round-trip its parameters.");
        }

        VisionPipelineStorage.Save(recipeName, pipeline);
        VisionPipelineStorage.SaveActivePipelineName(recipeName, pipeline.Name);
        OpenVisionShellHostView shellHost = CreateShellHost(recipeName, seedMainLayer: false);
        try
        {
            return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
            {
                ToggleButton recipeManagerButton = FindNamedVisualChild<ToggleButton>(shellHost, "btnHostRecipeManager")
                    ?? throw new InvalidOperationException("ReferenceDifference PropertyGrid smoke could not find Recipe Manager.");
                recipeManagerButton.IsChecked = true;
                Pump(100);

                FindNamedVisualChild<TabItem>(shellHost, "tabRecipePipeline")!.IsSelected = true;
                Pump(40);
                FindNamedVisualChild<TabItem>(shellHost, "tabRecipePipelineXmlSteps")!.IsSelected = true;
                Pump(40);

                OpenVisionRecipePipelineStepPreview preview = shellHost.RecipeCommands.SelectedRecipeSummary.PipelinePreviewSteps.Single();
                shellHost.RecipeCommands.SelectedPipelinePreviewStep = preview;
                shellHost.RecipeCommands.LoadSelectedStepParametersCommand.Execute(null);
                Pump(180);

                FrameworkElement propertyGridHost = FindVisualChildren<FrameworkElement>(shellHost)
                    .FirstOrDefault(item => item.IsVisible && string.Equals(
                        AutomationProperties.GetAutomationId(item),
                        "HostRecipeSelectedStepPropertyGridHost",
                        StringComparison.Ordinal))
                    ?? throw new InvalidOperationException("ReferenceDifference PropertyGrid host was not visible.");
                propertyGridHost.BringIntoView();
                propertyGridHost.UpdateLayout();
                Pump(80);

                System.Windows.Controls.WpfPropertyGrid.PropertyGrid grid =
                    FindVisualChildren<System.Windows.Controls.WpfPropertyGrid.PropertyGrid>(propertyGridHost)
                        .FirstOrDefault(item => item.IsVisible && item.SelectedObject != null)
                    ?? throw new InvalidOperationException("ReferenceDifference PropertyGrid did not load.");
                string[] requiredProperties =
                {
                    "ReferencePath1", "ReferencePath2", "ReferencePath3", "ReferencePath4",
                    "DifferenceThreshold", "MinimumDefectArea", "MaximumDefectArea", "MorphologyKernel",
                    "IgnoreBorder", "OrbFeatures", "MatchRatio", "MinimumInliers", "RansacThreshold"
                };
                PropertyDescriptorCollection descriptors = TypeDescriptor.GetProperties(grid.SelectedObject);
                string[] missing = requiredProperties.Where(name => descriptors.Find(name, true) == null).ToArray();
                if (missing.Length > 0)
                {
                    throw new InvalidOperationException(
                        "ReferenceDifference PropertyGrid missed parameters: " + string.Join(",", missing));
                }

                TextBox searchTextBox = GetActivePropertyGridSearchTextBox(grid, "ReferenceDifference recipe step");
                searchTextBox.Text = "Reference Path";
                searchTextBox.GetBindingExpression(TextBox.TextProperty)?.UpdateSource();
                grid.UpdateLayout();
                Pump(60);
                if (grid.IsSearchEmptyMessageVisibleForTest || shellHost.NativePreviewRunCount != 0)
                {
                    throw new InvalidOperationException(
                        "ReferenceDifference PropertyGrid search failed or loading parameters triggered Preview/Run.");
                }
            }, captureFloatingToolWindow: false, captureScreen: true);
        }
        finally
        {
            RecipeWorkspaceService.DeleteVisionWorkspace(recipeName);
        }
    }

    private static CaptureResult CaptureShellHostRecipePinArrayGapProperties(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.English, false);
        CleanupTransientRecipeWorkspaces();

        string recipeName = "Smoke_RecipePinPitch_" + Guid.NewGuid().ToString("N").Substring(0, 12);
        VisionPipeline pipeline = new() { Name = "PinArrayGap_PropertyGrid" };
        VisionPipelineStep step = new()
        {
            Name = "01 Pin Center Pitch",
            ToolType = "PinArrayGap",
            InputLayer = "Main",
            OutputLayer = "PinPitch_Result",
            AcceptanceMetricName = "PitchPxRange",
            UseAcceptance = true,
            UseAcceptanceMetricMaximum = true,
            AcceptanceMetricMaximum = 2D
        };
        step.Parameters["MeasurementMode"] = "CenterPitch";
        step.Parameters["USE_ROI"] = "true";
        step.Parameters["CvROI"] = "50,50,540,140";
        step.Parameters["DarkThreshold"] = "128";
        step.Parameters["MinDarkCoverageRatio"] = "0.55";
        step.Parameters["MinPinWidth"] = "5";
        step.Parameters["MaxPinBreakWidth"] = "2";
        step.Parameters["MinGapWidth"] = "3";
        step.Parameters["ALLOW_BRANCH_INPUT"] = "true";
        pipeline.Steps.Add(step);

        object mappedProperty = VisionPipelineStepPropertyMapper.CreateProperty(step)
            ?? throw new InvalidOperationException("PinArrayGap PropertyGrid mapper returned no property object.");
        VisionPipelineStep roundTrip = new()
        {
            Name = step.Name,
            ToolType = step.ToolType,
            InputLayer = step.InputLayer,
            OutputLayer = step.OutputLayer
        };
        if (!VisionPipelineStepPropertyMapper.ApplyProperty(roundTrip, mappedProperty)
            || !string.Equals(roundTrip.Parameters.GetValueOrDefault("MeasurementMode"), "CenterPitch", StringComparison.Ordinal)
            || !string.Equals(roundTrip.Parameters.GetValueOrDefault("CvROI"), "50,50,540,140", StringComparison.Ordinal)
            || !string.Equals(roundTrip.Parameters.GetValueOrDefault("ALLOW_BRANCH_INPUT"), "true", StringComparison.OrdinalIgnoreCase))
        {
            throw new InvalidOperationException("PinArrayGap PropertyGrid direct round trip lost mode, ROI, or an unrepresented parameter.");
        }

        VisionPipelineStep aliasStep = new()
        {
            Name = "Adjacent alias",
            ToolType = "AdjacentPinGapTool",
            InputLayer = "Main",
            OutputLayer = "Alias_Result"
        };
        aliasStep.Parameters["UnrepresentedParameter"] = "preserved";
        object aliasProperty = VisionPipelineStepPropertyMapper.CreateProperty(aliasStep)
            ?? throw new InvalidOperationException("AdjacentPinGapTool alias returned no property object.");
        VisionPipelineStep aliasRoundTrip = new();
        if (!VisionPipelineStepPropertyMapper.ApplyProperty(aliasRoundTrip, aliasProperty)
            || !string.Equals(aliasRoundTrip.ToolType, "AdjacentPinGapTool", StringComparison.Ordinal)
            || !string.Equals(aliasRoundTrip.Parameters.GetValueOrDefault("MeasurementMode"), "EdgeGap", StringComparison.Ordinal)
            || !string.Equals(aliasRoundTrip.Parameters.GetValueOrDefault("DarkThreshold"), "128", StringComparison.Ordinal)
            || !string.Equals(aliasRoundTrip.Parameters.GetValueOrDefault("UnrepresentedParameter"), "preserved", StringComparison.Ordinal))
        {
            throw new InvalidOperationException("AdjacentPinGapTool alias/default/baseline round trip changed.");
        }

        VisionPipelineStorage.Save(recipeName, pipeline);
        VisionPipelineStorage.SaveActivePipelineName(recipeName, pipeline.Name);
        OpenVisionShellHostView shellHost = CreateShellHost(recipeName, seedMainLayer: false);
        try
        {
            return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
            {
                ToggleButton recipeManagerButton = FindNamedVisualChild<ToggleButton>(shellHost, "btnHostRecipeManager")
                    ?? throw new InvalidOperationException("PinArrayGap PropertyGrid smoke could not find Recipe Manager.");
                recipeManagerButton.IsChecked = true;
                Pump(100);

                FindNamedVisualChild<ToggleButton>(shellHost, "recipeAdvancedReviewToggle")!.IsChecked = true;
                Pump(60);
                FindNamedVisualChild<TabItem>(shellHost, "tabRecipePipeline")!.IsSelected = true;
                Pump(40);
                FindNamedVisualChild<TabItem>(shellHost, "tabRecipePipelineXmlSteps")!.IsSelected = true;
                Pump(40);

                OpenVisionRecipePipelineStepPreview preview = shellHost.RecipeCommands.SelectedRecipeSummary.PipelinePreviewSteps.Single();
                shellHost.RecipeCommands.SelectedPipelinePreviewStep = preview;
                if (!shellHost.RecipeCommands.LoadSelectedStepParametersCommand.CanExecute(null))
                {
                    throw new InvalidOperationException("PinArrayGap PropertyGrid load command remained disabled.");
                }

                shellHost.RecipeCommands.LoadSelectedStepParametersCommand.Execute(null);
                Pump(180);

                FrameworkElement propertyGridHost = FindVisualChildren<FrameworkElement>(shellHost)
                    .FirstOrDefault(item => item.IsVisible && string.Equals(
                        AutomationProperties.GetAutomationId(item),
                        "HostRecipeSelectedStepPropertyGridHost",
                        StringComparison.Ordinal))
                    ?? throw new InvalidOperationException("PinArrayGap PropertyGrid host was not visible.");
                System.Windows.Controls.WpfPropertyGrid.PropertyGrid grid =
                    FindVisualChildren<System.Windows.Controls.WpfPropertyGrid.PropertyGrid>(propertyGridHost)
                        .FirstOrDefault(item => item.IsVisible && item.SelectedObject != null)
                    ?? throw new InvalidOperationException("PinArrayGap PropertyGrid did not load.");
                string[] requiredProperties =
                {
                    "MeasurementMode", "UseRoi", "Roi", "DarkThreshold", "MinimumDarkCoverageRatio",
                    "MinimumPinWidth", "MaximumPinBreakWidth", "MinimumGapWidth", "AcceptanceMetricName"
                };
                PropertyDescriptorCollection descriptors = TypeDescriptor.GetProperties(grid.SelectedObject);
                string[] missingProperties = requiredProperties
                    .Where(propertyName => descriptors.Find(propertyName, true) == null)
                    .ToArray();
                if (missingProperties.Length > 0)
                {
                    throw new InvalidOperationException("PinArrayGap PropertyGrid missed: " + string.Join(",", missingProperties));
                }

                int previewRunsBeforeApply = shellHost.NativePreviewRunCount;
                shellHost.RecipeCommands.ApplySelectedStepParametersCommand.Execute(null);
                Pump(220);
                VisionPipeline savedPipeline = VisionPipelineStorage.Load(recipeName, pipeline.Name);
                VisionPipelineStep savedStep = savedPipeline.Steps.Single();
                if (!string.Equals(savedStep.Parameters.GetValueOrDefault("MeasurementMode"), "CenterPitch", StringComparison.Ordinal)
                    || !string.Equals(savedStep.Parameters.GetValueOrDefault("CvROI"), "50,50,540,140", StringComparison.Ordinal)
                    || !string.Equals(savedStep.Parameters.GetValueOrDefault("ALLOW_BRANCH_INPUT"), "true", StringComparison.OrdinalIgnoreCase)
                    || !string.Equals(savedStep.AcceptanceMetricName, "PitchPxRange", StringComparison.Ordinal)
                    || shellHost.NativePreviewRunCount != previewRunsBeforeApply)
                {
                    throw new InvalidOperationException("Recipe Manager PinArrayGap apply/save/reload lost its contract or triggered Preview/Run.");
                }

                TextBox searchTextBox = GetActivePropertyGridSearchTextBox(grid, "PinArrayGap recipe step");
                searchTextBox.Text = "Measurement";
                searchTextBox.GetBindingExpression(TextBox.TextProperty)?.UpdateSource();
                grid.UpdateLayout();
                Pump(60);

                ScrollViewer pipelineScrollViewer = FindNamedVisualChild<ScrollViewer>(
                    shellHost,
                    "recipePipelineTabScrollViewer")
                    ?? throw new InvalidOperationException("PinArrayGap Pipeline scroll viewer was not found.");
                pipelineScrollViewer.ScrollToBottom();
                pipelineScrollViewer.UpdateLayout();
                Pump(80);
                BringPropertyGridPropertyIntoView(grid, "MeasurementMode", "PinArrayGap recipe step", 0D);
                if (grid.IsSearchEmptyMessageVisibleForTest || shellHost.NativePreviewRunCount != 0)
                {
                    throw new InvalidOperationException("PinArrayGap PropertyGrid Pitch search failed or changed Preview/Run state.");
                }
            }, captureFloatingToolWindow: false, captureScreen: true);
        }
        finally
        {
            RecipeWorkspaceService.DeleteVisionWorkspace(recipeName);
        }
    }

    private static CaptureResult CaptureShellHostRecipeLinePairProperties(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.English, false);
