    private static CaptureResult CaptureShellHostWorkspaceSamplePipelineReviewControlledNgMetrics(
        string outputPath,
        string sampleName,
        string expectedMetricName,
        string resultDetailKeyword,
        string scenarioLabel,
        string shellHostTitle,
        string scenarioName,
        int minStepCount,
        int? expectedOkCount = null,
        int? expectedWaitCount = null,
        VisionPipelineSampleCatalogSourceKind expectedSourceKind = VisionPipelineSampleCatalogSourceKind.Public)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        VisionPipelineSampleCatalogItem sample = FindRunnableCatalogSample(sampleName);
        AssertSampleSourceKind(sample, sampleName, expectedSourceKind);
        VisionPipelineSampleCheckResult sampleCheck = VisionPipelineSampleCheckService.RunSampleCheckSafe(sample);
        if (!sample.ExpectsFailure || !sampleCheck.Success)
        {
            throw new InvalidOperationException(
                $"Workspace sample review {scenarioLabel} NG baseline sample check did not confirm the expected-failure sample. "
                + $"Sample={sampleName}, ExpectsFailure={sample.ExpectsFailure}, Status={sampleCheck.Status}, "
                + $"Message={sampleCheck.Message}, Metrics={sampleCheck.MetricText}");
        }

        if (!sampleCheck.MetricText.Contains(expectedMetricName, StringComparison.OrdinalIgnoreCase))
        {
            throw new InvalidOperationException(
                $"Workspace sample review {scenarioLabel} NG baseline is missing {expectedMetricName} metric. "
                + $"Sample={sampleName}, Metrics={sampleCheck.MetricText}");
        }

        OpenVisionShellHostView shellHost = CreateShellHost(shellHostTitle, seedMainLayer: false);
        return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
        {
            (_, int activePipelineStepCount, _) = OpenWorkspaceSamplePipelineReviewForSmoke(
                shellHost,
                sampleName,
                scenarioName,
                minStepCount);

            WaitForTaskWithPump(shellHost.RunPipelineReviewForTestAsync(), 30000, $"Workspace sample pipeline review {scenarioLabel} NG metric execution");
            Pump(120);
            shellHost.SelectPipelineReviewStepForTest(activePipelineStepCount - 1, OpenVisionLab.Pipeline.Controls.PipelineFlowPreviewMode.Output);
            Pump(80);

            if (!shellHost.CanSelectFirstIssuePipelineReviewStepForTest)
            {
                throw new InvalidOperationException(
                    $"Workspace sample Pipeline Review {scenarioLabel} NG did not expose first-issue navigation after selecting the later Step.");
            }

            int nativePreviewRunsBeforeFirstIssue = shellHost.NativePreviewRunCount;
            ClickFloatingButtonByName("btnFirstIssueStep", $"Workspace sample Pipeline Review {scenarioLabel} first-issue navigation");
            Pump(80);
            if (shellHost.NativePreviewRunCount != nativePreviewRunsBeforeFirstIssue)
            {
                throw new InvalidOperationException(
                    $"Workspace sample Pipeline Review {scenarioLabel} first-issue navigation triggered Preview/Run. "
                    + $"Before={nativePreviewRunsBeforeFirstIssue}, After={shellHost.NativePreviewRunCount}");
            }

            bool isObjectResultScenario = sampleName.Contains("Blob", StringComparison.OrdinalIgnoreCase)
                || sampleName.Contains("Contour", StringComparison.OrdinalIgnoreCase);
            if (isObjectResultScenario)
            {
                int objectCount = shellHost.PipelineReviewObjectResultCountForTest;
                int initiallySelectedObjectNumber = shellHost.PipelineReviewSelectedObjectResultNumberForTest;
                int distributionSeriesCount = shellHost.PipelineReviewObjectMetricDistributionSeriesCountForTest;
                int distributionMarkerCount = shellHost.PipelineReviewObjectMetricDistributionMarkerCountForTest;
                string distributionMetric = shellHost.PipelineReviewObjectMetricDistributionMetricForTest;
                string distributionEvidenceId = shellHost.PipelineReviewObjectMetricDistributionEvidenceIdForTest;
                int runsBeforeObjectSelection = shellHost.NativePreviewRunCount;
                int layersBeforeObjectSelection = shellHost.LayerDocumentCount;
                string activeLayerBeforeObjectSelection = shellHost.ActiveHostLayerTitle;
                string inputRouteBeforeObjectSelection = shellHost.ActiveNativeRouteInputLayerNameForTest;
                string outputRouteBeforeObjectSelection = shellHost.ActiveNativeRouteOutputLayerNameForTest;
                if (objectCount <= 0
                    || !shellHost.HasPipelineReviewObjectHighlightForTest
                    || distributionSeriesCount != 2
                    || distributionMarkerCount != 2
                    || !string.Equals(distributionMetric, "Area", StringComparison.Ordinal)
                    || distributionEvidenceId.Length != 64)
                {
                    throw new InvalidOperationException(
                        $"Workspace sample Pipeline Review {scenarioLabel} did not expose object rows, current Area distribution/range, and the selected-object drawing. "
                        + $"Count={objectCount}, Highlight={shellHost.HasPipelineReviewObjectHighlightForTest}, "
                        + $"Series={distributionSeriesCount}, Markers={distributionMarkerCount}, "
                        + $"Metric={distributionMetric}, Evidence={distributionEvidenceId}");
                }

                WriteObjectMetricRuntimeEvidence(
                    outputPath,
                    sampleName,
                    shellHost,
                    objectCount);

                shellHost.SelectPipelineReviewObjectResultForTest(0);
                Pump(40);
                if (shellHost.PipelineReviewSelectedObjectResultNumberForTest != 1
                    || !shellHost.HasPipelineReviewObjectHighlightForTest
                    || shellHost.NativePreviewRunCount != runsBeforeObjectSelection)
                {
                    throw new InvalidOperationException(
                        $"Workspace sample Pipeline Review {scenarioLabel} table selection did not highlight the same object without Preview/Run. "
                        + $"Selected={shellHost.PipelineReviewSelectedObjectResultNumberForTest}, "
                        + $"Highlight={shellHost.HasPipelineReviewObjectHighlightForTest}, "
                        + $"Runs={runsBeforeObjectSelection}->{shellHost.NativePreviewRunCount}");
                }

                int imageSelectionIndex = Math.Min(1, objectCount - 1);
                shellHost.SelectPipelineReviewObjectResultFromImageForTest(imageSelectionIndex);
                Pump(40);
                if (shellHost.PipelineReviewSelectedObjectResultNumberForTest != imageSelectionIndex + 1
                    || shellHost.NativePreviewRunCount != runsBeforeObjectSelection)
                {
                    throw new InvalidOperationException(
                        $"Workspace sample Pipeline Review {scenarioLabel} image hit did not select the matching object row without Preview/Run. "
                        + $"Expected={imageSelectionIndex + 1}, Selected={shellHost.PipelineReviewSelectedObjectResultNumberForTest}, "
                        + $"Runs={runsBeforeObjectSelection}->{shellHost.NativePreviewRunCount}");
                }

                shellHost.SelectPipelineReviewObjectResultForTest(Math.Max(0, initiallySelectedObjectNumber - 1));
                Pump(40);
                if (shellHost.PipelineReviewSelectedObjectResultNumberForTest != initiallySelectedObjectNumber
                    || shellHost.NativePreviewRunCount != runsBeforeObjectSelection)
                {
                    throw new InvalidOperationException(
                        $"Workspace sample Pipeline Review {scenarioLabel} could not restore the reviewed accepted object without Preview/Run.");
                }

                if (shellHost.LayerDocumentCount != layersBeforeObjectSelection
                    || !string.Equals(shellHost.ActiveHostLayerTitle, activeLayerBeforeObjectSelection, StringComparison.Ordinal)
                    || !string.Equals(shellHost.ActiveNativeRouteInputLayerNameForTest, inputRouteBeforeObjectSelection, StringComparison.Ordinal)
                    || !string.Equals(shellHost.ActiveNativeRouteOutputLayerNameForTest, outputRouteBeforeObjectSelection, StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        $"Workspace sample Pipeline Review {scenarioLabel} object inspection changed layers or routing. "
                        + $"Layers={layersBeforeObjectSelection}->{shellHost.LayerDocumentCount}, "
                        + $"Active={activeLayerBeforeObjectSelection}->{shellHost.ActiveHostLayerTitle}, "
                        + $"Input={inputRouteBeforeObjectSelection}->{shellHost.ActiveNativeRouteInputLayerNameForTest}, "
                        + $"Output={outputRouteBeforeObjectSelection}->{shellHost.ActiveNativeRouteOutputLayerNameForTest}");
                }

                AssertObjectResultReportPersistence(outputPath);
            }

            string ngNextAction = OpenVisionLanguageService.T("PipelineReview.Guide.NgNext");
            string fixDetailPrefix = OpenVisionLanguageService.T("PipelineReview.Guide.FixDetailPrefix");
            string parameterLocationPrefix = OpenVisionLanguageService.T("PipelineReview.Guide.ParameterLocationPrefix");
            string triageRerunPair = OpenVisionLanguageService.T("PipelineReview.Guide.TriageRerunPair");
            string metricDisplayKey = "PipelineReview.Metric." + expectedMetricName;
            string metricDisplayName = OpenVisionLanguageService.T(metricDisplayKey);
            bool hasLocalizedMetricDisplayName = !string.IsNullOrWhiteSpace(metricDisplayName)
                && !string.Equals(metricDisplayName, metricDisplayKey, StringComparison.Ordinal);
            string expectedGuideMetricName = hasLocalizedMetricDisplayName ? metricDisplayName : expectedMetricName;
            bool pairMetricHasExpectedResult = shellHost.PipelineReviewGuidePairMetricText.Contains(resultDetailKeyword, StringComparison.OrdinalIgnoreCase)
                || shellHost.PipelineReviewGuidePairMetricText.Contains(expectedGuideMetricName, StringComparison.Ordinal);
            bool resultDetailHasExpectedResult = shellHost.PipelineReviewResultDetailText.Contains(resultDetailKeyword, StringComparison.OrdinalIgnoreCase)
                || shellHost.PipelineReviewResultDetailText.Contains(expectedGuideMetricName, StringComparison.Ordinal);
            string reviewText = string.Join(
                " | ",
                shellHost.PipelineReviewValidationStatusText,
                shellHost.PipelineReviewResultSummaryText,
                shellHost.PipelineReviewResultDetailText,
                shellHost.PipelineReviewRunLogText,
                shellHost.PipelineReviewGuideNextActionText,
                shellHost.PipelineReviewGuideResultDecisionText,
                shellHost.PipelineReviewGuideDetailText,
                shellHost.PipelineReviewGuidePairText,
                shellHost.PipelineReviewGuidePairMetricText,
                shellHost.PipelineReviewGuideParameterFocusText,
                shellHost.PipelineReviewGuideTriageFailureText,
                shellHost.PipelineReviewGuideTriageAdjustmentText,
                shellHost.PipelineReviewGuideTriageRerunText);
            if (string.IsNullOrWhiteSpace(shellHost.PipelineReviewValidationStatusText)
                || !shellHost.PipelineReviewResultSummaryText.Contains("NG", StringComparison.OrdinalIgnoreCase)
                || string.IsNullOrWhiteSpace(shellHost.PipelineReviewRunLogText)
                || !shellHost.PipelineReviewGuideResultDecisionText.Contains("NG", StringComparison.OrdinalIgnoreCase)
                || !shellHost.PipelineReviewGuideNextActionText.Contains(ngNextAction, StringComparison.Ordinal)
                || !shellHost.PipelineReviewGuideNextActionText.Contains(expectedGuideMetricName, StringComparison.Ordinal)
                || !shellHost.PipelineReviewGuidePairText.Contains("Good/Bad", StringComparison.OrdinalIgnoreCase)
                || !shellHost.PipelineReviewGuidePairText.Contains(sampleName, StringComparison.OrdinalIgnoreCase)
                || !shellHost.PipelineReviewGuidePairText.Contains(expectedGuideMetricName, StringComparison.Ordinal)
                || !pairMetricHasExpectedResult
                || !shellHost.PipelineReviewGuidePairMetricText.Contains("Pipeline", StringComparison.OrdinalIgnoreCase)
                || !shellHost.PipelineReviewGuidePairMetricText.Contains("OK", StringComparison.OrdinalIgnoreCase)
                || !shellHost.PipelineReviewGuidePairMetricText.Contains("NG", StringComparison.OrdinalIgnoreCase)
                || !shellHost.PipelineReviewGuidePairMetricText.Contains("샘플 범위", StringComparison.Ordinal)
                || shellHost.PipelineReviewGuidePairMetricText.Contains("기준 안", StringComparison.Ordinal)
                || shellHost.PipelineReviewGuidePairMetricText.Contains("기준 밖", StringComparison.Ordinal)
                || !shellHost.PipelineReviewGuideDetailText.Contains("NG", StringComparison.OrdinalIgnoreCase)
                || (hasLocalizedMetricDisplayName && !shellHost.PipelineReviewGuideDetailText.Contains(metricDisplayName, StringComparison.Ordinal))
                || !shellHost.PipelineReviewGuideDetailText.Contains(parameterLocationPrefix, StringComparison.Ordinal)
                || !shellHost.PipelineReviewGuideDetailText.Contains("파라미터 패널", StringComparison.Ordinal)
                || !shellHost.PipelineReviewGuideParameterFocusText.Contains(parameterLocationPrefix, StringComparison.Ordinal)
                || !shellHost.PipelineReviewGuideParameterFocusText.Contains("파라미터 패널", StringComparison.Ordinal)
                || !shellHost.PipelineReviewGuideTriageFailureText.Contains("NG", StringComparison.OrdinalIgnoreCase)
                || !shellHost.PipelineReviewGuideTriageAdjustmentText.Contains(fixDetailPrefix, StringComparison.Ordinal)
                || !shellHost.PipelineReviewGuideTriageRerunText.Contains(triageRerunPair, StringComparison.Ordinal)
                || (hasLocalizedMetricDisplayName && shellHost.PipelineReviewGuideDetailText.Contains(expectedMetricName, StringComparison.OrdinalIgnoreCase))
                || (hasLocalizedMetricDisplayName && shellHost.PipelineReviewGuidePairText.Contains(expectedMetricName, StringComparison.OrdinalIgnoreCase))
                || (hasLocalizedMetricDisplayName && shellHost.PipelineReviewGuidePairMetricText.Contains(expectedMetricName, StringComparison.OrdinalIgnoreCase))
                || !resultDetailHasExpectedResult
                || !shellHost.HasPipelineReviewOutputPreview
                || !shellHost.CanSelectFirstIssuePipelineReviewStepForTest)
            {
                throw new InvalidOperationException(
                    $"WPF workspace sample Pipeline Review did not expose {scenarioLabel} NG decision, beginner next action, metric detail, run log, output preview, and first issue navigation. "
                    + $"ReviewText='{reviewText}', ExpectedNext='{ngNextAction}', OutputPreview={shellHost.HasPipelineReviewOutputPreview}, FirstIssue={shellHost.CanSelectFirstIssuePipelineReviewStepForTest}");
            }

            AssertPipelineReviewProgressText(
                shellHost,
                expectedOk: expectedOkCount ?? Math.Max(0, activePipelineStepCount - 1),
                expectedNg: 1,
                expectedWait: expectedWaitCount ?? 0,
                $"Workspace sample Pipeline Review {scenarioLabel} NG");

            AssertVisibleAutomationIds(
                GetActiveFloatingToolWindow($"Workspace sample Pipeline Review {scenarioLabel} NG operator focus"),
                $"Workspace sample Pipeline Review {scenarioLabel} NG operator focus",
                "PipelineReviewStepFlowOperatorFocus",
                "PipelineReviewFirstIssueStepButton");
        }, captureFloatingToolWindow: true);
    }

    private static void AssertObjectResultReportPersistence(string screenshotOutputPath)
    {
        string recipeName = "Smoke_ObjectResults_" + Guid.NewGuid().ToString("N");
        try
        {
            VisionPipelineStep step = new VisionPipelineStep
            {
                Name = "Object Count",
                ToolType = "Blob",
                Enabled = true,
                InputLayer = "Main",
                OutputLayer = "Blob_Result"
            };
            VisionPipeline pipeline = new VisionPipeline { Name = "ObjectResultPersistence" };
            pipeline.Steps.Add(step);
            using VisionRecipeRunResult result = new VisionRecipeRunResult
            {
                PipelineName = pipeline.Name,
                Success = true,
                Message = "Object result persistence smoke.",
                Steps = new List<VisionRecipeStepRunSummary>
                {
                    new VisionRecipeStepRunSummary
                    {
                        Index = 1,
                        Name = step.Name,
                        ToolType = step.ToolType,
                        Enabled = true,
                        InputLayer = step.InputLayer,
                        OutputLayer = step.OutputLayer,
                        Status = "OK",
                        ToolSuccess = true,
                        Success = true,
                        AcceptancePassed = true,
                        ObjectResults = new List<VisionPipelineObjectResult>
                        {
                            new VisionPipelineObjectResult
                            {
                                Number = 1,
                                Accepted = true,
                                Area = 640,
                                CenterX = 42,
                                CenterY = 54,
                                BoundsX = 30,
                                BoundsY = 40,
                                BoundsWidth = 24,
                                BoundsHeight = 28,
                                Angle = 1.25
                            },
                            new VisionPipelineObjectResult
                            {
                                Number = 2,
                                Accepted = false,
                                Area = 12,
                                CenterX = 80,
                                CenterY = 54,
                                BoundsX = 77,
                                BoundsY = 51,
                                BoundsWidth = 6,
                                BoundsHeight = 6,
                                Angle = 0,
                                RejectReason = "Area 12 < MIN_AREA 200"
                            }
                        }
                    }
                }
            };

            DateTime startedAt = DateTime.UtcNow;
            VisionRecipeStepRunSummary recipeStepSummary = result.Steps.Single();
            VisionToolResult directToolResult = new VisionToolResult { Success = true };
            VisionPipelineObjectResultStore.Set(directToolResult, recipeStepSummary.ObjectResults);
            VisionPipelineRunResult directRunResult = new VisionPipelineRunResult();
            directRunResult.StepResults.Add(new VisionPipelineStepResult
            {
                Step = step,
                ToolResult = directToolResult,
                AcceptancePassed = true,
                AcceptanceMessage = "Acceptance passed."
            });
            string directReportPath = VisionPipelineRunReportStorage.Save(
                recipeName,
                pipeline,
                directRunResult,
                startedAt,
                startedAt.AddMilliseconds(1),
                false,
                "ObjectResultsDirect");
            VisionPipelineRunReport directReport = VisionPipelineRunReportStorage.Load(directReportPath)
                ?? throw new InvalidOperationException("Direct object result report could not be loaded.");
            AssertPersistedObjectRows(directReport, "Direct object result report");

            string recipeReportPath = VisionPipelineRunReportStorage.Save(
                recipeName,
                pipeline,
                result,
                startedAt,
                startedAt.AddMilliseconds(1),
                "ObjectResults");
            VisionPipelineRunReport recipeReport = VisionPipelineRunReportStorage.Load(recipeReportPath)
                ?? throw new InvalidOperationException("Object result report could not be loaded.");
            AssertPersistedObjectRows(recipeReport, "Recipe object result report");

            string artifactDirectory = Path.GetDirectoryName(screenshotOutputPath) ?? string.Empty;
            Directory.CreateDirectory(artifactDirectory);
            File.Copy(directReportPath, Path.Combine(artifactDirectory, "object_results_direct_report.xml"), true);
            File.Copy(recipeReportPath, Path.Combine(artifactDirectory, "object_results_recipe_report.xml"), true);
        }
        finally
        {
            RecipeWorkspaceService.DeleteVisionWorkspace(recipeName);
        }
    }

    private static void WriteObjectMetricRuntimeEvidence(
        string screenshotOutputPath,
        string sampleName,
        OpenVisionShellHostView shellHost,
        int objectCount)
    {
        string directory = Path.GetDirectoryName(screenshotOutputPath)
            ?? throw new InvalidOperationException("Object metric runtime evidence directory is missing.");
        Directory.CreateDirectory(directory);
        File.WriteAllLines(
            Path.Combine(directory, "object-metric-distribution-runtime.txt"),
            new[]
            {
                "Status=OK",
                "Sample=" + sampleName,
                "ObjectRows=" + objectCount.ToString(CultureInfo.InvariantCulture),
                "Series=" + shellHost.PipelineReviewObjectMetricDistributionSeriesCountForTest.ToString(CultureInfo.InvariantCulture),
                "Markers=" + shellHost.PipelineReviewObjectMetricDistributionMarkerCountForTest.ToString(CultureInfo.InvariantCulture),
                "Metric=" + shellHost.PipelineReviewObjectMetricDistributionMetricForTest,
                "EvidenceId=" + shellHost.PipelineReviewObjectMetricDistributionEvidenceIdForTest,
                "ResultSummary=" + shellHost.PipelineReviewResultSummaryText,
                "ResultDetail=" + shellHost.PipelineReviewResultDetailText
            });
    }

    private static void AssertPersistedObjectRows(VisionPipelineRunReport report, string context)
    {
        List<VisionPipelineObjectRunReport> objects = report?.Steps?.SingleOrDefault()?.Objects
            ?? new List<VisionPipelineObjectRunReport>();
        if (objects.Count != 2
            || !objects[0].Accepted
            || objects[1].Accepted
            || !objects[1].RejectReason.Contains("MIN_AREA", StringComparison.Ordinal))
        {
            throw new InvalidOperationException(
                context + " did not preserve accepted/rejected rows and reject reason.");
        }
    }

    private static void AssertPipelineReviewProgressText(
        OpenVisionShellHostView shellHost,
        int expectedOk,
        int expectedNg,
        int expectedWait,
        string context)
    {
        string progress = shellHost?.PipelineReviewProgressText ?? string.Empty;
        string expectedCounts = string.Format(
            CultureInfo.CurrentCulture,
            OpenVisionLanguageService.T("PipelineReview.Progress.CountsFormat"),
            expectedOk,
            expectedNg,
            expectedWait);
        if (!progress.Contains(expectedCounts, StringComparison.Ordinal)
            || progress.Contains(OpenVisionLanguageService.T("PipelineReview.Progress.Running"), StringComparison.Ordinal))
        {
            throw new InvalidOperationException(
                context + " did not expose the expected Pipeline Review progress summary. "
                + $"Expected='{expectedCounts}', Actual='{progress}'");
        }
    }

