            window.FilterModeIndexForTest = 0;
            window.ResetFilterAnimationForTest();
            window.AdvanceFilterAnimationForTest();
            window.AdvanceFilterAnimationForTest();
            if (!window.FilterAnimationStatusTextForTest.Contains("677 / 9", StringComparison.Ordinal))
            {
