    private static CaptureResult CaptureOpenVisionLearnColorHsv(string outputPath)
    {
        DateTime started = DateTime.UtcNow;
        OpenVisionLearnWindow window = new(127, 255, false, 16);
        window.Show();
        try
        {
            Pump(12);
            window.ColorHueForTest = 45;
            window.ColorValueForTest = 185;
            Pump(8);
            if (window.SelectedTopicIndexForTest != 16)
            {
                throw new InvalidOperationException("OpenVision Learn Color / HSV topic was not selected.");
            }

            AssertLearnTopicDocument(window, "LEARN_COLOR_HSV.md");
            if (!window.SelectedTopicPracticeTextForTest.Contains("HSV", StringComparison.Ordinal)
                || !window.SelectedTopicPracticeTextForTest.Contains("Public_HSV_ColorPatch", StringComparison.Ordinal)
                || !window.SelectedTopicPracticeTextForTest.Contains("MaskPixelRatio", StringComparison.Ordinal)
                || !window.SelectedTopicPracticeTextForTest.Contains("explicit Run Review", StringComparison.Ordinal)
                || !string.Equals(window.SelectedTopicLearnPathIdForTest, "color-hsv", StringComparison.Ordinal))
            {
                throw new InvalidOperationException(
                    "Color / HSV topic did not expose the expected practice guidance. "
                    + "Path='"
                    + window.SelectedTopicLearnPathIdForTest
                    + "', Text='"
                    + window.SelectedTopicPracticeTextForTest
                    + "'.");
            }

            if (!window.ColorHsvFormulaTextForTest.Contains("HSV mask", StringComparison.Ordinal)
                || !window.ColorHsvFormulaTextForTest.Contains("MaskPixelRatio", StringComparison.Ordinal)
                || !window.ColorHsvFormulaTextForTest.Contains("metric=", StringComparison.Ordinal)
                || !window.ColorHsvFormulaTextForTest.Contains("downstream ResultCount/Area", StringComparison.Ordinal)
                || !window.ColorHsvFormulaTextForTest.Contains("OutputLayer", StringComparison.Ordinal))
            {
                throw new InvalidOperationException("Color / HSV guide did not explain mask metric support and downstream review.");
            }

            if (window.CanOpenColorHsvToolForTest)
            {
                throw new InvalidOperationException("Standalone Color / HSV Learn unexpectedly enabled the Shell-only Tool View action.");
            }

            using (OpenCvSharp.Mat bgrPixel = new(
                       1,
                       1,
                       OpenCvSharp.MatType.CV_8UC3,
                       new OpenCvSharp.Scalar(25, 185, 105)))
            using (OpenCvSharp.Mat hsvPixel = new())
            {
                OpenCvSharp.Mat[] bgrChannels = OpenCvSharp.Cv2.Split(bgrPixel);
                try
                {
                    if (bgrChannels.Length != 3
                        || bgrChannels.Any(channel => channel.Type() != OpenCvSharp.MatType.CV_8UC1)
                        || bgrChannels[0].At<byte>(0, 0) != 25
                        || bgrChannels[1].At<byte>(0, 0) != 185
                        || bgrChannels[2].At<byte>(0, 0) != 105)
                    {
                        throw new InvalidOperationException("Color / HSV sample Cv2.Split channel values changed.");
                    }

                    using OpenCvSharp.Mat mergedBgrPixel = new();
                    OpenCvSharp.Cv2.Merge(bgrChannels, mergedBgrPixel);
                    OpenCvSharp.Vec3b mergedPixel = mergedBgrPixel.At<OpenCvSharp.Vec3b>(0, 0);
                    if (mergedPixel.Item0 != 25 || mergedPixel.Item1 != 185 || mergedPixel.Item2 != 105)
                    {
                        throw new InvalidOperationException(
                            "Color / HSV sample Cv2.Merge changed BGR order. Actual BGR=("
                            + mergedPixel.Item0
                            + ","
                            + mergedPixel.Item1
                            + ","
                            + mergedPixel.Item2
                            + ").");
                    }
                }
                finally
                {
                    foreach (OpenCvSharp.Mat channel in bgrChannels)
                    {
                        channel.Dispose();
                    }
                }

                OpenCvSharp.Cv2.CvtColor(
                    bgrPixel,
                    hsvPixel,
                    OpenCvSharp.ColorConversionCodes.BGR2HSV);
                OpenCvSharp.Vec3b convertedPixel = hsvPixel.At<OpenCvSharp.Vec3b>(0, 0);
                if (convertedPixel.Item0 != 45
                    || convertedPixel.Item1 != 221
                    || convertedPixel.Item2 != 185)
                {
                    throw new InvalidOperationException(
                        "Color / HSV sample conversion changed. Actual HSV=("
                        + convertedPixel.Item0
                        + ","
                        + convertedPixel.Item1
                        + ","
                        + convertedPixel.Item2
                        + ").");
                }
            }

            window.ResetColorHsvAnimationForTest();
            window.ToggleColorHsvAnimationForTest();
            Thread.Sleep(600);
            Pump(4);
            if (window.ColorHsvAnimationStepForTest < 1)
            {
                throw new InvalidOperationException("Color / HSV animation timer did not advance.");
            }

            window.ResetColorHsvAnimationForTest();
            if (!string.Equals(window.ColorBgrPixelValueForTest, "(25,185,105)", StringComparison.Ordinal)
                || !string.Equals(window.ColorHsvPixelValueForTest, "(45,221,185)", StringComparison.Ordinal)
                || window.ColorBgrSplitChannelsOpacityForTest >= 0.5D
                || window.ColorBgrMergeResultOpacityForTest >= 0.5D
                || window.ColorHsvConvertedPixelOpacityForTest >= 0.5D
                || window.ColorHsvConversionArrowOpacityForTest >= 0.5D
                || !window.ColorHsvAnimationStatusTextForTest.Contains("Vec3b(B,G,R)=(25,185,105)", StringComparison.Ordinal))
            {
                throw new InvalidOperationException("Color / HSV animation did not expose the BGR source pixel reset state.");
            }

            window.AdvanceColorHsvAnimationForTest();
            if (window.ColorHsvAnimationStepForTest != 1
                || window.ColorBgrSplitChannelsOpacityForTest < 0.99D
                || window.ColorBgrMergeResultOpacityForTest >= 0.5D
                || window.ColorHsvConvertedPixelOpacityForTest >= 0.5D
                || window.ColorHsvConversionArrowOpacityForTest >= 0.5D
                || window.ColorHsvVec3bTypeOpacityForTest >= 0.5D
                || window.ColorHsvScalarBoundsOpacityForTest >= 0.5D
                || !window.ColorHsvAnimationStatusTextForTest.Contains("Cv2.Split", StringComparison.Ordinal)
                || !window.ColorHsvAnimationStatusTextForTest.Contains("B=25, G=185, R=105", StringComparison.Ordinal)
                || !window.ColorHsvAnimationStatusTextForTest.Contains("CV_8UC1", StringComparison.Ordinal))
            {
                throw new InvalidOperationException("Color / HSV animation did not expose the split B/G/R channels.");
            }

            window.AdvanceColorHsvAnimationForTest();
            if (window.ColorHsvAnimationStepForTest != 2
                || window.ColorBgrMergeResultOpacityForTest < 0.99D
                || !window.ColorBgrMergeResultTextForTest.Contains("Cv2.Merge(B,G,R)", StringComparison.Ordinal)
                || window.ColorHsvConvertedPixelOpacityForTest < 0.99D
                || window.ColorHsvConversionArrowOpacityForTest < 0.99D
                || window.ColorHsvVec3bTypeOpacityForTest < 0.99D
                || window.ColorHsvScalarBoundsOpacityForTest >= 0.5D
                || !window.ColorHsvVec3bTypeTextForTest.Contains("Vec3b(H,S,V) = (45,221,185)", StringComparison.Ordinal)
                || !window.ColorHsvAnimationStatusTextForTest.Contains("Cv2.Merge", StringComparison.Ordinal)
                || !window.ColorHsvAnimationStatusTextForTest.Contains("Cv2.CvtColor(BGR2HSV)", StringComparison.Ordinal)
                || !window.ColorHsvAnimationStatusTextForTest.Contains("H=45, S=221, V=185", StringComparison.Ordinal))
            {
                throw new InvalidOperationException("Color / HSV animation did not expose channel merge and HSV conversion.");
            }

            window.AdvanceColorHsvAnimationForTest();
            if (window.ColorHsvAnimationStepForTest != 3
                || window.ColorHsvScalarBoundsOpacityForTest < 0.99D
                || !window.ColorHsvScalarBoundsTextForTest.Contains("lower = Scalar(35,60,185)", StringComparison.Ordinal)
                || !window.ColorHsvScalarBoundsTextForTest.Contains("upper = Scalar(55,255,255)", StringComparison.Ordinal)
                || !window.ColorHsvInRangeTextForTest.Contains("Cv2.InRange(hsvMat, lower, upper, mask)", StringComparison.Ordinal)
                || !window.ColorHsvAnimationStatusTextForTest.Contains("H OK", StringComparison.Ordinal)
                || !window.ColorHsvAnimationStatusTextForTest.Contains("S OK", StringComparison.Ordinal)
                || !window.ColorHsvAnimationStatusTextForTest.Contains("V OK", StringComparison.Ordinal)
                || !window.ColorHsvAnimationStatusTextForTest.Contains("IN RANGE", StringComparison.Ordinal))
            {
                throw new InvalidOperationException("Color / HSV animation did not expose the passing HSV gate.");
            }

            window.AdvanceColorHsvAnimationForTest();
            if (window.ColorHsvAnimationStepForTest != 4
                || !window.ColorHsvAnimationStatusTextForTest.Contains("Mask=255", StringComparison.Ordinal)
                || !window.ColorHsvAnimationStatusTextForTest.Contains("MaskPixelRatio", StringComparison.Ordinal)
                || !window.ColorHsvAnimationStatusTextForTest.Contains("Preview/Run", StringComparison.Ordinal)
                || !string.Equals(window.ColorHsvPreviewLabelForTest, "MASK 255", StringComparison.Ordinal))
            {
                throw new InvalidOperationException("Color / HSV animation did not finish with the passing binary mask.");
            }

            window.ColorHueForTest = 90;
            window.ColorValueForTest = 200;
            window.ResetColorHsvAnimationForTest();
            window.AdvanceColorHsvAnimationForTest();
            window.AdvanceColorHsvAnimationForTest();
            window.AdvanceColorHsvAnimationForTest();
            window.AdvanceColorHsvAnimationForTest();
            if (!window.ColorHsvAnimationStatusTextForTest.Contains("Mask=0", StringComparison.Ordinal)
                || !string.Equals(window.ColorHsvPreviewLabelForTest, "MASK 0", StringComparison.Ordinal))
            {
                throw new InvalidOperationException("Color / HSV animation did not expose the out-of-range binary mask.");
            }

            window.ColorHueForTest = 45;
            window.ColorValueForTest = 185;
            window.ResetColorHsvAnimationForTest();
            window.AdvanceColorHsvAnimationForTest();
            window.AdvanceColorHsvAnimationForTest();
            window.AdvanceColorHsvAnimationForTest();
            window.AdvanceColorHsvAnimationForTest();
            AssertOpenVisionLearnAnimationLegend(window, "OpenVision Learn Color / HSV");

            VISION_MENU? capturedRelatedMenu = null;
            window.SetOpenRelatedToolAction(menu => capturedRelatedMenu = menu);
            ClickVisibleButtonByAutomationId(
                window,
                "OpenVisionLearnColorHsvOpenToolButton",
                "standalone Color / HSV Tool View button");
            Pump(4);
            if (capturedRelatedMenu != VISION_MENU.HSV
                || !window.ColorHsvToolLocationTitleForTest.Contains("Hue Min/Max", StringComparison.Ordinal)
                || !window.ColorHsvToolLocationTitleForTest.Contains("OutputLayer", StringComparison.Ordinal)
                || !window.ColorHsvToolLocationDetailForTest.Contains("Preview 또는 Run Review에서", StringComparison.Ordinal))
            {
                throw new InvalidOperationException("Color / HSV Learn did not route to the HSV Tool View parameter guide.");
            }

            string visibleText = string.Join(
                " | ",
                FindVisualChildren<TextBlock>(window)
                    .Select(item => item.Text)
                    .Where(text => !string.IsNullOrWhiteSpace(text)));
            foreach (string token in new[] { "Hue", "Saturation", "Value", "BGR Vec3b", "HSV Vec3b", "Cv2.Split", "CV_8UC1", "Cv2.Merge", "CvtColor", "Vec3b", "Scalar", "Cv2.InRange", "OutputLayer", "MaskPixelRatio", "Preview 또는 Run Review", "공개 HSV 실습 샘플", "Public_HSV_ColorPatch_Good", "Public_HSV_ColorPatch_Missing_Bad" })
            {
                if (!visibleText.Contains(token, StringComparison.Ordinal))
                {
                    throw new InvalidOperationException("Color / HSV topic did not show expected token '" + token + "'.");
                }
            }

            AssertVisibleAutomationIds(
                window,
                "OpenVision Learn Color / HSV topic",
                "OpenVisionLearnColorSampleEvidence",
                "OpenVisionLearnColorHueSlider",
                "OpenVisionLearnColorValueSlider",
                "OpenVisionLearnColorHsvPlayButton",
                "OpenVisionLearnColorHsvStepButton",
                "OpenVisionLearnColorHsvResetButton",
                "OpenVisionLearnColorHsvAnimationStatus",
                "OpenVisionLearnColorHsvTypeGuidePanel",
                "OpenVisionLearnColorHsvVec3bType",
                "OpenVisionLearnColorHsvScalarBounds",
                "OpenVisionLearnColorHsvInRange",
                "OpenVisionLearnColorHsvConversionPanel",
                "OpenVisionLearnColorBgrPixelCard",
                "OpenVisionLearnColorHsvConversionArrow",
                "OpenVisionLearnColorHsvPixelCard",
                "OpenVisionLearnColorBgrSplitMergePanel",
                "OpenVisionLearnColorBgrSplitTitle",
                "OpenVisionLearnColorBgrSplitChannels",
                "OpenVisionLearnColorBgrMergeResult",
                "OpenVisionLearnColorHsvOpenToolButton",
                "OpenVisionLearnColorHsvToolLocationPanel",
                "OpenVisionLearnColorHsvToolLocationTitle",
                "OpenVisionLearnColorHsvToolLocationDetail");
            foreach (ScrollViewer scrollViewer in FindVisualChildren<ScrollViewer>(window).Where(item => item.IsVisible))
            {
                scrollViewer.ScrollToTop();
            }

            Pump(4);
            WriteElementPng(window, outputPath, 1040, 960);
            window.SetOpenRelatedToolAction(null);
            return new CaptureResult(1040, 960, (DateTime.UtcNow - started).TotalMilliseconds);
        }
        finally
        {
            window.Close();
        }
    }

    private static CaptureResult CaptureShellHostThresholdTool(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        OpenVisionShellHostView shellHost = CreateShellHost("Smoke_WpfShellHostThreshold");
        return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
        {
            shellHost.SelectToolForTest(VISION_MENU.Threshold);
            Pump(16);
            ComboBox? inputLayerCombo = Application.Current.Windows
                .OfType<Window>()
                .Where(item => item.IsVisible && item.GetType().Name == "OpenVisionFloatingToolWindow")
                .SelectMany(FindVisualChildren<ComboBox>)
                .FirstOrDefault(item => string.Equals(item.Name, "cbInputLayer", StringComparison.Ordinal));
            if (inputLayerCombo == null || inputLayerCombo.Items.Count == 0)
            {
                throw new InvalidOperationException("Threshold layer combo did not expose items.");
            }

            inputLayerCombo.IsDropDownOpen = true;
            Pump(6);
            if (!inputLayerCombo.IsDropDownOpen)
            {
                throw new InvalidOperationException("Threshold layer combo did not open.");
            }

            inputLayerCombo.IsDropDownOpen = false;
            RadioButton? adaptiveMode = Application.Current.Windows
                .OfType<Window>()
                .Where(item => item.IsVisible && item.GetType().Name == "OpenVisionFloatingToolWindow")
                .SelectMany(FindVisualChildren<RadioButton>)
                .FirstOrDefault(item => string.Equals(item.Name, "rbAdaptive", StringComparison.Ordinal));
            RadioButton? basicMode = Application.Current.Windows
                .OfType<Window>()
                .Where(item => item.IsVisible && item.GetType().Name == "OpenVisionFloatingToolWindow")
                .SelectMany(FindVisualChildren<RadioButton>)
                .FirstOrDefault(item => string.Equals(item.Name, "rbBasic", StringComparison.Ordinal));
            RadioButton? rangeMode = Application.Current.Windows
                .OfType<Window>()
                .Where(item => item.IsVisible && item.GetType().Name == "OpenVisionFloatingToolWindow")
                .SelectMany(FindVisualChildren<RadioButton>)
                .FirstOrDefault(item => string.Equals(item.Name, "rbRange", StringComparison.Ordinal));
            RadioButton? gaussianMethod = Application.Current.Windows
                .OfType<Window>()
                .Where(item => item.IsVisible && item.GetType().Name == "OpenVisionFloatingToolWindow")
                .SelectMany(FindVisualChildren<RadioButton>)
                .FirstOrDefault(item => string.Equals(item.Name, "rbAdaptiveGaussian", StringComparison.Ordinal));
            Slider? blockSlider = Application.Current.Windows
                .OfType<Window>()
                .Where(item => item.IsVisible && item.GetType().Name == "OpenVisionFloatingToolWindow")
                .SelectMany(FindVisualChildren<Slider>)
                .FirstOrDefault(item => string.Equals(item.Name, "sliderBlockSize", StringComparison.Ordinal));
            if (basicMode == null || adaptiveMode == null || rangeMode == null || gaussianMethod == null || blockSlider == null)
            {
                throw new InvalidOperationException("Threshold adaptive controls were not found.");
            }

            ThresholdToolWpfView? thresholdView = Application.Current.Windows
                .OfType<Window>()
                .Where(item => item.IsVisible && item.GetType().Name == "OpenVisionFloatingToolWindow")
                .SelectMany(FindVisualChildren<ThresholdToolWpfView>)
                .FirstOrDefault();
            if (thresholdView == null)
            {
                throw new InvalidOperationException("Threshold WPF view was not found.");
            }

            thresholdView.ConfigureBasicInvertForTest(false);
            Pump(12);
            Button? guideButton = Application.Current.Windows
                .OfType<Window>()
                .Where(item => item.IsVisible && item.GetType().Name == "OpenVisionFloatingToolWindow")
                .SelectMany(FindVisualChildren<Button>)
                .Where(item => item.IsVisible)
                .FirstOrDefault(item =>
                    string.Equals(
                        AutomationProperties.GetAutomationId(item),
                        "ThresholdToolLearnButton",
                        StringComparison.Ordinal)
                    || ExtractElementText(item).Contains("Learn Threshold", StringComparison.Ordinal));
            if (guideButton == null)
            {
                string buttonCandidates = string.Join(
                    " | ",
                    Application.Current.Windows
                        .OfType<Window>()
                        .Where(item => item.IsVisible && item.GetType().Name == "OpenVisionFloatingToolWindow")
                        .SelectMany(FindVisualChildren<Button>)
                        .Where(item => item.IsVisible)
                        .Select(item =>
                            "Name='"
                            + item.Name
                            + "', Id='"
                            + AutomationProperties.GetAutomationId(item)
                            + "', Text='"
                            + ExtractElementText(item.Content)
                            + "', Visible="
                            + item.IsVisible.ToString(CultureInfo.InvariantCulture)
                            + ", Size="
                            + item.ActualWidth.ToString("0.0", CultureInfo.InvariantCulture)
                            + "x"
                            + item.ActualHeight.ToString("0.0", CultureInfo.InvariantCulture)));
                throw new InvalidOperationException("Threshold Learn entry button was not visible. Buttons=" + buttonCandidates);
            }

            int beforeGuideApplyRuns = shellHost.NativePreviewRunCount;
            guideButton.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));
            Pump(12);
            OpenVisionLearnWindow? guideWindow = Application.Current.Windows
                .OfType<OpenVisionLearnWindow>()
                .FirstOrDefault(item => item.IsVisible);
            if (guideWindow == null)
            {
                throw new InvalidOperationException("OpenVision Learn window did not open.");
            }

            thresholdView.OpenThresholdGuideForTest();
            Pump(6);
            List<OpenVisionLearnWindow> activeGuideWindows = Application.Current.Windows
                .OfType<OpenVisionLearnWindow>()
                .Where(item => item.IsVisible)
                .ToList();
            if (activeGuideWindows.Count != 1 || !ReferenceEquals(activeGuideWindows[0], guideWindow))
            {
                throw new InvalidOperationException("Threshold Learn reopen created a duplicate window instead of activating the existing window.");
            }

            guideWindow.ThresholdValueForTest = 142;
            guideWindow.IsInvertedForTest = true;
            Pump(6);
            if (!guideWindow.FormulaTextForTest.Contains("BinaryInv", StringComparison.Ordinal)
                || !guideWindow.FormulaTextForTest.Contains("MaxValue", StringComparison.Ordinal))
            {
                throw new InvalidOperationException("Threshold guide did not explain BinaryInv conversion.");
            }

            guideWindow.ApplyForTest();
            Pump(12);
            guideWindow.Close();
            Pump(6);

            thresholdView.OpenThresholdGuideForTest();
            Pump(6);
            OpenVisionLearnWindow? reopenedGuideWindow = Application.Current.Windows
                .OfType<OpenVisionLearnWindow>()
                .FirstOrDefault(item => item.IsVisible);
            if (reopenedGuideWindow == null || ReferenceEquals(reopenedGuideWindow, guideWindow))
            {
                throw new InvalidOperationException("Threshold Learn window did not reopen after the previous window closed.");
            }

            reopenedGuideWindow.Close();
            Pump(6);
            if (shellHost.NativePreviewRunCount != beforeGuideApplyRuns)
            {
                throw new InvalidOperationException(
                    "Threshold guide Apply triggered Preview/Run. "
                    + $"RunsBefore={beforeGuideApplyRuns}, RunsAfter={shellHost.NativePreviewRunCount}");
            }

            if (!FloatingToolTextContains("Basic / T 142"))
            {
                throw new InvalidOperationException("Threshold guide Apply did not update the visible tool threshold summary.");
            }

            AssertFloatingNamedElementsDoNotOverlap(
                "Threshold basic slider layout",
                "txtThreshold",
                "txtMaxValue",
                "sliderThreshold");
            rangeMode.IsChecked = true;
            Pump(12);
            AssertFloatingNamedElementsDoNotOverlap(
                "Threshold range slider layout",
                "txtRangeMin",
                "sliderRangeMin",
                "txtRangeMax",
                "sliderRangeMax");
            Thread.Sleep(180);
            Pump(24);
            AssertThresholdRangeSignalInspector(shellHost, thresholdView);

            int beforeRuns = shellHost.NativePreviewRunCount;
            adaptiveMode.IsChecked = true;
            gaussianMethod.IsChecked = true;
            blockSlider.Value = 31;
            Thread.Sleep(180);
            Pump(24);
            AssertFloatingNamedElementsDoNotOverlap(
                "Threshold adaptive block slider layout",
                "txtBlockSize",
                "sliderBlockSize");
            AssertFloatingSlidersHaveBreathingRoom("Threshold");
            if (!shellHost.IsNativeDocumentActive
                || !shellHost.HasNativePreviewResult
                || shellHost.NativePreviewRunCount <= beforeRuns)
            {
                throw new InvalidOperationException("Native WPF Threshold tool did not auto-preview from adaptive control changes: " + shellHost.ActiveNativeStatusText);
            }

            if (thresholdView.SignalInspectorHasEvidenceForTest)
            {
                throw new InvalidOperationException(
                    "Adaptive Threshold should not present a global cutoff-teaching chart.");
            }

            if (!shellHost.ActiveNativeDocumentTypeName.Contains("ThresholdToolWpfView", StringComparison.Ordinal))
            {
                throw new InvalidOperationException("Threshold did not open the WPF Threshold tool view.");
            }

            if (!FloatingToolTextContains(OpenVisionLanguageService.T("VisionMenu.Threshold"))
                || !FloatingToolTextContains(OpenVisionLanguageService.T("Threshold.ModeBasic"))
                || !FloatingToolTextContains(OpenVisionLanguageService.T("Threshold.ModeRange"))
                || !FloatingToolTextContains(OpenVisionLanguageService.T("Threshold.ModeAdaptive"))
                || !FloatingToolTextContains(OpenVisionLanguageService.T("Threshold.BinaryInv"))
                || !FloatingToolTextContains(OpenVisionLanguageService.T("Threshold.GaussianC"))
                || !FloatingToolTextContains("Block 31"))
            {
                throw new InvalidOperationException("Threshold WPF tool did not expose the modern mode selector.");
            }

            VisionPipelineStep step = shellHost.AddActiveNativePipelineStepForTest();
            if (step == null
                || !string.Equals(step.ToolType, "Threshold", StringComparison.Ordinal)
                || !string.Equals(step.InputLayer, "Main", StringComparison.Ordinal)
                || !string.Equals(step.OutputLayer, "Threshold_Preview", StringComparison.Ordinal)
                || step.Parameters == null
                || !step.Parameters.ContainsKey("Mode")
                || !step.Parameters.TryGetValue("Mode", out string? mode)
                || !string.Equals(mode, "Adaptive", StringComparison.Ordinal)
                || !step.Parameters.ContainsKey("ThresholdType")
                || !step.Parameters.ContainsKey("RangeMin")
                || !step.Parameters.TryGetValue("AdaptiveType", out string? adaptiveType)
                || !string.Equals(adaptiveType, "GaussianC", StringComparison.Ordinal)
                || !step.Parameters.TryGetValue("BlockSize", out string? blockSize)
                || !string.Equals(blockSize, "31", StringComparison.Ordinal))
            {
                throw new InvalidOperationException("Threshold WPF tool did not create a valid pipeline step.");
            }

            if (!shellHost.DockActiveWpfToolWindowForTest())
            {
                throw new InvalidOperationException("Threshold floating tool did not accept the dock-to-right request.");
            }

            Pump(24);
            AssertDockedSingleInputToolLayout("Docked Threshold tool layout");
            AssertActiveToolNamedElementsDoNotOverlap(
                "Docked Threshold adaptive layout",
                "txtBlockSize",
                "sliderBlockSize");
            AssertActiveToolNamedElementsVisibleWithinAncestors(
                "Docked Threshold adaptive controls",
                "rbBasic",
                "rbRange",
                "rbAdaptive",
                "txtBlockSize",
                "sliderBlockSize");
            AssertFloatingSlidersHaveBreathingRoom("Docked Threshold");
        });
    }

    private static CaptureResult CaptureCvr07ThresholdSuggestion(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        OpenVisionShellHostView shellHost = CreateShellHost("Smoke_Cvr07ThresholdSuggestion");
        return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
        {
            AssertCvr07ThresholdSuggestionAnalyzerMatrix();
            shellHost.SelectToolForTest(VISION_MENU.Threshold);
            Pump(16);
            shellHost.RunActiveNativePreviewForTest();
            Pump(24);
            ThresholdToolWpfView thresholdView = FindActiveToolVisualRoots()
                .SelectMany(root => FindVisualChildren<ThresholdToolWpfView>(root))
                .LastOrDefault()
                ?? throw new InvalidOperationException(
                    "CVR-07 Threshold suggestion could not find the active Threshold view.");
            if (!thresholdView.SignalInspectorHasEvidenceForTest
                || !thresholdView.IsThresholdSuggestionPanelVisibleForTest
                || thresholdView.HasThresholdSuggestionForTest
                || thresholdView.CanUseThresholdSuggestionForTest)
            {
                throw new InvalidOperationException(
                    "CVR-07 Threshold suggestion did not start from current Basic Preview evidence without a preselected candidate.");
            }

            ThresholdToolProperty initialProperty = thresholdView.CreateProperty();
            int initialThreshold = Math.Clamp((int)Math.Round(initialProperty.Threshold), 0, 255);
            int runsBeforeAnalyze = shellHost.NativePreviewRunCount;
            int layersBeforeAnalyze = shellHost.LayerDocumentCount;
            string activeLayerBeforeAnalyze = shellHost.ActiveRecipeContextLayerNameForTest;
            string inputBeforeAnalyze = shellHost.ActiveNativeRouteInputLayerNameForTest;
            string outputBeforeAnalyze = shellHost.ActiveNativeRouteOutputLayerNameForTest;
            thresholdView.AnalyzeThresholdSuggestionForTest();
            int suggestedThreshold = thresholdView.ThresholdSuggestionValueForTest;
            if (shellHost.NativePreviewRunCount != runsBeforeAnalyze
                || shellHost.LayerDocumentCount != layersBeforeAnalyze
                || !string.Equals(shellHost.ActiveRecipeContextLayerNameForTest, activeLayerBeforeAnalyze, StringComparison.Ordinal)
                || !string.Equals(shellHost.ActiveNativeRouteInputLayerNameForTest, inputBeforeAnalyze, StringComparison.Ordinal)
                || !string.Equals(shellHost.ActiveNativeRouteOutputLayerNameForTest, outputBeforeAnalyze, StringComparison.Ordinal)
                || !thresholdView.HasThresholdSuggestionForTest
                || !thresholdView.CanUseThresholdSuggestionForTest
                || thresholdView.SignalInspectorAdvisoryMarkerCountForTest != 1
                || thresholdView.ThresholdSuggestionEvidenceIdForTest.Length != 64
                || suggestedThreshold < 0
                || suggestedThreshold > 255
                || !thresholdView.ThresholdSuggestionStatusForTest.Contains("significant gray modes", StringComparison.Ordinal)
                || !thresholdView.ThresholdSuggestionStatusForTest.Contains("Full image", StringComparison.OrdinalIgnoreCase))
            {
                throw new InvalidOperationException(
                    "Analyzing the Threshold suggestion did not retain one explained full-image candidate without execution or workspace mutation. "
                    + $"Runs={runsBeforeAnalyze}->{shellHost.NativePreviewRunCount}, "
                    + $"Candidate={suggestedThreshold}, Evidence={thresholdView.ThresholdSuggestionEvidenceIdForTest}, "
                    + $"AdvisoryMarkers={thresholdView.SignalInspectorAdvisoryMarkerCountForTest}, "
                    + $"Status='{thresholdView.ThresholdSuggestionStatusForTest}'");
            }

            if (suggestedThreshold == initialThreshold)
            {
                int setupThreshold = suggestedThreshold >= 224
                    ? suggestedThreshold - 31
                    : suggestedThreshold + 31;
                thresholdView.CommitSignalInspectorMarkerForTest(
                    OpenVisionNativeThresholdSignalEvidenceFactory.ThresholdMarkerId,
                    setupThreshold);
                Thread.Sleep(180);
                Pump(30);
                initialThreshold = setupThreshold;
                runsBeforeAnalyze = shellHost.NativePreviewRunCount;
                thresholdView.AnalyzeThresholdSuggestionForTest();
                suggestedThreshold = thresholdView.ThresholdSuggestionValueForTest;
                if (suggestedThreshold == initialThreshold
                    || shellHost.NativePreviewRunCount != runsBeforeAnalyze)
                {
                    throw new InvalidOperationException(
                        "CVR-07 setup could not preserve a distinct deterministic suggestion without executing.");
                }
            }

            int runsBeforeUse = shellHost.NativePreviewRunCount;
            thresholdView.UseThresholdSuggestionForTest();
            if (thresholdView.SignalInspectorHasEvidenceForTest
                || Math.Abs(thresholdView.CreateProperty().Threshold - suggestedThreshold) > 0.001D)
            {
                throw new InvalidOperationException(
                    "Use T did not synchronously apply the explicit suggestion and clear stale evidence.");
            }

            Thread.Sleep(180);
            Pump(30);
            if (shellHost.NativePreviewRunCount <= runsBeforeUse
                || !thresholdView.SignalInspectorHasEvidenceForTest
                || !thresholdView.CanUndoThresholdSuggestionForTest
                || !thresholdView.ThresholdSuggestionStatusForTest.Contains(
                    "Previous T=" + initialThreshold.ToString(CultureInfo.InvariantCulture),
                    StringComparison.Ordinal))
            {
                throw new InvalidOperationException(
                    "Use T did not follow the existing debounced Preview policy and preserve the prior teaching value. "
                    + $"Runs={runsBeforeUse}->{shellHost.NativePreviewRunCount}, "
                    + $"Undo={thresholdView.CanUndoThresholdSuggestionForTest}, "
                    + $"Status='{thresholdView.ThresholdSuggestionStatusForTest}'");
            }

            string artifactDirectory = Path.GetDirectoryName(Path.GetFullPath(outputPath))
                ?? throw new InvalidOperationException("CVR-07 UI artifact directory is missing.");
            Directory.CreateDirectory(artifactDirectory);
            WriteElementPng(
                GetActiveFloatingToolWindow("CVR-07 applied Threshold suggestion"),
                Path.Combine(artifactDirectory, "threshold_suggestion_applied.png"),
                1500,
                880);

            int runsBeforeUndo = shellHost.NativePreviewRunCount;
            thresholdView.UndoThresholdSuggestionForTest();
            if (thresholdView.SignalInspectorHasEvidenceForTest
                || Math.Abs(thresholdView.CreateProperty().Threshold - initialThreshold) > 0.001D)
            {
                throw new InvalidOperationException(
                    "Undo did not synchronously restore the previous Threshold teaching value.");
            }

            Thread.Sleep(180);
            Pump(30);
            if (shellHost.NativePreviewRunCount <= runsBeforeUndo
                || !thresholdView.SignalInspectorHasEvidenceForTest
                || thresholdView.CanUndoThresholdSuggestionForTest
                || shellHost.LayerDocumentCount != layersBeforeAnalyze
                || !string.Equals(shellHost.ActiveRecipeContextLayerNameForTest, activeLayerBeforeAnalyze, StringComparison.Ordinal)
                || !string.Equals(shellHost.ActiveNativeRouteInputLayerNameForTest, inputBeforeAnalyze, StringComparison.Ordinal)
                || !string.Equals(shellHost.ActiveNativeRouteOutputLayerNameForTest, outputBeforeAnalyze, StringComparison.Ordinal))
            {
                throw new InvalidOperationException(
                    "Undo did not restore current Preview evidence or changed workspace layers/routes.");
            }

            int runsBeforeFinalAnalyze = shellHost.NativePreviewRunCount;
            thresholdView.AnalyzeThresholdSuggestionForTest();
            if (shellHost.NativePreviewRunCount != runsBeforeFinalAnalyze
                || !thresholdView.HasThresholdSuggestionForTest
                || thresholdView.SignalInspectorAdvisoryMarkerCountForTest != 1)
            {
                throw new InvalidOperationException(
                    "Final Threshold suggestion review did not remain selection-only.");
            }

            WriteCvr07ThresholdSuggestionPublicReplay(outputPath);
            AssertVisibleAutomationIds(
                GetActiveFloatingToolWindow("CVR-07 Threshold suggestion"),
                "CVR-07 Threshold suggestion",
                "ThresholdSuggestionPanel",
                "ThresholdSuggestionAnalyzeButton",
                "ThresholdSuggestionUseButton",
                "ThresholdSuggestionUndoButton",
                "VisionToolSignalPlot");
        });
    }

    private static CaptureResult CaptureManualToolView(
        string outputPath,
        VISION_MENU menu,
        OpenVisionLanguage language = OpenVisionLanguage.Korean)
    {
        OpenVisionLanguageService.SetLanguage(language, false);
        OpenVisionShellHostView shellHost = CreateShellHost("Manual_" + menu);
        OpenVisionLanguageService.SetLanguage(language, false);
        return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
        {
            int beforeRuns = shellHost.NativePreviewRunCount;
            shellHost.SelectToolForTest(menu);
            Pump(24);
            if (!shellHost.IsNativeDocumentActive || !shellHost.IsActiveWpfToolWindowVisibleForTest)
            {
                throw new InvalidOperationException(
                    "Manual capture did not open the requested Tool View. "
                    + $"Menu={menu}, Type={shellHost.ActiveNativeDocumentTypeName}, Title={shellHost.ActiveWpfToolWindowTitle}");
            }

            if (shellHost.NativePreviewRunCount != beforeRuns || shellHost.HasNativePreviewResult)
            {
                throw new InvalidOperationException(
                    "Opening a Tool View for the manual must not run Preview. "
                    + $"Menu={menu}, Runs={shellHost.NativePreviewRunCount}, HasResult={shellHost.HasNativePreviewResult}");
            }
        });
    }

    private static void WriteCvr07ThresholdSuggestionPublicReplay(string outputPath)
    {
        const string goodSampleName = "Public_Threshold_BandPads_Good";
        const string badSampleName = "Public_Threshold_BandPads_Missing_Bad";
        VisionPipelineSampleCatalogItem goodSample = FindRunnableCatalogSample(goodSampleName);
        VisionPipelineSampleCatalogItem badSample = FindRunnableCatalogSample(badSampleName);
        if (!VisionPipelineStorage.TryLoadFromFile(
                goodSample.PipelineFullPath,
                out VisionPipeline pipeline,
                out string loadMessage)
            || pipeline == null)
        {
            throw new InvalidOperationException(
                "CVR-07 public Threshold replay could not load the shared Pipeline: " + loadMessage);
        }

        VisionPipelineStep thresholdStep = pipeline.Steps.SingleOrDefault(step =>
            string.Equals(step.ToolType, "Threshold", StringComparison.OrdinalIgnoreCase))
            ?? throw new InvalidOperationException(
                "CVR-07 public Threshold replay Pipeline has no Threshold Step.");
        ThresholdToolProperty baselineProperty = new()
        {
            Mode = ThresholdToolMode.Threshold,
            Threshold = thresholdStep.Parameters.TryGetValue("Threshold", out string? baselineText)
                && double.TryParse(baselineText, NumberStyles.Float, CultureInfo.InvariantCulture, out double baseline)
                    ? baseline
                    : 130D,
            MaxValue = 255D,
            ThresholdType = OpenCvSharp.ThresholdTypes.Binary
        };
        VisionToolSignalEvidence goodEvidence =
            CreateThresholdReplaySignalEvidence(goodSample, baselineProperty);
        VisionToolThresholdSuggestion suggestion =
            VisionToolThresholdSuggestionAnalyzer.Analyze(
                goodEvidence,
                baselineProperty.ThresholdType != OpenCvSharp.ThresholdTypes.BinaryInv);
        if (!suggestion.Accepted)
        {
            throw new InvalidOperationException(
                "CVR-07 public Threshold Good histogram rejected the bounded suggestion: "
                + suggestion.Reason);
        }

        thresholdStep.Parameters["Mode"] = "Threshold";
        thresholdStep.Parameters["Threshold"] =
            suggestion.Threshold.ToString(CultureInfo.InvariantCulture);
        thresholdStep.Parameters["MaxValue"] = "255";
        thresholdStep.Parameters["ThresholdType"] = "Binary";

        string directory = Path.GetDirectoryName(Path.GetFullPath(outputPath))
            ?? throw new InvalidOperationException("CVR-07 artifact directory is missing.");
        Directory.CreateDirectory(directory);
        string pipelinePath = Path.Combine(directory, "Public_Threshold_BandPads_BrightMode.pipeline.xml");
        if (!VisionPipelineStorage.TrySaveToFile(pipelinePath, pipeline, out string saveMessage))
        {
            throw new InvalidOperationException(
                "CVR-07 could not retain the exact suggested Pipeline: " + saveMessage);
        }

        using CvMat goodSource = Cv.ImRead(goodSample.ImageFullPath, CvImreadModes.Color);
        using CvMat badSource = Cv.ImRead(badSample.ImageFullPath, CvImreadModes.Color);
        VisionRecipeRunner runner = new();
        Task<VisionRecipeRunResult> goodTask = runner.RunAsync(pipeline, goodSource);
        WaitForTaskWithPump(goodTask, 30000, "CVR-07 public Good suggested Pipeline");
        using VisionRecipeRunResult goodResult = goodTask.GetAwaiter().GetResult();
        Task<VisionRecipeRunResult> badTask = runner.RunAsync(pipeline, badSource);
        WaitForTaskWithPump(badTask, 30000, "CVR-07 public Bad suggested Pipeline");
        using VisionRecipeRunResult badResult = badTask.GetAwaiter().GetResult();
        double goodCount = goodResult.FinalStepSummary?.Metrics?.GetValueOrDefault(
            VisionPipelineKnownMetrics.ResultCount) ?? double.NaN;
        double badCount = badResult.FinalStepSummary?.Metrics?.GetValueOrDefault(
            VisionPipelineKnownMetrics.ResultCount) ?? double.NaN;
        if (!goodResult.Success
            || goodCount != 4D
            || badResult.Success
            || badCount != 1D)
        {
            throw new InvalidOperationException(
                "CVR-07 suggested Threshold did not preserve the public Good/Bad semantic split. "
                + $"T={suggestion.Threshold}, Good={goodResult.Success}/{goodCount}, "
                + $"Bad={badResult.Success}/{badCount}");
        }

        Cv.ImWrite(Path.Combine(directory, "Public_Threshold_BandPads_Good_source.png"), goodSource);
        Cv.ImWrite(Path.Combine(directory, "Public_Threshold_BandPads_Bad_source.png"), badSource);
        if (goodResult.ResultImage == null
            || goodResult.ResultImage.Empty()
            || badResult.ResultImage == null
            || badResult.ResultImage.Empty())
        {
            throw new InvalidOperationException(
                "CVR-07 public suggested Pipeline did not retain final result drawings.");
        }

        Cv.ImWrite(
            Path.Combine(directory, "Public_Threshold_BandPads_Good_result.png"),
            goodResult.ResultImage);
        Cv.ImWrite(
            Path.Combine(directory, "Public_Threshold_BandPads_Bad_result.png"),
            badResult.ResultImage);
        File.WriteAllLines(
            Path.Combine(directory, "threshold-suggestion.tsv"),
            new[]
            {
                "Status\tSuggestedThreshold\tSeparationRatio\tLowerPopulationRatio\tUpperPopulationRatio\tSuggestionEvidenceId\tSourceEvidenceId\tGoodResultCount\tBadResultCount\tReason",
                string.Join(
                    "\t",
                    "PASS",
                    suggestion.Threshold.ToString(CultureInfo.InvariantCulture),
                    suggestion.SeparationRatio.ToString("0.###############", CultureInfo.InvariantCulture),
                    suggestion.LowerPopulationRatio.ToString("0.###############", CultureInfo.InvariantCulture),
                    suggestion.UpperPopulationRatio.ToString("0.###############", CultureInfo.InvariantCulture),
                    suggestion.EvidenceId,
                    goodEvidence.EvidenceId,
                    goodCount.ToString(CultureInfo.InvariantCulture),
                    badCount.ToString(CultureInfo.InvariantCulture),
                    suggestion.Reason.Replace("\t", " ").Replace("\r", " ").Replace("\n", " "))
            });
    }

    private static void AssertCvr07ThresholdSuggestionAnalyzerMatrix()
    {
        double[] threeModeValues = new double[256];
        threeModeValues[40] = 20D;
        threeModeValues[110] = 10D;
        threeModeValues[190] = 5D;
        VisionToolSignalEvidence evidence = new(
            new string('A', 64),
            new string('B', 64),
            new string('C', 64),
            "Threshold/Threshold",
            "Main",
            "Full image",
            "Basic",
            "Gray level",
            "Pixel %",
            new[]
            {
                new VisionToolSignalSeries(
                    "Gray population",
                    "#1F77B4",
                    0D,
                    1D,
                    threeModeValues)
            });
        VisionToolThresholdSuggestion bright =
            VisionToolThresholdSuggestionAnalyzer.Analyze(evidence, selectBright: true);
        VisionToolThresholdSuggestion dark =
            VisionToolThresholdSuggestionAnalyzer.Analyze(evidence, selectBright: false);
        VisionToolThresholdSuggestion repeated =
            VisionToolThresholdSuggestionAnalyzer.Analyze(evidence, selectBright: true);
        if (!bright.Accepted
            || bright.Threshold != 150
            || !dark.Accepted
            || dark.Threshold != 75
            || !string.Equals(bright.EvidenceId, repeated.EvidenceId, StringComparison.Ordinal))
        {
            throw new InvalidOperationException(
                "CVR-07 Threshold suggestion bright/dark significant-mode matrix changed. "
                + $"Bright={bright.Accepted}/{bright.Threshold}, Dark={dark.Accepted}/{dark.Threshold}, "
                + $"Repeat={bright.EvidenceId == repeated.EvidenceId}");
        }

        double[] flatValues = new double[256];
        flatValues[128] = 100D;
        VisionToolSignalEvidence flatEvidence = new(
            new string('D', 64),
            new string('E', 64),
            new string('F', 64),
            "Threshold/Threshold",
            "Main",
            "Full image",
            "Basic",
            "Gray level",
            "Pixel %",
            new[]
            {
                new VisionToolSignalSeries(
                    "Gray population",
                    "#1F77B4",
                    0D,
                    1D,
                    flatValues)
            });
        VisionToolThresholdSuggestion flat =
            VisionToolThresholdSuggestionAnalyzer.Analyze(flatEvidence, selectBright: true);
        if (flat.Accepted
            || !flat.Reason.Contains("Fewer than two", StringComparison.Ordinal))
        {
            throw new InvalidOperationException(
                "CVR-07 Threshold suggestion did not reject a single-mode histogram.");
        }
    }

