    private static CaptureResult CaptureShellHostRecipeChangeSafety(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        CleanupTransientRecipeWorkspaces();

        string recipeA = "Smoke_RecipeSafety_A_" + Guid.NewGuid().ToString("N").Substring(0, 10);
        string recipeB = "Smoke_RecipeSafety_B_" + Guid.NewGuid().ToString("N").Substring(0, 10);
        const string pipelineA = "Inspection_A";
        const string pipelineAAlternative = "Inspection_A_Alternative";
        const string pipelineB = "Inspection_B";
        const int originalMinArea = 321;
        const int editedMinArea = 987;

        VisionPipeline CreateBlobPipeline(string name, int stepCount)
        {
            VisionPipeline pipeline = new() { Name = name };
            for (int index = 0; index < stepCount; index++)
            {
                VisionPipelineStep step = new()
                {
                    Name = $"{name}_Blob_{index + 1}",
                    ToolType = "Blob",
                    InputLayer = index == 0 ? "Main" : $"{name}_Preview_{index}",
                    OutputLayer = $"{name}_Preview_{index + 1}"
                };
                step.Parameters["MIN_AREA"] = (originalMinArea + index).ToString(CultureInfo.InvariantCulture);
                step.Parameters["MAX_AREA"] = "1000000";
                pipeline.Steps.Add(step);
            }

            return pipeline;
        }

        VisionPipelineStorage.Save(recipeA, CreateBlobPipeline(pipelineA, 2));
        VisionPipelineStorage.Save(recipeA, CreateBlobPipeline(pipelineAAlternative, 1));
        VisionPipelineStorage.SaveActivePipelineName(recipeA, pipelineA);
        VisionPipelineStorage.Save(recipeB, CreateBlobPipeline(pipelineB, 1));
        VisionPipelineStorage.SaveActivePipelineName(recipeB, pipelineB);

        OpenVisionShellHostView shellHost = CreateShellHost(recipeA, seedMainLayer: true);
        try
        {
            return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
            {
                int previewRunsBefore = shellHost.NativePreviewRunCount;
                int layerCountBefore = shellHost.LayerDocumentCount;
                string activeLayerBefore = shellHost.ActiveHostLayerTitle;
                string routeInputBefore = shellHost.ActiveNativeRouteInputLayerNameForTest;
                string routeOutputBefore = shellHost.ActiveNativeRouteOutputLayerNameForTest;

                void AssertNoWorkspaceSideEffects(string scenario)
                {
                    if (shellHost.NativePreviewRunCount != previewRunsBefore
                        || shellHost.HasNativePreviewResult
                        || shellHost.LayerDocumentCount != layerCountBefore
                        || !string.Equals(shellHost.ActiveHostLayerTitle, activeLayerBefore, StringComparison.Ordinal)
                        || !string.Equals(shellHost.ActiveNativeRouteInputLayerNameForTest, routeInputBefore, StringComparison.Ordinal)
                        || !string.Equals(shellHost.ActiveNativeRouteOutputLayerNameForTest, routeOutputBefore, StringComparison.Ordinal))
                    {
                        throw new InvalidOperationException(
                            scenario + " changed Preview/Run, layers, active layer, or routing. "
                            + $"Runs={previewRunsBefore}->{shellHost.NativePreviewRunCount}, "
                            + $"Layers={layerCountBefore}->{shellHost.LayerDocumentCount}, "
                            + $"Active='{activeLayerBefore}'->'{shellHost.ActiveHostLayerTitle}', "
                            + $"Route='{routeInputBefore}->{routeOutputBefore}'->"
                            + $"'{shellHost.ActiveNativeRouteInputLayerNameForTest}->{shellHost.ActiveNativeRouteOutputLayerNameForTest}'.");
                    }
                }

                void SelectPipeline(string name)
                {
                    OpenVisionRecipePipelineOption option = shellHost.RecipeCommands.PipelineOptions
                        .FirstOrDefault(item => string.Equals(item.PipelineName, name, StringComparison.Ordinal))
                        ?? throw new InvalidOperationException("Recipe change-safety pipeline was not found: " + name);
                    shellHost.RecipeCommands.SelectedPipelineOption = option;
                    Pump(80);
                }

                BlobProperty LoadBlobStep(int zeroBasedIndex)
                {
                    IReadOnlyList<OpenVisionRecipePipelineStepPreview> steps =
                        shellHost.RecipeCommands.SelectedRecipeSummary.PipelinePreviewSteps;
                    if (zeroBasedIndex < 0 || zeroBasedIndex >= steps.Count)
                    {
                        throw new InvalidOperationException(
                            $"Recipe change-safety Step index was invalid: {zeroBasedIndex}/{steps.Count}.");
                    }

                    shellHost.RecipeCommands.SelectedPipelinePreviewStep = steps[zeroBasedIndex];
                    shellHost.RecipeCommands.LoadSelectedStepParametersCommand.Execute(null);
                    Pump(80);
                    return shellHost.RecipeCommands.SelectedStepEditObject as BlobProperty
                        ?? throw new InvalidOperationException("Recipe change-safety Blob editor did not load.");
                }

                void MakeDirty(BlobProperty property, int value = editedMinArea)
                {
                    property.MIN_AREA = value;
                    shellHost.RecipeCommands.MarkSelectedStepEditDirty();
                    Pump(40);
                    if (!shellHost.RecipeCommands.IsSelectedStepEditDirty
                        || property.MIN_AREA != value)
                    {
                        throw new InvalidOperationException(
                            "Recipe change-safety could not establish a dirty edit session.");
                    }
                }

                shellHost.SetRecipeManagerOpenForTest(true);
                Pump(100);
                ToggleButton advancedToggle = FindNamedVisualChild<ToggleButton>(
                    shellHost,
                    "recipeAdvancedReviewToggle")
                    ?? throw new InvalidOperationException("Recipe change-safety advanced review toggle was not found.");
                advancedToggle.IsChecked = true;
                Pump(80);
                TabItem pipelineTab = FindNamedVisualChild<TabItem>(shellHost, "tabRecipePipeline")
                    ?? throw new InvalidOperationException("Recipe change-safety Pipeline tab was not found.");
                TabItem xmlStepsTab = FindNamedVisualChild<TabItem>(shellHost, "tabRecipePipelineXmlSteps")
                    ?? throw new InvalidOperationException("Recipe change-safety XML/Step tab was not found.");
                ScrollViewer pipelineScrollViewer = FindNamedVisualChild<ScrollViewer>(
                    shellHost,
                    "recipePipelineTabScrollViewer")
                    ?? throw new InvalidOperationException("Recipe change-safety Pipeline scroll viewer was not found.");
                pipelineTab.IsSelected = true;
                xmlStepsTab.IsSelected = true;
                Pump(80);

                void MakeDirtyThroughPropertyGrid(BlobProperty property, int value)
                {
                    TextBox editor = FindVisualChildren<TextBox>(shellHost)
                        .Single(item => item.IsVisible
                            && item.IsEnabled
                            && string.Equals(
                                item.Text,
                                property.MIN_AREA.ToString(CultureInfo.InvariantCulture),
                                StringComparison.Ordinal));
                    editor.Focus();
                    editor.Text = value.ToString(CultureInfo.InvariantCulture);
                    Pump(40);
                    advancedToggle.Focus();
                    Pump(80);
                    shellHost.RecipeCommands.MarkSelectedStepEditDirty();
                    if (!shellHost.RecipeCommands.IsSelectedStepEditDirty
                        || property.MIN_AREA != value)
                    {
                        throw new InvalidOperationException(
                            "Recipe change-safety could not commit the visible PropertyGrid edit. "
                            + $"Model={property.MIN_AREA}, Editor='{editor.Text}', Expected={value}.");
                    }
                }

                SelectPipeline(pipelineA);
                BlobProperty stepEdit = LoadBlobStep(0);
                MakeDirty(stepEdit);
                OpenVisionRecipePipelineStepPreview originalStep =
                    shellHost.RecipeCommands.SelectedPipelinePreviewStep;
                object originalEditObject = shellHost.RecipeCommands.SelectedStepEditObject;
                OpenVisionRecipePipelineStepPreview nextStep =
                    shellHost.RecipeCommands.SelectedRecipeSummary.PipelinePreviewSteps[1];

                shellHost.QueuePendingRecipeEditDecisionForTest(
                    OpenVisionRecipePendingEditDecision.Cancel);
                shellHost.RecipeCommands.SelectedPipelinePreviewStep = nextStep;
                Pump(80);
                if (shellHost.RecipeCommands.SelectedPipelinePreviewStep?.Index != originalStep.Index
                    || !ReferenceEquals(shellHost.RecipeCommands.SelectedStepEditObject, originalEditObject)
                    || !shellHost.RecipeCommands.IsSelectedStepEditDirty
                    || stepEdit.MIN_AREA != editedMinArea)
                {
                    throw new InvalidOperationException(
                        "Cancel did not preserve the selected Step and dirty editor.");
                }
                pipelineScrollViewer.ScrollToBottom();
                Pump(80);
                SaveVisibleAutomationElementPng(
                    shellHost,
                    "HostRecipeManagerPanel",
                    outputPath,
                    "01-step-cancel-preserves-dirty.png");

                shellHost.QueuePendingRecipeEditDecisionForTest(
                    OpenVisionRecipePendingEditDecision.Discard);
                shellHost.RecipeCommands.SelectedPipelinePreviewStep = nextStep;
                Pump(80);
                if (shellHost.RecipeCommands.SelectedPipelinePreviewStep?.Index != nextStep.Index
                    || shellHost.RecipeCommands.IsSelectedStepEditDirty
                    || shellHost.RecipeCommands.SelectedStepEditObject != null
                    || VisionPipelineStorage.Load(recipeA, pipelineA).Steps[0].Parameters["MIN_AREA"]
                        != originalMinArea.ToString(CultureInfo.InvariantCulture))
                {
                    throw new InvalidOperationException(
                        "Discard did not move to the requested Step while preserving stored XML.");
                }

                const int stepAppliedMinArea = 401;
                BlobProperty stepApplyEdit = LoadBlobStep(0);
                MakeDirtyThroughPropertyGrid(stepApplyEdit, stepAppliedMinArea);
                nextStep = shellHost.RecipeCommands.SelectedRecipeSummary.PipelinePreviewSteps[1];
                shellHost.QueuePendingRecipeEditDecisionForTest(
                    OpenVisionRecipePendingEditDecision.ApplyAndContinue);
                shellHost.RecipeCommands.SelectedPipelinePreviewStep = nextStep;
                Pump(100);
                if (shellHost.RecipeCommands.SelectedPipelinePreviewStep?.Index != nextStep.Index
                    || shellHost.RecipeCommands.IsSelectedStepEditDirty
                    || VisionPipelineStorage.Load(recipeA, pipelineA).Steps[0].Parameters["MIN_AREA"]
                        != stepAppliedMinArea.ToString(CultureInfo.InvariantCulture))
                {
                    throw new InvalidOperationException(
                        "Apply and continue did not persist XML before the Step transition.");
                }

                SelectPipeline(pipelineA);
                BlobProperty pipelineEdit = LoadBlobStep(0);
                MakeDirty(pipelineEdit);
                OpenVisionRecipePipelineOption alternativeOption = shellHost.RecipeCommands.PipelineOptions
                    .First(item => string.Equals(
                        item.PipelineName,
                        pipelineAAlternative,
                        StringComparison.Ordinal));
                shellHost.QueuePendingRecipeEditDecisionForTest(
                    OpenVisionRecipePendingEditDecision.Cancel);
                shellHost.RecipeCommands.SelectedPipelineOption = alternativeOption;
                Pump(80);
                if (!string.Equals(
                        shellHost.RecipeCommands.SelectedPipelineOption?.PipelineName,
                        pipelineA,
                        StringComparison.Ordinal)
                    || !shellHost.RecipeCommands.IsSelectedStepEditDirty
                    || !ReferenceEquals(shellHost.RecipeCommands.SelectedStepEditObject, pipelineEdit))
                {
                    throw new InvalidOperationException(
                        "Cancel did not preserve the Pipeline and dirty editor.");
                }

                shellHost.QueuePendingRecipeEditDecisionForTest(
                    OpenVisionRecipePendingEditDecision.Discard);
                shellHost.RecipeCommands.SelectedPipelineOption = alternativeOption;
                Pump(80);
                if (!string.Equals(
                        shellHost.RecipeCommands.SelectedPipelineOption?.PipelineName,
                        pipelineAAlternative,
                        StringComparison.Ordinal)
                    || shellHost.RecipeCommands.IsSelectedStepEditDirty
                    || shellHost.RecipeCommands.SelectedStepEditObject != null)
                {
                    throw new InvalidOperationException(
                        "Discard did not move to the requested Pipeline.");
                }

                const int pipelineAppliedMinArea = 402;
                SelectPipeline(pipelineA);
                BlobProperty pipelineApplyEdit = LoadBlobStep(0);
                MakeDirtyThroughPropertyGrid(pipelineApplyEdit, pipelineAppliedMinArea);
                shellHost.QueuePendingRecipeEditDecisionForTest(
                    OpenVisionRecipePendingEditDecision.ApplyAndContinue);
                shellHost.RecipeCommands.SelectedPipelineOption = alternativeOption;
                Pump(100);
                if (!string.Equals(
                        shellHost.RecipeCommands.SelectedPipelineOption?.PipelineName,
                        pipelineAAlternative,
                        StringComparison.Ordinal)
                    || shellHost.RecipeCommands.IsSelectedStepEditDirty
                    || VisionPipelineStorage.Load(recipeA, pipelineA).Steps[0].Parameters["MIN_AREA"]
                        != pipelineAppliedMinArea.ToString(CultureInfo.InvariantCulture))
                {
                    throw new InvalidOperationException(
                        "Apply and continue did not persist XML before the Pipeline transition.");
                }

                SelectPipeline(pipelineA);
                BlobProperty recipeApplyEdit = LoadBlobStep(0);
                pipelineScrollViewer.ScrollToBottom();
                Pump(80);
                MakeDirtyThroughPropertyGrid(recipeApplyEdit, editedMinArea);
                shellHost.QueuePendingRecipeEditDecisionForTest(
                    OpenVisionRecipePendingEditDecision.ApplyAndContinue);
                shellHost.RecipeCommands.SelectedRecipeName = recipeB;
                Pump(140);
                string savedRecipeAValue = VisionPipelineStorage.Load(recipeA, pipelineA)
                    .Steps[0]
                    .Parameters["MIN_AREA"];
                if (!string.Equals(shellHost.SelectedRecipeNameForTest, recipeB, StringComparison.Ordinal)
                    || shellHost.RecipeCommands.IsSelectedStepEditDirty
                    || savedRecipeAValue != editedMinArea.ToString(CultureInfo.InvariantCulture))
                {
                    throw new InvalidOperationException(
                        "Apply and continue did not persist XML before the Recipe transition. "
                        + $"Selected='{shellHost.SelectedRecipeNameForTest}/{recipeB}', "
                        + $"Dirty={shellHost.RecipeCommands.IsSelectedStepEditDirty}, "
                        + $"Stored={savedRecipeAValue}/{editedMinArea}, "
                        + $"Status='{shellHost.RecipeCommands.SelectedStepEditStatusText}'.");
                }

                SelectPipeline(pipelineB);
                BlobProperty recipeCancelEdit = LoadBlobStep(0);
                MakeDirty(recipeCancelEdit, editedMinArea + 10);
                object? recipeCancelEditObject = shellHost.RecipeCommands.SelectedStepEditObject;
                shellHost.QueuePendingRecipeEditDecisionForTest(
                    OpenVisionRecipePendingEditDecision.Cancel);
                shellHost.RecipeCommands.SelectedRecipeName = recipeA;
                Pump(100);
                if (!string.Equals(shellHost.SelectedRecipeNameForTest, recipeB, StringComparison.Ordinal)
                    || !shellHost.RecipeCommands.IsSelectedStepEditDirty
                    || !ReferenceEquals(shellHost.RecipeCommands.SelectedStepEditObject, recipeCancelEditObject)
                    || recipeCancelEdit.MIN_AREA != editedMinArea + 10)
                {
                    throw new InvalidOperationException(
                        "Cancel did not preserve the Recipe and dirty editor.");
                }

                shellHost.QueuePendingRecipeEditDecisionForTest(
                    OpenVisionRecipePendingEditDecision.Discard);
                shellHost.RecipeCommands.SelectedRecipeName = recipeA;
                Pump(100);
                if (!string.Equals(shellHost.SelectedRecipeNameForTest, recipeA, StringComparison.Ordinal)
                    || shellHost.RecipeCommands.IsSelectedStepEditDirty
                    || VisionPipelineStorage.Load(recipeB, pipelineB).Steps[0].Parameters["MIN_AREA"]
                        != originalMinArea.ToString(CultureInfo.InvariantCulture))
                {
                    throw new InvalidOperationException(
                        "Discard did not move to the requested Recipe while preserving stored XML.");
                }

                shellHost.RecipeCommands.SelectedRecipeName = recipeB;
                Pump(100);
                SelectPipeline(pipelineB);
                BlobProperty managerEdit = LoadBlobStep(0);
                MakeDirty(managerEdit, editedMinArea + 1);
                object? managerEditObject = shellHost.RecipeCommands.SelectedStepEditObject;
                shellHost.QueuePendingRecipeEditDecisionForTest(
                    OpenVisionRecipePendingEditDecision.Cancel);
                shellHost.SetRecipeManagerOpenForTest(false);
                Pump(100);
                if (!shellHost.IsRecipeManagerOpenForTest
                    || !shellHost.RecipeCommands.IsSelectedStepEditDirty
                    || !ReferenceEquals(shellHost.RecipeCommands.SelectedStepEditObject, managerEditObject)
                    || managerEdit.MIN_AREA != editedMinArea + 1)
                {
                    throw new InvalidOperationException(
                        "Cancel did not keep Recipe Manager and its dirty editor open.");
                }

                shellHost.QueuePendingRecipeEditDecisionForTest(
                    OpenVisionRecipePendingEditDecision.Discard);
                shellHost.SetRecipeManagerOpenForTest(false);
                Pump(100);
                if (shellHost.IsRecipeManagerOpenForTest
                    || shellHost.RecipeCommands.IsSelectedStepEditDirty
                    || shellHost.RecipeCommands.SelectedStepEditObject != null
                    || VisionPipelineStorage.Load(recipeB, pipelineB).Steps[0].Parameters["MIN_AREA"]
                        != originalMinArea.ToString(CultureInfo.InvariantCulture))
                {
                    throw new InvalidOperationException(
                        "Discard did not close Recipe Manager while preserving stored XML.");
                }

                shellHost.SetRecipeManagerOpenForTest(true);
                Pump(100);
                advancedToggle.IsChecked = true;
                pipelineTab.IsSelected = true;
                xmlStepsTab.IsSelected = true;
                SelectPipeline(pipelineB);
                const int managerAppliedMinArea = 403;
                BlobProperty managerApplyEdit = LoadBlobStep(0);
                MakeDirtyThroughPropertyGrid(managerApplyEdit, managerAppliedMinArea);
                shellHost.QueuePendingRecipeEditDecisionForTest(
                    OpenVisionRecipePendingEditDecision.ApplyAndContinue);
                shellHost.SetRecipeManagerOpenForTest(false);
                Pump(120);
                if (shellHost.IsRecipeManagerOpenForTest
                    || shellHost.RecipeCommands.IsSelectedStepEditDirty
                    || VisionPipelineStorage.Load(recipeB, pipelineB).Steps[0].Parameters["MIN_AREA"]
                        != managerAppliedMinArea.ToString(CultureInfo.InvariantCulture))
                {
                    throw new InvalidOperationException(
                        "Apply and continue did not persist XML before closing Recipe Manager.");
                }

                VisionPipelineStorage.Save(recipeB, CreateBlobPipeline(pipelineB, 1));
                shellHost.SetRecipeManagerOpenForTest(true);
                Pump(100);
                advancedToggle.IsChecked = true;
                pipelineTab.IsSelected = true;
                xmlStepsTab.IsSelected = true;
                SelectPipeline(pipelineB);
                BlobProperty failedApplyEdit = LoadBlobStep(0);
                MakeDirty(failedApplyEdit, editedMinArea + 2);
                object? failedEditObject = shellHost.RecipeCommands.SelectedStepEditObject;
                shellHost.FailNextRecipeStepEditCommitForTest();
                shellHost.QueuePendingRecipeEditDecisionForTest(
                    OpenVisionRecipePendingEditDecision.ApplyAndContinue);
                shellHost.RecipeCommands.SelectedRecipeName = recipeA;
                Pump(120);
                if (!string.Equals(shellHost.SelectedRecipeNameForTest, recipeB, StringComparison.Ordinal)
                    || !shellHost.RecipeCommands.IsSelectedStepEditDirty
                    || !ReferenceEquals(shellHost.RecipeCommands.SelectedStepEditObject, failedEditObject)
                    || failedApplyEdit.MIN_AREA != editedMinArea + 2
                    || VisionPipelineStorage.Load(recipeB, pipelineB).Steps[0].Parameters["MIN_AREA"]
                        != originalMinArea.ToString(CultureInfo.InvariantCulture))
                {
                    throw new InvalidOperationException(
                        "A failed apply did not keep the current Recipe and dirty editor unchanged.");
                }
                pipelineScrollViewer.ScrollToBottom();
                Pump(80);
                SaveVisibleAutomationElementPng(
                    shellHost,
                    "HostRecipeManagerPanel",
                    outputPath,
                    "02-failed-apply-keeps-dirty.png");

                shellHost.QueuePendingRecipeEditDecisionForTest(
                    OpenVisionRecipePendingEditDecision.Discard);
                shellHost.RecipeCommands.SelectedRecipeName = recipeA;
                Pump(120);
                shellHost.RecipeCommands.SelectedRecipeName = recipeB;
                Pump(120);
                SelectPipeline(pipelineB);
                BlobProperty failedSaveEdit = LoadBlobStep(0);
                pipelineScrollViewer.ScrollToBottom();
                Pump(80);
                int failedRoundTripMinArea = editedMinArea + 3;
                MakeDirtyThroughPropertyGrid(failedSaveEdit, failedRoundTripMinArea);
                object? failedSaveEditObject = shellHost.RecipeCommands.SelectedStepEditObject;

                shellHost.FailNextRecipeStepSaveForTest();
                shellHost.QueuePendingRecipeEditDecisionForTest(
                    OpenVisionRecipePendingEditDecision.ApplyAndContinue);
                shellHost.RecipeCommands.SelectedRecipeName = recipeA;
                Pump(140);
                string storedAfterFailedSave = VisionPipelineStorage.Load(recipeB, pipelineB)
                    .Steps[0]
                    .Parameters["MIN_AREA"];
                if (!string.Equals(shellHost.SelectedRecipeNameForTest, recipeB, StringComparison.Ordinal)
                    || !shellHost.RecipeCommands.IsSelectedStepEditDirty
                    || !ReferenceEquals(shellHost.RecipeCommands.SelectedStepEditObject, failedSaveEditObject)
                    || failedSaveEdit.MIN_AREA != failedRoundTripMinArea
                    || storedAfterFailedSave != originalMinArea.ToString(CultureInfo.InvariantCulture)
                    || shellHost.RecipeCommands.SelectedStepEditStatusText.IndexOf(
                        "Forced XML save failure",
                        StringComparison.Ordinal) < 0)
                {
                    throw new InvalidOperationException(
                        "A failed XML save did not block the transition, retain the dirty editor, "
                        + "and preserve the previous stored XML. "
                        + $"Selected='{shellHost.SelectedRecipeNameForTest}/{recipeB}', "
                        + $"Dirty={shellHost.RecipeCommands.IsSelectedStepEditDirty}, "
                        + $"Model={failedSaveEdit.MIN_AREA}/{failedRoundTripMinArea}, "
                        + $"Stored={storedAfterFailedSave}/{originalMinArea}, "
                        + $"Status='{shellHost.RecipeCommands.SelectedStepEditStatusText}'.");
                }
                pipelineScrollViewer.ScrollToBottom();
                Pump(80);
                SaveVisibleAutomationElementPng(
                    shellHost,
                    "HostRecipeManagerPanel",
                    outputPath,
                    "03-failed-save-keeps-dirty.png");

                shellHost.QueuePendingRecipeEditDecisionForTest(
                    OpenVisionRecipePendingEditDecision.Discard);
                shellHost.RecipeCommands.SelectedRecipeName = recipeA;
                Pump(120);
                shellHost.RecipeCommands.SelectedRecipeName = recipeB;
                Pump(120);
                SelectPipeline(pipelineB);
                BlobProperty failedRoundTripEdit = LoadBlobStep(0);
                pipelineScrollViewer.ScrollToBottom();
                Pump(80);
                int failedValidationMinArea = editedMinArea + 4;
                MakeDirtyThroughPropertyGrid(failedRoundTripEdit, failedValidationMinArea);
                object? failedRoundTripEditObject = shellHost.RecipeCommands.SelectedStepEditObject;

                shellHost.FailNextRecipeStepRoundTripValidationForTest();
                shellHost.QueuePendingRecipeEditDecisionForTest(
                    OpenVisionRecipePendingEditDecision.ApplyAndContinue);
                shellHost.RecipeCommands.SelectedRecipeName = recipeA;
                Pump(140);
                string restoredRecipeBValue = VisionPipelineStorage.Load(recipeB, pipelineB)
                    .Steps[0]
                    .Parameters["MIN_AREA"];
                if (!string.Equals(shellHost.SelectedRecipeNameForTest, recipeB, StringComparison.Ordinal)
                    || !shellHost.RecipeCommands.IsSelectedStepEditDirty
                    || !ReferenceEquals(shellHost.RecipeCommands.SelectedStepEditObject, failedRoundTripEditObject)
                    || failedRoundTripEdit.MIN_AREA != failedValidationMinArea
                    || restoredRecipeBValue != originalMinArea.ToString(CultureInfo.InvariantCulture)
                    || shellHost.RecipeCommands.SelectedStepEditStatusText.IndexOf(
                        "복원",
                        StringComparison.Ordinal) < 0)
                {
                    throw new InvalidOperationException(
                        "A failed XML round-trip did not block the transition, retain the dirty editor, "
                        + "and restore the previous stored XML. "
                        + $"Selected='{shellHost.SelectedRecipeNameForTest}/{recipeB}', "
                        + $"Dirty={shellHost.RecipeCommands.IsSelectedStepEditDirty}, "
                        + $"Model={failedRoundTripEdit.MIN_AREA}/{failedValidationMinArea}, "
                        + $"Stored={restoredRecipeBValue}/{originalMinArea}, "
                        + $"Status='{shellHost.RecipeCommands.SelectedStepEditStatusText}'.");
                }
                pipelineScrollViewer.ScrollToBottom();
                Pump(80);
                SaveVisibleAutomationElementPng(
                    shellHost,
                    "HostRecipeManagerPanel",
                    outputPath,
                    "04-failed-roundtrip-restores-xml.png");

                AssertNoWorkspaceSideEffects("Recipe change-safety decisions");
                string diagnosticsDirectory = Path.Combine(
                    Path.GetDirectoryName(outputPath) ?? ".",
                    Path.GetFileNameWithoutExtension(outputPath) + ".diagnostics");
                Directory.CreateDirectory(diagnosticsDirectory);
                File.WriteAllLines(
                    Path.Combine(diagnosticsDirectory, "recipe_change_safety_results.txt"),
                    new[]
                    {
                        "StepCancel=Preserved",
                        "StepDiscard=TransitionedWithoutSave",
                        "StepApplyAndContinue=SavedThenTransitioned",
                        "PipelineCancel=Preserved",
                        "PipelineDiscard=TransitionedWithoutSave",
                        "PipelineApplyAndContinue=SavedThenTransitioned",
                        "RecipeCancel=Preserved",
                        "RecipeDiscard=TransitionedWithoutSave",
                        "RecipeApplyAndContinue=SavedThenTransitioned",
                        "ManagerCloseCancel=StayedOpen",
                        "ManagerCloseDiscard=ClosedWithoutSave",
                        "ManagerCloseApplyAndContinue=SavedThenClosed",
                        "FailedApply=TransitionBlockedAndDirtyPreserved",
                        "FailedSave=TransitionBlockedAndStoredXmlPreserved",
                        "FailedRoundTrip=TransitionBlockedAndStoredXmlRestored",
                        "PreviewRunSideEffects=None",
                        "LayerSideEffects=None",
                        "RouteSideEffects=None"
                    });
            }, captureFloatingToolWindow: false, captureScreen: true);
        }
        finally
        {
            RecipeWorkspaceService.DeleteVisionWorkspace(recipeA);
            RecipeWorkspaceService.DeleteVisionWorkspace(recipeB);
        }
    }

    private static void AssertBasicImagePropertyMapperRoundTrip()
    {
        VisionPipelineStep threshold = CreateBasicImageRoundTripStep(
            "ThresholdTool",
            "ThresholdInput",
            "ThresholdOutput");
        threshold.Enabled = false;
        threshold.UseAcceptance = true;
        threshold.ExpectedSuccess = false;
        threshold.MaxElapsedMilliseconds = 91D;
        threshold.RequiredMessageText = "threshold-reviewed";
        threshold.AcceptanceMetricName = "ThresholdValue";
        threshold.UseAcceptanceMetricMinimum = true;
        threshold.AcceptanceMetricMinimum = 33D;
        threshold.UseAcceptanceMetricMaximum = true;
        threshold.AcceptanceMetricMaximum = 144D;
        SetParameters(
            threshold,
            (nameof(ThresholdToolProperty.Mode), ThresholdToolMode.Range),
            (nameof(ThresholdToolProperty.Threshold), 101D),
            (nameof(ThresholdToolProperty.MaxValue), 240D),
            (nameof(ThresholdToolProperty.ThresholdType), OpenCvSharp.ThresholdTypes.BinaryInv),
            (nameof(ThresholdToolProperty.RangeMin), 33),
            (nameof(ThresholdToolProperty.RangeMax), 144),
            (nameof(ThresholdToolProperty.Invert), true),
            (nameof(ThresholdToolProperty.AdaptiveType), OpenCvSharp.AdaptiveThresholdTypes.GaussianC),
            (nameof(ThresholdToolProperty.AdaptiveThresholdType), OpenCvSharp.ThresholdTypes.BinaryInv),
            (nameof(ThresholdToolProperty.BlockSize), 31),
            (nameof(ThresholdToolProperty.Weight), 7));
        AssertBasicImageRoundTrip(threshold, "Threshold");

        VisionPipelineStep morphology = CreateBasicImageRoundTripStep(
            "MorphologyTool",
            "MorphologyInput",
            "MorphologyOutput");
        SetParameters(
            morphology,
            (nameof(MorphologyToolProperty.Shape), OpenCvSharp.MorphShapes.Ellipse),
            (nameof(MorphologyToolProperty.Operator), OpenCvSharp.MorphTypes.Close),
            (nameof(MorphologyToolProperty.KernelWidth), 5),
            (nameof(MorphologyToolProperty.KernelHeight), 7),
            (nameof(MorphologyToolProperty.Iterations), 2));
        AssertBasicImageRoundTrip(morphology, "Morphology");

        VisionPipelineStep filter = CreateBasicImageRoundTripStep(
            "FilterTool",
            "FilterInput",
            "FilterOutput");
        SetParameters(
            filter,
            (nameof(FilterToolProperty.FilterType), FilterToolType.BilateralFilter),
            (nameof(FilterToolProperty.KernelWidth), 5),
            (nameof(FilterToolProperty.KernelHeight), 7),
            (nameof(FilterToolProperty.MedianKernelSize), 9),
            (nameof(FilterToolProperty.Diameter), 11),
            (nameof(FilterToolProperty.SigmaColor), 13),
            (nameof(FilterToolProperty.SigmaSpace), 17),
            (nameof(FilterToolProperty.BorderType), OpenCvSharp.BorderTypes.Reflect));
        AssertBasicImageRoundTrip(filter, "Filter");

        VisionPipelineStep edge = CreateBasicImageRoundTripStep(
            "EdgeTool",
            "EdgeInput",
            "EdgeOutput");
        SetParameters(
            edge,
            (nameof(EdgeDetectionToolProperty.EdgeType), EdgeDetectionToolType.Scharr),
            (nameof(EdgeDetectionToolProperty.CannyThresholdLow), 44),
            (nameof(EdgeDetectionToolProperty.CannyThresholdHigh), 188),
            (nameof(EdgeDetectionToolProperty.CannyApertureSize), 5),
            (nameof(EdgeDetectionToolProperty.UseL2Gradient), false),
            (nameof(EdgeDetectionToolProperty.SobelDegreeX), 1),
            (nameof(EdgeDetectionToolProperty.SobelDegreeY), 0),
            (nameof(EdgeDetectionToolProperty.SobelKernelSize), 3),
            (nameof(EdgeDetectionToolProperty.ScharrDegreeX), 0),
            (nameof(EdgeDetectionToolProperty.ScharrDegreeY), 1),
            (nameof(EdgeDetectionToolProperty.LaplacianKernelSize), 3));
        AssertBasicImageRoundTrip(edge, "EdgeDetection");
    }

    private static VisionPipelineStep CreateBasicImageRoundTripStep(
        string toolType,
        string inputLayer,
        string outputLayer)
    {
        return new VisionPipelineStep
        {
            Name = toolType + " Round Trip",
            ToolType = toolType,
            InputLayer = inputLayer,
            OutputLayer = outputLayer
        };
    }

    private static void SetParameters(
        VisionPipelineStep step,
        params (string Key, object Value)[] values)
    {
        foreach ((string key, object value) in values)
        {
            step.Parameters[key] = Convert.ToString(
                value,
                CultureInfo.InvariantCulture) ?? string.Empty;
        }
    }

    private static void AssertBasicImageRoundTrip(
        VisionPipelineStep step,
        string expectedToolType)
    {
        string inputLayer = step.InputLayer;
        string outputLayer = step.OutputLayer;
        bool enabled = step.Enabled;
        bool useAcceptance = step.UseAcceptance;
        bool expectedSuccess = step.ExpectedSuccess;
        double maxElapsedMilliseconds = step.MaxElapsedMilliseconds;
        string requiredMessageText = step.RequiredMessageText;
        string acceptanceMetricName = step.AcceptanceMetricName;
        bool useMinimum = step.UseAcceptanceMetricMinimum;
        double minimum = step.AcceptanceMetricMinimum;
        bool useMaximum = step.UseAcceptanceMetricMaximum;
        double maximum = step.AcceptanceMetricMaximum;
        Dictionary<string, string> expectedParameters = new(
            step.Parameters,
            StringComparer.OrdinalIgnoreCase);

        object property = VisionPipelineStepPropertyMapper.CreateProperty(step)
            ?? throw new InvalidOperationException(
                step.ToolType + " selected-Step property object was not created.");
        foreach ((string key, string value) in expectedParameters)
        {
            AssertPropertyValue(property, key, value);
        }

        if (!VisionPipelineStepPropertyMapper.ApplyProperty(step, property))
        {
            throw new InvalidOperationException(
                step.ToolType + " selected-Step property object did not apply back.");
        }

        if (!string.Equals(step.ToolType, expectedToolType, StringComparison.Ordinal)
            || !string.Equals(step.InputLayer, inputLayer, StringComparison.Ordinal)
            || !string.Equals(step.OutputLayer, outputLayer, StringComparison.Ordinal)
            || step.Enabled != enabled
            || step.UseAcceptance != useAcceptance
            || step.ExpectedSuccess != expectedSuccess
            || Math.Abs(step.MaxElapsedMilliseconds - maxElapsedMilliseconds) > 0.0001D
            || !string.Equals(step.RequiredMessageText, requiredMessageText, StringComparison.Ordinal)
            || !string.Equals(step.AcceptanceMetricName, acceptanceMetricName, StringComparison.Ordinal)
            || step.UseAcceptanceMetricMinimum != useMinimum
            || Math.Abs(step.AcceptanceMetricMinimum - minimum) > 0.0001D
            || step.UseAcceptanceMetricMaximum != useMaximum
            || Math.Abs(step.AcceptanceMetricMaximum - maximum) > 0.0001D)
        {
            throw new InvalidOperationException(
                expectedToolType + " selected-Step metadata or routing did not round-trip.");
        }

        foreach ((string key, string value) in expectedParameters)
        {
            AssertParameterValue(step, key, value);
        }
    }

    private static CaptureResult CaptureShellHostPipelineReviewInputState(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        string recipeName = "Smoke_WpfPipelineReviewInputState_" + Guid.NewGuid().ToString("N");
        OpenVisionShellHostView shellHost = CreateShellHost(recipeName);
        VisionPipeline pipeline = CreatePipelineReviewInputStatePipeline();
        VisionPipelineStorage.Save(recipeName, pipeline);
        VisionPipelineStorage.SaveActivePipelineName(recipeName, pipeline.Name);
        return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
        {
            shellHost.SelectToolForTest(VISION_MENU.Pipeline);
            Pump(24);
            Window reviewWindow = GetActiveFloatingToolWindow("Pipeline review input state");
            shellHost.SelectPipelineReviewStepForTest(1, OpenVisionLab.Pipeline.Controls.PipelineFlowPreviewMode.Overlay);
            Pump(16);

            string missingInputStatus = OpenVisionLanguageService.T("PipelineReview.Status.InputMissing");
            string missingInputFlow = string.Format(
                CultureInfo.CurrentCulture,
                OpenVisionLanguageService.T("PipelineReview.Flow.MissingInputFormat"),
                "Unloaded_External");
            string missingInputReadiness = string.Format(
                CultureInfo.CurrentCulture,
                OpenVisionLanguageService.T("PipelineReview.Readiness.MissingInputFormat"),
                "Unloaded_External");
            if (shellHost.PipelineReviewStepCount != 2
                || !shellHost.PipelineReviewSelectedStepName.Contains("Missing External Input", StringComparison.Ordinal)
                || !string.Equals(shellHost.PipelineReviewSelectedStatusText, missingInputStatus, StringComparison.Ordinal)
                || !shellHost.PipelineReviewFlowSummaryText.Contains(missingInputFlow, StringComparison.Ordinal)
                || !string.Equals(
                    ReadVisibleTextByAutomationId(reviewWindow, "PipelineReviewReadinessInputStatus"),
                    missingInputReadiness,
                    StringComparison.Ordinal)
                || shellHost.HasPipelineReviewInputPreview
                || shellHost.NativePreviewRunCount != 0)
            {
                throw new InvalidOperationException(
                    "Pipeline review did not distinguish the missing external input without execution. "
                    + $"Steps={shellHost.PipelineReviewStepCount}, Selected='{shellHost.PipelineReviewSelectedStepName}', "
                    + $"Status='{shellHost.PipelineReviewSelectedStatusText}', Flow='{shellHost.PipelineReviewFlowSummaryText}', "
                    + $"InputPreview={shellHost.HasPipelineReviewInputPreview}, Runs={shellHost.NativePreviewRunCount}");
            }
        });
    }

    private static CaptureResult CaptureShellHostAffineTransformTool(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        OpenVisionShellHostView shellHost = CreateShellHost("Smoke_WpfShellHostAffineTransform");
        return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
        {
            int previewCountBeforeOpen = shellHost.NativePreviewRunCount;
            shellHost.SelectToolForTest(VISION_MENU.AffineTransform);
            Pump(20);
            if (!shellHost.IsNativeDocumentActive
                || !shellHost.ActiveNativeDocumentTypeName.Contains("AffineTransformToolWpfView", StringComparison.Ordinal))
            {
                throw new InvalidOperationException("AffineTransform did not open the PropertyGrid Tool View.");
            }

            shellHost.ConfigureActiveAffineTransformForTest(property =>
            {
                property.SourcePoint1X = 20;
                property.SourcePoint1Y = 20;
                property.SourcePoint2X = 200;
                property.SourcePoint2Y = 20;
                property.SourcePoint3X = 20;
                property.SourcePoint3Y = 180;
                property.DestinationPoint1X = 30;
                property.DestinationPoint1Y = 25;
                property.DestinationPoint2X = 210;
                property.DestinationPoint2Y = 35;
                property.DestinationPoint3X = 40;
                property.DestinationPoint3Y = 185;
                property.MinimumSourceTriangleArea = 100;
                property.MinimumDestinationTriangleArea = 100;
                property.MinimumValidPixelRatio = 0.7;
            });
            Pump(20);

            if (shellHost.NativePreviewRunCount != previewCountBeforeOpen || shellHost.HasNativePreviewResult)
            {
                throw new InvalidOperationException(
                    "AffineTransform open/property changes must not auto-run Preview. "
                    + $"Before={previewCountBeforeOpen}, After={shellHost.NativePreviewRunCount}, HasResult={shellHost.HasNativePreviewResult}.");
            }

            foreach (string inheritedLabel in new[] { "Pixel / mm", "이진화 사용", "적응형 이진화 사용" })
            {
                if (FloatingToolTextContains(inheritedLabel))
                {
                    throw new InvalidOperationException(
                        "AffineTransform PropertyGrid exposed an unrelated inherited field: " + inheritedLabel);
                }
            }

            shellHost.RunActiveNativePreviewForTest();
            Pump(28);
            if (!shellHost.HasNativePreviewResult
                || shellHost.NativePreviewRunCount != previewCountBeforeOpen + 1
                || !string.Equals(shellHost.ActiveNativeRouteOutputLayerNameForTest, "AffineTransform_Preview", StringComparison.OrdinalIgnoreCase)
                || string.Equals(shellHost.ActiveNativeRouteInputLayerNameForTest, "AffineTransform_Preview", StringComparison.OrdinalIgnoreCase))
            {
                throw new InvalidOperationException(
                    "AffineTransform explicit Preview did not preserve the expected route contract. "
                    + $"Input={shellHost.ActiveNativeRouteInputLayerNameForTest}, "
                    + $"Output={shellHost.ActiveNativeRouteOutputLayerNameForTest}, "
                    + $"Runs={shellHost.NativePreviewRunCount}, Status={shellHost.ActiveNativeStatusText}.");
            }

            if (!shellHost.ActiveNativeStatusText.Contains("Preview OK", StringComparison.OrdinalIgnoreCase)
                || !shellHost.ActiveNativeResultReviewText.Contains("Affine 2x3", StringComparison.Ordinal)
                || !shellHost.ActiveNativeResultReviewText.Contains("유효 픽셀", StringComparison.Ordinal))
            {
                throw new InvalidOperationException(
                    "AffineTransform Preview did not publish its status and operator review card. "
                    + $"Status={shellHost.ActiveNativeStatusText}, Review={shellHost.ActiveNativeResultReviewText}.");
            }

            AssertFloatingInlinePreviewSlotCount("AffineTransform", 2);
        });
    }

    private static CaptureResult CaptureP213GeometryReview(string outputPath)
    {
        AssertP213GeometryCore(outputPath);
        using Bitmap preview = new(640, 420);
        using (Graphics graphics = Graphics.FromImage(preview))
        {
            graphics.Clear(DrawingColor.FromArgb(36, 43, 47));
            using System.Drawing.Pen featurePen = new(DrawingColor.Gold, 3f);
            using System.Drawing.Pen constructionPen = new(DrawingColor.DeepSkyBlue, 3f);
            graphics.DrawEllipse(featurePen, 145, 75, 210, 210);
            graphics.DrawLine(constructionPen, 250, 180, 500, 310);
            graphics.DrawLine(constructionPen, 420, 70, 420, 350);
        }

        OpenVisionPipelineReviewView view = new();
        view.SetSelectedStep(
            "03 Circle / Segment Clearance",
            "GeometryMeasure",
            "OK",
            "Reference",
            preview,
            "Geometry_Result",
            preview,
            "Typed same-run features in Reference coordinates",
            "CircleFeature/Circle -> DatumLine/Segment",
            "Explicit Run / GeometrySignedClearancePx=65.217");
        view.SetObjectResults(false, Array.Empty<VisionPipelineObjectResult>());
        view.SetGeometryResults(true, new[]
        {
            new VisionPipelineGeometryFeatureResult
            {
                SourceStep = "CircleFeature", FeatureName = "Circle", Kind = VisionPipelineGeometryKind.Circle,
                CoordinateLayer = "Reference", ImageWidth = 640, ImageHeight = 420,
                CenterX = 250, CenterY = 180, RadiusPx = 105,
                SupportCount = 176, SupportRatio = 0.978, CoverageDeg = 352, FitResidualPx = 0.42
            },
            new VisionPipelineGeometryFeatureResult
            {
                SourceStep = "DatumLine", FeatureName = "Segment", Kind = VisionPipelineGeometryKind.Segment,
                CoordinateLayer = "Reference", ImageWidth = 640, ImageHeight = 420,
                X1 = 420, Y1 = 70, X2 = 420, Y2 = 350, CenterX = 420, CenterY = 210,
                SupportCount = 36, SupportRatio = 1, FitResidualPx = 0.31
            },
            new VisionPipelineGeometryFeatureResult
            {
                SourceStep = "Clearance", FeatureName = "MeasureEnd", Kind = VisionPipelineGeometryKind.Point,
                CoordinateLayer = "Reference", ImageWidth = 640, ImageHeight = 420,
                X1 = 420, Y1 = 180, CenterX = 420, CenterY = 180,
                SupportCount = 1, SupportRatio = 1
            }
        });
        if (!view.SelectGeometryAtImagePointForTest(420D, 200D)
            || view.SelectedGeometryIdentityForTest != "DatumLine/Segment")
        {
            throw new InvalidOperationException("P213 drawing-to-row geometry selection failed.");
        }
        view.Measure(new System.Windows.Size(1180, 890));
        view.Arrange(new System.Windows.Rect(0, 0, 1180, 890));
        view.UpdateLayout();
        Pump(4);
        return CaptureElement(view, outputPath, 1180, 890);
    }

    private static CaptureResult CaptureCvr10MultiMatchMeanReview(string outputPath)
    {
        using Bitmap preview = new(640, 400);
        using (Graphics graphics = Graphics.FromImage(preview))
        {
            graphics.Clear(DrawingColor.FromArgb(28, 28, 28));
            (int X, int Y, bool Accepted)[] instances =
            {
                (130, 110, true),
                (390, 96, true),
                (150, 292, false),
                (410, 276, true)
            };
            using System.Drawing.Pen locatorPen = new(DrawingColor.Gainsboro, 3F);
            using System.Drawing.Pen okPen = new(DrawingColor.LimeGreen, 3F);
            using System.Drawing.Pen ngPen = new(DrawingColor.OrangeRed, 3F);
            for (int index = 0; index < instances.Length; index++)
            {
                (int x, int y, bool accepted) = instances[index];
                graphics.DrawRectangle(locatorPen, x - 20, y - 20, 40, 40);
                graphics.DrawLine(locatorPen, x - 12, y - 12, x + 12, y + 12);
                graphics.DrawEllipse(locatorPen, x - 11, y + 3, 12, 12);
                graphics.DrawRectangle(
                    accepted ? okPen : ngPen,
                    x + 40,
                    y - 2,
                    30,
                    24);
            }
        }

        VisionPipelineInstanceResult[] rows =
        {
            new() { Number = 1, InstanceId = "I01", SourceStep = "01 Locate Four Instances", Accepted = true, Score = 1, CenterX = 130, CenterY = 110, Angle = 0, Scale = 1, RoiCenterX = 185, RoiCenterY = 120, RoiWidth = 30, RoiHeight = 24, RoiAngle = 0, MeanValue = 225, ValidPixelRatio = 1 },
            new() { Number = 2, InstanceId = "I02", SourceStep = "01 Locate Four Instances", Accepted = true, Score = 1, CenterX = 390, CenterY = 96, Angle = 0, Scale = 1, RoiCenterX = 445, RoiCenterY = 106, RoiWidth = 30, RoiHeight = 24, RoiAngle = 0, MeanValue = 225, ValidPixelRatio = 0.573 },
            new() { Number = 3, InstanceId = "I03", SourceStep = "01 Locate Four Instances", Accepted = false, Score = 1, CenterX = 150, CenterY = 292, Angle = 0, Scale = 1, RoiCenterX = 205, RoiCenterY = 302, RoiWidth = 30, RoiHeight = 24, RoiAngle = 0, MeanValue = 65, ValidPixelRatio = 0.528, RejectReason = "Mean 65 is outside 170..255" },
            new() { Number = 4, InstanceId = "I04", SourceStep = "01 Locate Four Instances", Accepted = true, Score = 1, CenterX = 410, CenterY = 276, Angle = 0, Scale = 1, RoiCenterX = 465, RoiCenterY = 286, RoiWidth = 30, RoiHeight = 24, RoiAngle = 0, MeanValue = 225, ValidPixelRatio = 0.329 }
        };
        VisionPipelineStep step = new()
        {
            Name = "02 Inspect Every Instance Pad",
            ToolType = "MultiMatchMean",
            Enabled = true,
            InputLayer = "Main",
            OutputLayer = "InstanceInspection"
        };
        AddParameters(
            step,
            ("SOURCE_STEP", "01 Locate Four Instances"),
            ("RELATIVE_ROI", "170,108,30,24"),
            ("MIN_INSTANCES", "4"),
            ("MAX_INSTANCES", "4"),
            ("MIN_MEAN", "170"),
            ("MAX_MEAN", "255"),
            ("REQUIRE_ALL", "true"));

        OpenVisionPipelineReviewView view = new();
        int reviewRequests = 0;
        view.RunReviewRequested += (_, _) => reviewRequests++;
        view.SetPipelineHeader("CVR10 Multi-Instance Fan-Out", 2);
        view.SetRecipeContext("Deterministic Multi-Instance Review");
        view.SetReviewProgress("OK 0 / NG 1 / WAIT 0");
        view.SetSteps(new[]
        {
            new PipelineFlowStepItem
            {
                Index = 0,
                Name = "01 Locate Four Instances",
                ToolType = "Matching",
                InputLayer = "Main",
                OutputLayer = "InstanceMatches",
                FlowStateText = "Main -> InstanceMatches",
                StatusText = "OK",
                Status = PipelineFlowStepStatus.Passed,
                HasInputImage = true,
                HasOutputImage = true
            },
            new PipelineFlowStepItem
            {
                Index = 1,
                Name = "02 Inspect Every Instance Pad",
                ToolType = "MultiMatchMean",
                InputLayer = "Main",
                OutputLayer = "InstanceInspection",
                FlowStateText = "Branch Main -> InstanceInspection",
                StatusText = "NG",
                Status = PipelineFlowStepStatus.Failed,
                HasInputImage = true,
                HasOutputImage = true
            }
        });
        view.SelectStep(1, PipelineFlowPreviewMode.Overlay);
        view.SetNavigationState(1, 2);
        view.SetIssueNavigationState(true);
        view.SetSelectedStep(
            "02 Inspect Every Instance Pad",
            "MultiMatchMean",
            "NG",
            "Main",
            preview,
            "InstanceInspection",
            preview,
            "Matching fan-out / stable row-major I01..I04",
            "SOURCE_STEP=01 Locate Four Instances / RELATIVE_ROI=170,108,30,24 / REQUIRE_ALL=true",
            "Explicit Run / InstancePassCount=3 / InstanceFailCount=1 / InstanceAggregatePassed=0");
        view.SetValidation(
            "VALID",
            "Matching source and exact InstanceAggregatePassed=1 acceptance are valid.");
        view.SetResultSummary(
            "NG / 3 of 4 instances passed",
            "I03 rejected: Mean 65 is outside 170..255.");
        view.SetReviewGuide(new OpenVisionPipelineReviewGuideState(
            "2 / 2",
            "02 Inspect Every Instance Pad",
            "Review I03 and adjust the recipe only if the physical requirement changed.",
            "NG / one instance rejected",
            "Stable row-major instances I01..I04 were inspected in one explicit Run. I03 failed the fixed relative-ROI Mean range."));
        view.SetObjectResults(
            false,
            step,
            Array.Empty<VisionPipelineObjectResult>(),
            preview,
            preview);
        view.SetInstanceResults(true, rows);
        if (view.InstanceResultCountForTest != 4
            || !string.Equals(view.SelectedInstanceIdForTest, "I03", StringComparison.Ordinal)
            || !view.HasObjectHighlight
            || reviewRequests != 0)
        {
            throw new InvalidOperationException(
                "CVR-10 Instance Results did not select and highlight the first rejected stable instance without another Run.");
        }

        view.Measure(new System.Windows.Size(1400, 1150));
        view.Arrange(new System.Windows.Rect(0, 0, 1400, 1150));
        view.UpdateLayout();
        view.SelectInstanceForTest(2);
        Pump(4);
        return CaptureElement(view, outputPath, 1400, 1150);
    }

    private static CaptureResult CaptureCvr05ObjectMetricDistribution(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        using Bitmap preview = new(640, 420);
        using (Graphics graphics = Graphics.FromImage(preview))
        {
            graphics.Clear(DrawingColor.FromArgb(36, 43, 47));
            using System.Drawing.Pen acceptedPen = new(DrawingColor.MediumSeaGreen, 3f);
            using System.Drawing.Pen rejectedPen = new(DrawingColor.IndianRed, 3f);
            graphics.DrawRectangle(acceptedPen, 80, 80, 24, 28);
            graphics.DrawRectangle(rejectedPen, 150, 82, 6, 6);
            graphics.DrawRectangle(acceptedPen, 230, 78, 30, 32);
            graphics.DrawRectangle(rejectedPen, 330, 58, 52, 60);
            graphics.DrawRectangle(rejectedPen, 470, 70, 44, 55);
        }

        VisionPipelineObjectResult[] rows =
        {
            new() { Number = 1, Accepted = true, Area = 640, CenterX = 92, CenterY = 94, BoundsX = 80, BoundsY = 80, BoundsWidth = 24, BoundsHeight = 28 },
            new() { Number = 2, Accepted = false, Area = 12, CenterX = 153, CenterY = 85, BoundsX = 150, BoundsY = 82, BoundsWidth = 6, BoundsHeight = 6, RejectReason = "Area 12 < MIN_AREA 200" },
            new() { Number = 3, Accepted = true, Area = 880, CenterX = 245, CenterY = 94, BoundsX = 230, BoundsY = 78, BoundsWidth = 30, BoundsHeight = 32 },
            new() { Number = 4, Accepted = false, Area = 2400, CenterX = 356, CenterY = 88, BoundsX = 330, BoundsY = 58, BoundsWidth = 52, BoundsHeight = 60, RejectReason = "Area 2400 > MAX_AREA 2000" },
            new() { Number = 5, Accepted = false, Area = 720, CenterX = 492, CenterY = 97.5, BoundsX = 470, BoundsY = 70, BoundsWidth = 44, BoundsHeight = 55, RejectReason = "Width 44 > MAX_WIDTH 40" }
        };

        VisionPipelineStep step = new()
        {
            Name = "02 Synthetic Particle Count",
            ToolType = "Blob",
            Enabled = true,
            InputLayer = "Blob_Binary",
            OutputLayer = "Blob_Result"
        };
        AddParameters(
            step,
            ("MIN_AREA", "200"),
            ("MAX_AREA", "2000"),
            ("MIN_WIDTH", "10"),
            ("MAX_WIDTH", "40"),
            ("MIN_HEIGHT", "10"),
            ("MAX_HEIGHT", "50"));

        OpenVisionPipelineReviewView view = new();
        int reviewRequests = 0;
        view.RunReviewRequested += (_, _) => reviewRequests++;
        view.SetSelectedStep(
            "02 Synthetic Particle Count",
            "Blob",
            "OK",
            "Blob_Binary",
            preview,
            "Blob_Result",
            preview,
            "Five retained candidates / current Run",
            "MIN_AREA=200 / MAX_AREA=2000 / MIN_WIDTH=10 / MAX_WIDTH=40",
            "Explicit Run / ResultCount=2");
        view.SetObjectResults(true, step, rows, preview, preview);
        if (view.ObjectResultCount != 5
            || view.SelectedObjectResultNumber != 1
            || view.ValidationLabelTextForTest != "Pipeline 구성"
            || view.ResultLabelTextForTest != "검사 결과"
            || view.ObjectInspectorTitleForTest != "검출 후보"
            || !view.ObjectCandidateCountTextForTest.Contains("검출 후보 5", StringComparison.Ordinal)
            || !view.ObjectCandidateCountTextForTest.Contains("검사 대상 2", StringComparison.Ordinal)
            || !view.ObjectCandidateCountTextForTest.Contains("필터 제외 3", StringComparison.Ordinal)
            || !view.ObjectCandidateGuideTextForTest.Contains("실제 물체 수와 다를 수", StringComparison.Ordinal)
            || view.ObjectMetricDistributionSeriesCountForTest != 2
            || view.ObjectMetricDistributionMarkerCountForTest != 2
            || view.ObjectMetricDistributionMetricForTest != "Area"
            || !view.ObjectMetricDistributionSummaryForTest.Contains("MIN_AREA 200", StringComparison.Ordinal)
            || string.IsNullOrWhiteSpace(view.ObjectMetricDistributionEvidenceIdForTest))
        {
            throw new InvalidOperationException(
                "CVR-05 Detection candidates did not retain the expected labels, rows, Area distribution, and current range markers. "
                + $"Validation='{view.ValidationLabelTextForTest}', Result='{view.ResultLabelTextForTest}', "
                + $"Tab='{view.ObjectInspectorTitleForTest}', Count='{view.ObjectCandidateCountTextForTest}', "
                + $"Guide='{view.ObjectCandidateGuideTextForTest}', Rows={view.ObjectResultCount}, "
                + $"Selected={view.SelectedObjectResultNumber}, Series={view.ObjectMetricDistributionSeriesCountForTest}, "
                + $"Markers={view.ObjectMetricDistributionMarkerCountForTest}, Metric='{view.ObjectMetricDistributionMetricForTest}', "
                + $"Summary='{view.ObjectMetricDistributionSummaryForTest}', Evidence='{view.ObjectMetricDistributionEvidenceIdForTest}'.");
        }

        string directory = Path.GetDirectoryName(outputPath)
            ?? throw new InvalidOperationException("CVR-05 artifact directory is missing.");
        Directory.CreateDirectory(directory);
        VisionToolSignalEvidenceExporter.ExportTsv(
            view.ObjectMetricDistributionEvidenceForTest,
            Path.Combine(directory, "blob-area-distribution.tsv"));
        view.SelectObjectMetricForTest(VisionPipelineObjectMetricKind.BoundsWidth);
        if (view.ObjectMetricDistributionMetricForTest != "Bounds width"
            || view.ObjectMetricDistributionMarkerCountForTest != 2)
        {
            throw new InvalidOperationException("CVR-05 Bounds width distribution did not use MIN_WIDTH/MAX_WIDTH.");
        }

        VisionToolSignalEvidenceExporter.ExportTsv(
            view.ObjectMetricDistributionEvidenceForTest,
            Path.Combine(directory, "blob-width-distribution.tsv"));
        view.SelectObjectMetricForTest(VisionPipelineObjectMetricKind.BoundsHeight);
        if (view.ObjectMetricDistributionMetricForTest != "Bounds height"
            || view.ObjectMetricDistributionMarkerCountForTest != 2)
        {
            throw new InvalidOperationException("CVR-05 Bounds height distribution did not use MIN_HEIGHT/MAX_HEIGHT.");
        }

        VisionToolSignalEvidenceExporter.ExportTsv(
            view.ObjectMetricDistributionEvidenceForTest,
            Path.Combine(directory, "blob-height-distribution.tsv"));
        view.SelectObjectMetricForTest(VisionPipelineObjectMetricKind.Area);
        view.SelectObjectMetricFromPlotForTest(720);
        if (view.SelectedObjectResultNumber != 5
            || view.ObjectMetricDistributionSelectionForTest != 720)
        {
            throw new InvalidOperationException("CVR-05 distribution click did not select the nearest object row and drawing.");
        }

        view.SelectObjectResultForTest(3);
        if (view.SelectedObjectResultNumber != 4
            || view.ObjectMetricDistributionSelectionForTest != 2400)
        {
            throw new InvalidOperationException("CVR-05 row selection did not select the same metric value in the distribution.");
        }

        VisionPipelineStep contourStep = new()
        {
            Name = "02 Synthetic Shape Count",
            ToolType = "Contour",
            Enabled = true,
            InputLayer = "Contour_Binary",
            OutputLayer = "Contour_Result"
        };
        foreach ((string key, string value) in step.Parameters)
        {
            contourStep.Parameters[key] = value;
        }

        VisionPipelineObjectMetricDistribution contourDistribution =
            OpenVisionPipelineReviewObjectDistributionPresenter.Create(
                contourStep,
                rows,
                VisionPipelineObjectMetricKind.Area,
                preview,
                preview);
        if (contourDistribution?.Evidence?.Series.Count != 2
            || contourDistribution.Evidence.Markers.Count != 2
            || !contourDistribution.Evidence.ToolIdentity.StartsWith("Contour/", StringComparison.Ordinal)
            || contourDistribution.Evidence.EvidenceId == view.ObjectMetricDistributionEvidenceIdForTest)
        {
            throw new InvalidOperationException("CVR-05 Contour distribution did not preserve its own tool identity and Area gates.");
        }

        VisionToolSignalEvidenceExporter.ExportTsv(
            contourDistribution.Evidence,
            Path.Combine(directory, "contour-area-distribution.tsv"));
        VisionPipelineStep legacyWidthStep = new()
        {
            Name = "Legacy Width",
            ToolType = "Blob",
            Enabled = true,
            InputLayer = "Blob_Binary",
            OutputLayer = "Blob_Result"
        };
        legacyWidthStep.Parameters["MIN_WIDTH"] = "0";
        VisionPipelineObjectMetricDistribution legacyWidthDistribution =
            OpenVisionPipelineReviewObjectDistributionPresenter.Create(
                legacyWidthStep,
                rows,
                VisionPipelineObjectMetricKind.BoundsWidth,
                preview,
                preview);
        if (legacyWidthDistribution?.MaximumIsUnbounded != true
            || legacyWidthDistribution.Evidence.Markers.Count != 1
            || !legacyWidthDistribution.SummaryText.Contains("unbounded", StringComparison.OrdinalIgnoreCase))
        {
            throw new InvalidOperationException(
                "CVR-05 legacy missing MAX_WIDTH did not preserve the existing unbounded sentinel without compressing the chart.");
        }

        if (reviewRequests != 0)
        {
            throw new InvalidOperationException("CVR-05 review controls requested another Run Review.");
        }

        view.Measure(new System.Windows.Size(1180, 890));
        view.Arrange(new System.Windows.Rect(0, 0, 1180, 890));
        view.UpdateLayout();
        Pump(4);
        return CaptureElement(view, outputPath, 1180, 890);
    }

    private static CaptureResult CaptureCvr04CircleResidualReview(string outputPath)
    {
        string directory = Path.GetDirectoryName(outputPath)
            ?? throw new InvalidOperationException("CVR-04 artifact directory is missing.");
        Directory.CreateDirectory(directory);
        using CvMat goodImage = CreateCvr04CircleImage(ellipse: false);
        using CvMat badImage = CreateCvr04CircleImage(ellipse: true);
        VisionPipelineStep step = new()
        {
            Name = "CircleFeature",
            ToolType = "CircleGauge",
            Enabled = true,
            InputLayer = "Reference",
            OutputLayer = "Circle_Result"
        };
        AddParameters(
            step,
            ("USE_ROI", "true"),
            ("CvROI", "100,50,200,200"),
            ("CENTER_X", "200"),
            ("CENTER_Y", "150"),
            ("RADIUS_MIN", "50"),
            ("RADIUS_MAX", "80"),
            ("START_ANGLE_DEG", "0"),
            ("SWEEP_ANGLE_DEG", "360"),
            ("SCAN_COUNT", "180"),
            ("EDGE_POLARITY", "LightToDark"),
            ("MIN_CONTRAST", "40"),
            ("MIN_SUPPORT_RATIO", "0.8"),
            ("MAX_FIT_RESIDUAL_PX", "1"));

        VisionToolResult goodResult = VisionPipelineAppToolFactory.Create(step).Execute(goodImage);
        VisionToolResult badResult = VisionPipelineAppToolFactory.Create(step).Execute(badImage);
        try
        {
            VisionPipelineCircleEvidence goodEvidence =
                VisionPipelineCircleEvidenceStore.Get(goodResult);
            VisionPipelineCircleEvidence badEvidence =
                VisionPipelineCircleEvidenceStore.Get(badResult);
            if (goodResult?.Success != true
                || goodEvidence == null
                || goodEvidence.Samples.Count != 180
                || goodEvidence.InlierCount < 140
                || !goodEvidence.Samples.Any(item => !item.ContrastAccepted)
                || !goodEvidence.Samples.Any(item => item.ContrastAccepted && !item.FitInlier)
                || goodEvidence.FitResidualPx > goodEvidence.MaximumFitResidualPx)
            {
                throw new InvalidOperationException(
                    "CVR-04 Good circle did not retain the expected inlier, contrast-reject, fit-outlier, and residual evidence. "
                    + goodResult?.Message);
            }

            if (badResult == null
                || badResult.Success
                || badEvidence == null
                || !badEvidence.HasFit
                || badEvidence.FitResidualPx <= badEvidence.MaximumFitResidualPx
                || !badResult.Message.Contains("residual", StringComparison.OrdinalIgnoreCase))
            {
                throw new InvalidOperationException(
                    "CVR-04 ellipse did not fail the unchanged fitted-residual gate with retained evidence. "
                    + badResult?.Message);
            }

            Cv.ImWrite(Path.Combine(directory, "circle-good-source.png"), goodImage);
            Cv.ImWrite(Path.Combine(directory, "circle-good-result.png"), goodResult.ResultImage);
            Cv.ImWrite(Path.Combine(directory, "circle-bad-source.png"), badImage);
            Cv.ImWrite(Path.Combine(directory, "circle-bad-result.png"), badResult.ResultImage);
            using Bitmap goodSourceBitmap = OpenVisionLab.Common.BitmapImageConverter.ToBitmap(goodImage);
            using Bitmap goodResultBitmap = OpenVisionLab.Common.BitmapImageConverter.ToBitmap(goodResult.ResultImage);
            using Bitmap badSourceBitmap = OpenVisionLab.Common.BitmapImageConverter.ToBitmap(badImage);
            using Bitmap badResultBitmap = OpenVisionLab.Common.BitmapImageConverter.ToBitmap(badResult.ResultImage);

            VisionToolSignalEvidence residualSignal =
                OpenVisionPipelineReviewCircleEvidencePresenter.CreateResidualEvidence(
                    goodEvidence,
                    goodSourceBitmap,
                    goodResultBitmap);
            VisionPipelineCircleSampleEvidence profileSample =
                goodEvidence.Samples.First(item => item.FitInlier);
            VisionToolSignalEvidence profileSignal =
                OpenVisionPipelineReviewCircleEvidencePresenter.CreateProfileEvidence(
                    goodEvidence,
                    profileSample,
                    goodSourceBitmap,
                    goodResultBitmap);
            if (residualSignal?.Series.Count != 1
                || profileSignal?.Series.Count != 2
                || profileSignal.Markers.Count != 1
                || residualSignal.SourceSha256.Length != 64
                || residualSignal.ResultSha256.Length != 64)
            {
                throw new InvalidOperationException(
                    "CVR-04 shared signal evidence did not retain residual/profile/provenance structure.");
            }

            VisionToolSignalEvidenceExporter.ExportTsv(
                residualSignal,
                Path.Combine(directory, "circle-good-residuals.tsv"));
            VisionToolSignalEvidenceExporter.ExportTsv(
                profileSignal,
                Path.Combine(directory, "circle-good-selected-profile.tsv"));
            VisionToolSignalEvidence badResidualSignal =
                OpenVisionPipelineReviewCircleEvidencePresenter.CreateResidualEvidence(
                    badEvidence,
                    badSourceBitmap,
                    badResultBitmap);
            VisionToolSignalEvidenceExporter.ExportTsv(
                badResidualSignal,
                Path.Combine(directory, "circle-bad-residuals.tsv"));

            OpenVisionPipelineReviewView view = new();
            int implicitRunRequests = 0;
            view.RunReviewRequested += (_, _) => implicitRunRequests++;
            view.SetSelectedStep(
                "01 Circle Feature",
                "CircleGauge",
                "OK",
                "Reference",
                goodSourceBitmap,
                "Circle_Result",
                goodResultBitmap,
                "Explicit Run / retained radial evidence",
                "Same frozen CircleGauge parameters",
                goodResult.Message);
            view.SetObjectResults(false, Array.Empty<VisionPipelineObjectResult>());
            view.SetGeometryResults(
                true,
                VisionPipelineGeometryFeatureStore.Get(goodResult));
            view.SetCircleEvidence(
                true,
                goodEvidence,
                goodSourceBitmap,
                goodResultBitmap);
            if (!view.CircleEvidenceTabVisibleForTest
                || view.CircleEvidenceSampleCountForTest != 180
                || view.CircleEvidencePlotSeriesCountForTest != 1
                || view.SelectedCircleSampleNumberForTest <= 0)
            {
                throw new InvalidOperationException(
                    "CVR-04 Circle Evidence tab did not bind the current runtime evidence.");
            }

            VisionPipelineCircleSampleEvidence fitOutlier =
                goodEvidence.Samples.First(item => item.ContrastAccepted && !item.FitInlier);
            view.SelectCircleSampleFromPlotForTest(fitOutlier.Number);
            if (view.SelectedCircleSampleNumberForTest != fitOutlier.Number)
            {
                throw new InvalidOperationException(
                    "CVR-04 residual plot-to-row selection did not select the requested scan.");
            }

            VisionPipelineCircleSampleEvidence imageSample =
                goodEvidence.Samples.Last(item => item.FitInlier);
            if (!view.SelectCircleSampleAtImagePointForTest(imageSample.EdgeX, imageSample.EdgeY)
                || view.SelectedCircleSampleNumberForTest != imageSample.Number)
            {
                throw new InvalidOperationException(
                    "CVR-04 image drawing-to-row selection did not select the nearest radial sample.");
            }

            string diagnosticDirectory = Path.Combine(
                directory,
                Path.GetFileNameWithoutExtension(outputPath) + ".diagnostics");
            Directory.CreateDirectory(diagnosticDirectory);
            view.ShowCircleProfilePlotForTest();
            if (!view.CircleEvidenceShowsProfileForTest
                || view.CircleEvidencePlotSeriesCountForTest != 2)
            {
                throw new InvalidOperationException(
                    "CVR-04 selected radial profile did not expose intensity and signed response.");
            }

            view.Measure(new System.Windows.Size(1180, 890));
            view.Arrange(new System.Windows.Rect(0, 0, 1180, 890));
            view.UpdateLayout();
            Pump(4);
            CaptureElement(
                view,
                Path.Combine(diagnosticDirectory, "circle-selected-profile.png"),
                1180,
                890);
            view.ShowCircleResidualPlotForTest();
            view.SelectCircleSampleFromPlotForTest(fitOutlier.Number);
            if (implicitRunRequests != 0 || view.CircleEvidencePlotSeriesCountForTest != 1)
            {
                throw new InvalidOperationException(
                    "CVR-04 review controls ran the pipeline implicitly or failed to restore residual review.");
            }

            File.WriteAllLines(
                Path.Combine(directory, "circle-evidence-replay.txt"),
                new[]
                {
                    "Status=OK",
                    "FrozenParameters=unchanged",
                    "Good=" + goodResult.Message,
                    "GoodSamples=" + goodEvidence.Samples.Count,
                    "GoodEdgeCandidates=" + goodEvidence.EdgeCandidateCount,
                    "GoodInliers=" + goodEvidence.InlierCount,
                    "GoodContrastRejects=" + goodEvidence.Samples.Count(item => !item.ContrastAccepted),
                    "GoodFitOutliers=" + goodEvidence.Samples.Count(item => item.ContrastAccepted && !item.FitInlier),
                    "GoodResidualPx=" + goodEvidence.FitResidualPx.ToString("0.###############", CultureInfo.InvariantCulture),
                    "Bad=" + badResult.Message,
                    "BadResidualPx=" + badEvidence.FitResidualPx.ToString("0.###############", CultureInfo.InvariantCulture),
                    "ResidualGatePx=" + goodEvidence.MaximumFitResidualPx.ToString("0.###############", CultureInfo.InvariantCulture),
                    "RowPlotDrawingSelection=OK",
                    "ReviewSideEffects=zero Run Review requests"
                });

            view.Measure(new System.Windows.Size(1180, 890));
            view.Arrange(new System.Windows.Rect(0, 0, 1180, 890));
            view.UpdateLayout();
            Pump(4);
            return CaptureElement(view, outputPath, 1180, 890);
        }
        finally
        {
            goodResult?.ResultImage?.Dispose();
            badResult?.ResultImage?.Dispose();
        }
    }

    private static CvMat CreateCvr04CircleImage(bool ellipse)
    {
        CvMat image = new(300, 400, OpenCvSharp.MatType.CV_8UC1, new OpenCvSharp.Scalar(240));
        for (int y = 0; y < image.Height; y++)
        {
            for (int x = 0; x < image.Width; x++)
            {
                double dx = x - 200D;
                double dy = y - 150D;
                double angle = Math.Atan2(dy, dx) * 180D / Math.PI;
                if (angle < 0D)
                {
                    angle += 360D;
                }

                bool dark;
                if (ellipse)
                {
                    double normalized = Math.Sqrt(
                        (dx * dx) / (70D * 70D)
                        + (dy * dy) / (60D * 60D));
                    dark = Math.Abs(normalized - 1D) <= 0.028D;
                }
                else
                {
                    double radius = Math.Sqrt(dx * dx + dy * dy);
                    bool occluded = angle >= 100D && angle < 120D;
                    bool trueRing = !occluded && Math.Abs(radius - 70D) <= 2D;
                    bool falseInnerRing = angle >= 8D
                        && angle < 18D
                        && Math.Abs(radius - 55D) <= 2D;
                    dark = trueRing || falseInnerRing;
                }

                if (dark)
                {
                    image.Set(y, x, (byte)20);
                }
            }
        }

        return image;
    }

    private static CaptureResult CaptureP214TwoPointScale(string outputPath)
    {
        string artifactDirectory = Path.GetDirectoryName(outputPath)
            ?? throw new InvalidOperationException("P214 artifact directory is missing.");
        Directory.CreateDirectory(artifactDirectory);

        using Bitmap contractImage = new(100, 100);
        using (Graphics graphics = Graphics.FromImage(contractImage))
        {
            graphics.Clear(DrawingColor.FromArgb(42, 48, 52));
            graphics.FillEllipse(System.Drawing.Brushes.Gold, 8, 8, 5, 5);
            graphics.FillEllipse(System.Drawing.Brushes.DeepSkyBlue, 11, 12, 5, 5);
        }

        VisionPipelineGeometryFeatureResult contractA = PointFeature("ScaleA", 10, 10);
        VisionPipelineGeometryFeatureResult contractB = PointFeature("ScaleB", 13, 14);
        contractA.CoordinateLayer = contractB.CoordinateLayer = "Reference";
        contractA.ImageWidth = contractB.ImageWidth = 100;
        contractA.ImageHeight = contractB.ImageHeight = 100;

        VisionPipelineScaleCalibrationRecord millimeterRecord = CalculateScale(
            contractA, contractB, 10D, VisionScaleCalibrationUnit.Millimeter, contractImage);
        VisionPipelineScaleCalibrationRecord micrometerRecord = CalculateScale(
            contractA, contractB, 10000D, VisionScaleCalibrationUnit.Micrometer, contractImage);
        VisionPipelineScaleCalibrationRecord inchRecord = CalculateScale(
            contractA, contractB, 10D / 25.4D, VisionScaleCalibrationUnit.Inch, contractImage);
        if (Math.Abs(millimeterRecord.PixelDistance - 5D) > 0.000000001D
            || Math.Abs(millimeterRecord.MillimetersPerPixel - 2D) > 0.000000001D
            || Math.Abs(micrometerRecord.MillimetersPerPixel - 2D) > 0.000000001D
            || Math.Abs(inchRecord.MillimetersPerPixel - 2D) > 0.000000001D)
        {
            throw new InvalidOperationException("P214 unit conversion or 3-4-5 scale calculation failed.");
        }

        string recipeName = "Smoke_P214Scale_" + Guid.NewGuid().ToString("N").Substring(0, 10);
        try
        {
            string saveError = string.Empty;
            string loadError = string.Empty;
            if (!VisionPipelineScaleCalibrationStorage.TrySave(
                    recipeName,
                    millimeterRecord,
                    out string evidencePath,
                    out saveError)
                || !VisionPipelineScaleCalibrationStorage.TryLoad(
                    recipeName,
                    millimeterRecord.PipelineName,
                    out VisionPipelineScaleCalibrationRecord loaded,
                    out loadError)
                || loaded.SourceImageSha256 != millimeterRecord.SourceImageSha256
                || Math.Abs(loaded.MillimetersPerPixel - 2D) > 0.000000001D)
            {
                throw new InvalidOperationException("P214 calibration evidence round trip failed. " + saveError + " " + loadError);
            }

            VisionPipelineStep target = new()
            {
                Name = "GapCaliper",
                ToolType = "LineDistance",
                Enabled = true,
                InputLayer = "Reference",
                OutputLayer = "Gap_Result"
            };
            VisionPipelineStep untouched = new()
            {
                Name = "OtherCircle",
                ToolType = "CircleGauge",
                Enabled = true,
                InputLayer = "Reference",
                OutputLayer = "Circle_Result"
            };
            if (!VisionPipelineScaleCalibrationStorage.TryApply(loaded, contractImage, target, out string applyError)
                || target.Parameters.GetValueOrDefault("PIXELPERMM") != "2"
                || target.Parameters.GetValueOrDefault("LeftPIXELPERMM") != "2"
                || target.Parameters.GetValueOrDefault("RightPIXELPERMM") != "2"
                || untouched.Parameters.ContainsKey("PIXELPERMM"))
            {
                throw new InvalidOperationException("P214 explicit single-target apply failed. " + applyError);
            }

            if (!VisionPipelineScaleCalibrationStorage.TrySave(
                    recipeName,
                    loaded,
                    out evidencePath,
                    out string appliedAuditError))
            {
                throw new InvalidOperationException("P214 applied-Step evidence did not round-trip. " + appliedAuditError);
            }

            VisionPipeline pipeline = new() { Name = loaded.PipelineName };
            pipeline.Steps.Add(target);
            pipeline.Steps.Add(untouched);
            VisionPipelineStorage.Save(recipeName, pipeline);
            if (!VisionPipelineStorage.TryValidateRoundTrip(recipeName, pipeline, out string roundTripMessage))
            {
                throw new InvalidOperationException("P214 pipeline round trip failed. " + roundTripMessage);
            }

            using Bitmap changedImage = new(contractImage);
            changedImage.SetPixel(50, 50, DrawingColor.Red);
            VisionPipelineStep changedTarget = new()
            {
                Name = "ChangedImageTarget", ToolType = "Line", Enabled = true,
                InputLayer = "Reference", OutputLayer = "Changed_Result"
            };
            if (VisionPipelineScaleCalibrationStorage.TryApply(loaded, changedImage, changedTarget, out string changedError)
                || !changedError.Contains("content changed", StringComparison.OrdinalIgnoreCase)
                || changedTarget.Parameters.ContainsKey("PIXELPERMM"))
            {
                throw new InvalidOperationException("P214 changed-image evidence did not fail closed.");
            }

            VisionPipelineGeometryFeatureResult sameIdentityB = contractB.Clone();
            sameIdentityB.SourceStep = contractA.SourceStep;
            sameIdentityB.FeatureName = contractA.FeatureName;
            if (VisionPipelineScaleCalibrationStorage.TryCalculate(
                    "P214_Scale", contractA, sameIdentityB, 10D, VisionScaleCalibrationUnit.Millimeter,
                    contractImage, out _, out string sameError)
                || !sameError.Contains("different", StringComparison.OrdinalIgnoreCase))
            {
                throw new InvalidOperationException("P214 same-point selection did not fail closed.");
            }

            VisionPipelineGeometryFeatureResult crossLayerB = contractB.Clone();
            crossLayerB.CoordinateLayer = "Other";
            if (VisionPipelineScaleCalibrationStorage.TryCalculate(
                    "P214_Scale", contractA, crossLayerB, 10D, VisionScaleCalibrationUnit.Millimeter,
                    contractImage, out _, out string layerError)
                || !layerError.Contains("same coordinate layer", StringComparison.OrdinalIgnoreCase))
            {
                throw new InvalidOperationException("P214 cross-layer point selection did not fail closed.");
            }

            VisionPipelineStep incompatible = new()
            {
                Name = "Threshold", ToolType = "Threshold", Enabled = true,
                InputLayer = "Reference", OutputLayer = "Threshold_Result"
            };
            if (VisionPipelineScaleCalibrationStorage.TryApply(loaded, contractImage, incompatible, out string incompatibleError)
                || !incompatibleError.Contains("compatible", StringComparison.OrdinalIgnoreCase))
            {
                throw new InvalidOperationException("P214 incompatible target did not fail closed.");
            }

            VisionToolResult metricResult = VisionToolResult.Passed(null, TimeSpan.Zero);
            metricResult.Metrics[VisionPipelineKnownMetrics.GeometryDistancePx] = 25D;
            metricResult.Metrics[VisionPipelineKnownMetrics.GeometrySignedClearancePx] = -2D;
            metricResult.Metrics[VisionPipelineKnownMetrics.CircleRadiusPx] = 5D;
            metricResult.Metrics[VisionPipelineKnownMetrics.CircleDiameterPx] = 10D;
            VisionPipelineStep metricStep = new() { ToolType = "GeometryMeasure" };
            metricStep.Parameters["PIXELPERMM"] = "0.04";
            VisionPipelineMetricEnrichmentService.Enrich(metricResult, metricStep);
            if (Math.Abs(metricResult.Metrics.GetValueOrDefault(VisionPipelineKnownMetrics.GeometryDistanceMm) - 1D) > 0.000000001D
                || Math.Abs(metricResult.Metrics.GetValueOrDefault(VisionPipelineKnownMetrics.GeometrySignedClearanceMm) + 0.08D) > 0.000000001D
                || Math.Abs(metricResult.Metrics.GetValueOrDefault(VisionPipelineKnownMetrics.CircleRadiusMm) - 0.2D) > 0.000000001D
                || Math.Abs(metricResult.Metrics.GetValueOrDefault(VisionPipelineKnownMetrics.CircleDiameterMm) - 0.4D) > 0.000000001D)
            {
                throw new InvalidOperationException("P214 calibrated P213 mm metric enrichment failed.");
            }

            File.Copy(evidencePath, Path.Combine(artifactDirectory, "two_point_scale_record.xml"), true);
            File.WriteAllText(
                Path.Combine(artifactDirectory, "verification.txt"),
                "P214 two-point scale contract passed.\n"
                + "3-4-5 pixel distance: 5 px\n"
                + "Known distance: 10 mm / 10000 um / 0.3937007874 inch\n"
                + "Derived scale: 2 mm/px\n"
                + "Changed image, same identity, cross layer, and incompatible target: fail closed\n"
                + "Explicit target: GapCaliper only; legacy PIXELPERMM + Left/Right values persisted\n"
                + "GeometryDistanceMm and CircleRadiusMm enrichment passed\n");
        }
        finally
        {
            RecipeWorkspaceService.DeleteVisionWorkspace(recipeName);
        }

        AssertP214DocumentIntegration(artifactDirectory);

        using Bitmap preview = new(640, 420);
        using (Graphics graphics = Graphics.FromImage(preview))
        {
            graphics.Clear(DrawingColor.FromArgb(34, 41, 45));
            using System.Drawing.Pen railPen = new(DrawingColor.FromArgb(115, 132, 138), 2F);
            using System.Drawing.Pen objectPen = new(DrawingColor.FromArgb(190, 205, 210), 5F);
            for (int x = 60; x <= 580; x += 40)
            {
                graphics.DrawLine(railPen, x, 70, x, 350);
            }
            graphics.DrawRectangle(objectPen, 95, 95, 450, 230);
            graphics.DrawEllipse(System.Drawing.Pens.Gold, 155, 295, 10, 10);
            graphics.DrawEllipse(System.Drawing.Pens.DeepSkyBlue, 495, 135, 10, 10);
        }

        VisionPipelineGeometryFeatureResult uiA = PointFeature("DatumA", 160, 300);
        VisionPipelineGeometryFeatureResult uiB = PointFeature("DatumB", 500, 140);
        uiA.CoordinateLayer = uiB.CoordinateLayer = "Reference";
        uiA.ImageWidth = uiB.ImageWidth = 640;
        uiA.ImageHeight = uiB.ImageHeight = 420;
        VisionPipelineScaleCalibrationRecord uiRecord = CalculateScale(
            uiA, uiB, 12.5D, VisionScaleCalibrationUnit.Millimeter, preview);
        VisionPipeline uiPipeline = new() { Name = "P214_Two_Point_Scale" };
        uiPipeline.Steps.Add(new VisionPipelineStep
        {
            Name = "PinPitch", ToolType = "LineDistance", Enabled = true,
            InputLayer = "Reference", OutputLayer = "Pitch_Result"
        });

        OpenVisionPipelineReviewView view = new();
        view.SetPipelineHeader(uiPipeline.Name, uiPipeline.Steps.Count);
        view.SetRecipeContext("P214_Scale_Demo");
        view.SetSelectedStep(
            "01 PinPitch",
            "LineDistance",
            "WAIT / apply scale",
            "Reference",
            preview,
            "Pitch_Result",
            preview,
            "Reference -> PinPitch -> Pitch_Result",
            "PIXELPERMM=0 (legacy key; runtime meaning mm/px)",
            "Explicit Run remains required after Apply");
        view.SetObjectResults(false, Array.Empty<VisionPipelineObjectResult>());
        view.SetGeometryResults(false, Array.Empty<VisionPipelineGeometryFeatureResult>());
        view.SetScaleCalibrationState(
            new[] { uiA, uiB },
            VisionPipelineScaleCalibrationStorage.GetCompatibleTargets(uiPipeline),
            uiRecord,
            preview,
            "Evidence hash matches. Apply to the selected Step only; no Preview/Run occurs.");
        view.SelectScaleCalibrationTabForTest();
        view.Measure(new System.Windows.Size(1180, 890));
        view.Arrange(new System.Windows.Rect(0, 0, 1180, 890));
        view.UpdateLayout();
        Pump(4);
        return CaptureElement(view, outputPath, 1180, 890);
    }

    private static void AssertP214DocumentIntegration(string artifactDirectory)
    {
        string recipeName = "Smoke_P214Document_" + Guid.NewGuid().ToString("N").Substring(0, 10);
        DisplayManagerService displayManager = new();
        using Bitmap source = new(240, 180);
        using (Graphics graphics = Graphics.FromImage(source))
        {
            graphics.Clear(DrawingColor.White);
            using System.Drawing.Pen pen = new(DrawingColor.Black, 5F);
            graphics.DrawLine(pen, 100, 20, 100, 160);
        }
        displayManager.CreateLayerDisplay(source, "Reference", false);
        displayManager.SelectedItem = "Reference";

        VisionPipeline pipeline = new() { Name = "P214_Document_Integration" };
        VisionPipelineStep line = new()
        {
            Name = "ScaleLine",
            ToolType = "Line",
            Enabled = true,
            InputLayer = "Reference",
            OutputLayer = "ScaleLine_Result"
        };
        AddParameters(line,
            ("USE_ROI", "true"), ("CvROI", "70,10,60,160"),
            ("PRJ_DIR", "X_LTOR"), ("PRJ_PORALITY", "WTOB"),
            ("CONTRAST", "20"), ("THICKNESS", "3"), ("SAMPLING_STEP", "8"),
            ("SHOW_EDGE", "true"), ("SHOW_FITLINE", "true"));
        pipeline.Steps.Add(line);
        VisionPipelineStorage.Save(recipeName, pipeline);
        VisionPipelineStorage.SaveActivePipelineName(recipeName, pipeline.Name);

        try
        {
            using OpenVisionPipelineReviewDocument document = new(displayManager, recipeName);
            Task run = document.RunReviewForTestAsync();
            WaitForTaskWithPump(run, 30000, "P214 explicit Pipeline Review Run");
            string executionState = document.ReviewExecutionState;
            string sourceHashBefore = VisionPipelineScaleCalibrationStorage.ComputeBitmapSha256(displayManager.GetLayerImage("Reference"));
            int layerCountBefore = displayManager.LayerCount;

            if (!document.TeachScaleForTest(
                    "ScaleLine/Start",
                    "ScaleLine/End",
                    14D,
                    VisionScaleCalibrationUnit.Millimeter)
                || !document.ScaleCalibrationStatusText.Contains("Saved exact two-point evidence", StringComparison.OrdinalIgnoreCase))
            {
                throw new InvalidOperationException(
                    "P214 Pipeline Review did not calculate and save same-run point evidence. "
                    + document.ScaleCalibrationStatusText);
            }

            if (!document.ApplyScaleForTest(0)
                || !document.ScaleCalibrationStatusText.Contains("no Preview/Run occurred", StringComparison.OrdinalIgnoreCase))
            {
                throw new InvalidOperationException(
                    "P214 Pipeline Review did not apply the saved scale explicitly. "
                    + document.ScaleCalibrationStatusText);
            }

            VisionPipeline saved = VisionPipelineStorage.Load(recipeName, pipeline.Name);
            string? scaleText = saved.Steps.Single().Parameters.GetValueOrDefault("PIXELPERMM");
            string sourceHashAfter = VisionPipelineScaleCalibrationStorage.ComputeBitmapSha256(displayManager.GetLayerImage("Reference"));
            if (!double.TryParse(scaleText, NumberStyles.Float, CultureInfo.InvariantCulture, out double scale)
                || scale <= 0D
                || document.ReviewExecutionState != executionState
                || displayManager.LayerCount != layerCountBefore
                || sourceHashAfter != sourceHashBefore)
            {
                throw new InvalidOperationException(
                    "P214 Apply changed execution/layers/source or failed pipeline persistence. "
                    + $"Scale={scaleText}, StateBefore={executionState}, StateAfter={document.ReviewExecutionState}, "
                    + $"LayersBefore={layerCountBefore}, LayersAfter={displayManager.LayerCount}");
            }

            if (!VisionPipelineScaleCalibrationStorage.TryLoad(
                    recipeName,
                    pipeline.Name,
                    out VisionPipelineScaleCalibrationRecord record,
                    out string loadError)
                || !record.AppliedStepNames.Contains("ScaleLine", StringComparer.OrdinalIgnoreCase))
            {
                throw new InvalidOperationException("P214 applied-Step audit did not persist. " + loadError);
            }

            File.AppendAllText(
                Path.Combine(artifactDirectory, "verification.txt"),
                "Pipeline Review integration: explicit Run supplied points; calculate/apply preserved execution state, layer count, routing image hash, and applied exactly one Step.\n");
        }
        finally
        {
            RecipeWorkspaceService.DeleteVisionWorkspace(recipeName);
        }
    }

    private static VisionPipelineScaleCalibrationRecord CalculateScale(
        VisionPipelineGeometryFeatureResult pointA,
        VisionPipelineGeometryFeatureResult pointB,
        double knownDistance,
        VisionScaleCalibrationUnit unit,
        Bitmap image)
    {
        if (!VisionPipelineScaleCalibrationStorage.TryCalculate(
                "P214_Scale",
                pointA,
                pointB,
                knownDistance,
                unit,
                image,
                out VisionPipelineScaleCalibrationRecord record,
                out string error))
        {
            throw new InvalidOperationException("P214 scale calculation failed: " + error);
        }

        return record;
    }

    private static CaptureResult CaptureP213GeometryPropertyGrid(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.English, false);
        CleanupTransientRecipeWorkspaces();

        string recipeName = "Smoke_P213GeometryProperty_" + Guid.NewGuid().ToString("N").Substring(0, 10);
        VisionPipeline pipeline = new() { Name = "P213_Geometry_PropertyGrid" };
        pipeline.Steps.Add(new VisionPipelineStep
        {
            Name = "DatumHorizontal", ToolType = "Line", Enabled = true,
            InputLayer = "Main", OutputLayer = "DatumHorizontal_Result"
        });
        pipeline.Steps.Add(new VisionPipelineStep
        {
            Name = "DatumVertical", ToolType = "Line", Enabled = true,
            InputLayer = "Main", OutputLayer = "DatumVertical_Result"
        });
        VisionPipelineStep geometry = CreateGeometryMeasureStep(
            GeometryMeasurementMode.LineLineIntersection,
            Segment("DatumHorizontal", 40, 160, 400, 160),
            Segment("DatumVertical", 320, 40, 320, 300));
        geometry.Name = "CardCorner";
        geometry.InputLayer = "Main";
        geometry.OutputLayer = "CardCorner_Result";
        geometry.Parameters[VisionPipelineGeometryMeasureService.MaximumExtensionAParameter] = "12";
        geometry.Parameters[VisionPipelineGeometryMeasureService.MaximumExtensionBParameter] = "12";
        pipeline.Steps.Add(geometry);

        VisionPipelineStorage.Save(recipeName, pipeline);
        VisionPipelineStorage.SaveActivePipelineName(recipeName, pipeline.Name);
        OpenVisionShellHostView shellHost = CreateShellHost(recipeName, seedMainLayer: false);
        try
        {
            return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
            {
                ToggleButton recipeManagerButton = FindNamedVisualChild<ToggleButton>(shellHost, "btnHostRecipeManager")
                    ?? throw new InvalidOperationException("P213 PropertyGrid smoke could not find Recipe Manager.");
                recipeManagerButton.IsChecked = true;
                Pump(100);
                FindNamedVisualChild<ToggleButton>(shellHost, "recipeAdvancedReviewToggle")!.IsChecked = true;
                Pump(60);
                FindNamedVisualChild<TabItem>(shellHost, "tabRecipePipeline")!.IsSelected = true;
                Pump(40);
                FindNamedVisualChild<TabItem>(shellHost, "tabRecipePipelineXmlSteps")!.IsSelected = true;
                Pump(40);

                shellHost.RecipeCommands.SelectedPipelinePreviewStep =
                    shellHost.RecipeCommands.SelectedRecipeSummary.PipelinePreviewSteps.Single(item => item.Name == "CardCorner");
                shellHost.RecipeCommands.LoadSelectedStepParametersCommand.Execute(null);
                Pump(180);

                FrameworkElement propertyGridHost = FindVisualChildren<FrameworkElement>(shellHost)
                    .FirstOrDefault(item => item.IsVisible && string.Equals(
                        AutomationProperties.GetAutomationId(item),
                        "HostRecipeSelectedStepPropertyGridHost",
                        StringComparison.Ordinal))
                    ?? throw new InvalidOperationException("P213 GeometryMeasure PropertyGrid host was not visible.");
                System.Windows.Controls.WpfPropertyGrid.PropertyGrid grid =
                    FindVisualChildren<System.Windows.Controls.WpfPropertyGrid.PropertyGrid>(propertyGridHost)
                        .FirstOrDefault(item => item.IsVisible && item.SelectedObject != null)
                    ?? throw new InvalidOperationException("P213 GeometryMeasure PropertyGrid did not load.");
                PropertyDescriptorCollection descriptors = TypeDescriptor.GetProperties(grid.SelectedObject);
                foreach (string required in new[] { "MeasurementMode", "SourceA", "SourceB", "MaximumExtensionAPx", "MaximumExtensionBPx" })
                {
                    if (descriptors.Find(required, true) == null)
                    {
                        throw new InvalidOperationException("P213 GeometryMeasure PropertyGrid missed " + required + ".");
                    }
                }

                PropertyDescriptor sourceA = descriptors.Find("SourceA", true)!;
                TypeConverter.StandardValuesCollection? choices = sourceA.Converter.GetStandardValues(new PropertyContext(grid.SelectedObject, sourceA));
                string[] references = choices?.Cast<object>().Select(item => Convert.ToString(item) ?? string.Empty).Where(value => !string.IsNullOrWhiteSpace(value)).ToArray()
                    ?? Array.Empty<string>();
                if (!references.Contains("DatumHorizontal/Segment", StringComparer.OrdinalIgnoreCase)
                    || !references.Contains("DatumVertical/Segment", StringComparer.OrdinalIgnoreCase))
                {
                    throw new InvalidOperationException("P213 compatible earlier-feature picker did not expose both Line segments.");
                }

                int runsBefore = shellHost.NativePreviewRunCount;
                shellHost.RecipeCommands.ApplySelectedStepParametersCommand.Execute(null);
                Pump(180);
                VisionPipeline saved = VisionPipelineStorage.Load(recipeName, pipeline.Name);
                VisionPipelineStep savedGeometry = saved.Steps.Single(item => item.Name == "CardCorner");
                if (savedGeometry.Parameters.GetValueOrDefault(VisionPipelineGeometryMeasureService.SourceStepAParameter) != "DatumHorizontal"
                    || savedGeometry.Parameters.GetValueOrDefault(VisionPipelineGeometryMeasureService.SourceFeatureAParameter) != "Segment"
                    || savedGeometry.Parameters.GetValueOrDefault(VisionPipelineGeometryMeasureService.SourceStepBParameter) != "DatumVertical"
                    || savedGeometry.Parameters.GetValueOrDefault(VisionPipelineGeometryMeasureService.SourceFeatureBParameter) != "Segment"
                    || shellHost.NativePreviewRunCount != runsBefore)
                {
                    throw new InvalidOperationException("P213 GeometryMeasure apply/save/reload lost source identity or triggered Preview/Run.");
                }

                TextBox search = GetActivePropertyGridSearchTextBox(grid, "P213 GeometryMeasure recipe step");
                search.Text = "Source";
                search.GetBindingExpression(TextBox.TextProperty)?.UpdateSource();
                grid.UpdateLayout();
                Pump(60);
                ScrollViewer pipelineScroll = FindNamedVisualChild<ScrollViewer>(shellHost, "recipePipelineTabScrollViewer")
                    ?? throw new InvalidOperationException("P213 Pipeline scroll viewer was not found.");
                pipelineScroll.ScrollToBottom();
                pipelineScroll.UpdateLayout();
                Pump(80);
                BringPropertyGridPropertyIntoView(grid, "SourceA", "P213 GeometryMeasure recipe step", 0D);
                if (grid.IsSearchEmptyMessageVisibleForTest || shellHost.NativePreviewRunCount != 0)
                {
                    throw new InvalidOperationException("P213 source-picker search failed or changed Preview/Run state.");
                }
            }, captureFloatingToolWindow: false, captureScreen: true);
        }
        finally
        {
            RecipeWorkspaceService.DeleteVisionWorkspace(recipeName);
        }
    }

