                ToggleButton recipeManagerButton = FindNamedVisualChild<ToggleButton>(shellHost, "btnHostRecipeManager")
                    ?? throw new InvalidOperationException("CVR-09 PropertyGrid smoke could not find Recipe Manager.");
                recipeManagerButton.IsChecked = true;
                Pump(100);
                FindNamedVisualChild<ToggleButton>(shellHost, "recipeAdvancedReviewToggle")!.IsChecked = true;
                Pump(60);
                FindNamedVisualChild<TabItem>(shellHost, "tabRecipePipeline")!.IsSelected = true;
                Pump(40);
                FindNamedVisualChild<TabItem>(shellHost, "tabRecipePipelineXmlSteps")!.IsSelected = true;
                Pump(40);

                shellHost.RecipeCommands.SelectedPipelinePreviewStep =
                    shellHost.RecipeCommands.SelectedRecipeSummary.PipelinePreviewSteps.Single(
                        item => item.Name == "03 Publish Dual-Edge Fixture");
                shellHost.RecipeCommands.LoadSelectedStepParametersCommand.Execute(null);
                Pump(180);

                FrameworkElement propertyGridHost = FindVisualChildren<FrameworkElement>(shellHost)
                    .FirstOrDefault(item => item.IsVisible && string.Equals(
                        AutomationProperties.GetAutomationId(item),
                        "HostRecipeSelectedStepPropertyGridHost",
                        StringComparison.Ordinal))
                    ?? throw new InvalidOperationException("CVR-09 LineFixture PropertyGrid host was not visible.");
                System.Windows.Controls.WpfPropertyGrid.PropertyGrid grid =
                    FindVisualChildren<System.Windows.Controls.WpfPropertyGrid.PropertyGrid>(propertyGridHost)
                        .FirstOrDefault(item => item.IsVisible && item.SelectedObject != null)
                    ?? throw new InvalidOperationException("CVR-09 LineFixture PropertyGrid did not load.");
                PropertyDescriptorCollection descriptors = TypeDescriptor.GetProperties(grid.SelectedObject);
                foreach (string required in new[]
                {
                    "SourceA",
                    "SourceB",
                    "FrameName",
                    "ReferenceX",
                    "ReferenceY",
                    "ReferenceAngleDeg",
                    "MinimumSupportA",
                    "MinimumSupportB",
                    "MaximumFitResidualAPx",
                    "MaximumFitResidualBPx",
                    "MinimumIncludedAngleDeg",
                    "MaximumIncludedAngleDeg",
                    "MaximumExtensionAPx",
                    "MaximumExtensionBPx"
                })
                {
                    if (descriptors.Find(required, true) == null)
                    {
                        throw new InvalidOperationException("CVR-09 LineFixture PropertyGrid missed " + required + ".");
                    }
                }

                PropertyDescriptor sourceA = descriptors.Find("SourceA", true)!;
                TypeConverter.StandardValuesCollection? choices =
                    sourceA.Converter.GetStandardValues(new PropertyContext(grid.SelectedObject, sourceA));
                string[] references = choices?.Cast<object>()
                    .Select(item => Convert.ToString(item) ?? string.Empty)
                    .Where(value => !string.IsNullOrWhiteSpace(value))
                    .ToArray()
                    ?? Array.Empty<string>();
                if (!references.Contains("01 Top Datum/Segment", StringComparer.OrdinalIgnoreCase)
                    || !references.Contains("02 Left Datum/Segment", StringComparer.OrdinalIgnoreCase))
                {
                    throw new InvalidOperationException(
                        "CVR-09 typed Segment pickers did not expose both earlier Line results.");
                }

                int runsBefore = shellHost.NativePreviewRunCount;
                shellHost.RecipeCommands.ApplySelectedStepParametersCommand.Execute(null);
                Pump(180);
                VisionPipeline saved = VisionPipelineStorage.Load(recipeName, pipeline.Name);
                VisionPipelineStep savedFixture = saved.Steps.Single(
                    item => item.Name == "03 Publish Dual-Edge Fixture");
                if (savedFixture.Parameters.GetValueOrDefault("SourceStepA") != "01 Top Datum"
                    || savedFixture.Parameters.GetValueOrDefault("SourceFeatureA") != "Segment"
                    || savedFixture.Parameters.GetValueOrDefault("SourceStepB") != "02 Left Datum"
                    || savedFixture.Parameters.GetValueOrDefault("SourceFeatureB") != "Segment"
                    || savedFixture.Parameters.GetValueOrDefault("FIXTURE_FRAME_NAME") != "OuterDatumFrame"
                    || shellHost.NativePreviewRunCount != runsBefore)
                {
                    throw new InvalidOperationException(
                        "CVR-09 LineFixture apply/save/reload lost its contract or triggered Preview/Run.");
                }

                TextBox search = GetActivePropertyGridSearchTextBox(grid, "CVR-09 LineFixture recipe step");
                search.Text = "Datum";
                search.GetBindingExpression(TextBox.TextProperty)?.UpdateSource();
                grid.UpdateLayout();
                Pump(60);
                ScrollViewer pipelineScroll = FindNamedVisualChild<ScrollViewer>(
                    shellHost,
                    "recipePipelineTabScrollViewer")
                    ?? throw new InvalidOperationException("CVR-09 Pipeline scroll viewer was not found.");
                pipelineScroll.ScrollToBottom();
                pipelineScroll.UpdateLayout();
                Pump(80);
                BringPropertyGridPropertyIntoView(
                    grid,
                    "SourceA",
                    "CVR-09 LineFixture recipe step",
                    0D);
                if (grid.IsSearchEmptyMessageVisibleForTest
                    || shellHost.NativePreviewRunCount != runsBefore)
                {
                    throw new InvalidOperationException(
                        "CVR-09 LineFixture PropertyGrid search failed or changed Preview/Run state.");
                }
            }, captureFloatingToolWindow: false, captureScreen: true);
        }
        finally
        {
            RecipeWorkspaceService.DeleteVisionWorkspace(recipeName);
        }
    }

    private static CaptureResult CaptureP219AffinePointBindingPropertyGrid(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.English, false);
        CleanupTransientRecipeWorkspaces();

        string recipeName = "Smoke_P219AffinePointBinding_" + Guid.NewGuid().ToString("N").Substring(0, 10);
        VisionPipeline pipeline = new() { Name = "P219_Affine_Point_Binding" };
        foreach (string name in new[] { "LocateTopLeft", "LocateTopRight", "LocateBottomLeft" })
        {
            pipeline.Steps.Add(new VisionPipelineStep
            {
                Name = name,
                ToolType = "Matching",
                Enabled = true,
                InputLayer = "Main",
                OutputLayer = name + "_Result"
            });
        }

        AffineTransformToolProperty property = new AffineTransformToolProperty
        {
            SourcePoint1X = 100,
            SourcePoint1Y = 100,
            SourcePoint2X = 500,
            SourcePoint2Y = 100,
            SourcePoint3X = 100,
            SourcePoint3Y = 350,
            DestinationPoint1X = 80,
            DestinationPoint1Y = 80,
            DestinationPoint2X = 480,
            DestinationPoint2Y = 80,
            DestinationPoint3X = 80,
            DestinationPoint3Y = 330,
            OutputWidth = 640,
            OutputHeight = 480
        };
        VisionPipelineStep affine = VisionPipelineStepBuilder.FromAffineTransformProperty(
            property,
            "NormalizeFromThreePoints",
            "Main",
            "Reference");
        affine.Parameters[VisionPipelineAffinePointBindingService.UseDetectedSourcePointsParameter] = "true";
        affine.Parameters[VisionPipelineAffinePointBindingService.SourcePoint1FeatureParameter] = "LocateTopLeft/Center";
        affine.Parameters[VisionPipelineAffinePointBindingService.SourcePoint2FeatureParameter] = "LocateTopRight/Center";
        affine.Parameters[VisionPipelineAffinePointBindingService.SourcePoint3FeatureParameter] = "LocateBottomLeft/Center";
        pipeline.Steps.Add(affine);

        VisionPipelineStorage.Save(recipeName, pipeline);
        VisionPipelineStorage.SaveActivePipelineName(recipeName, pipeline.Name);
        OpenVisionShellHostView shellHost = CreateShellHost(recipeName, seedMainLayer: false);
        try
        {
            return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
            {
                ToggleButton recipeManagerButton = FindNamedVisualChild<ToggleButton>(shellHost, "btnHostRecipeManager")
                    ?? throw new InvalidOperationException("P219 PropertyGrid smoke could not find Recipe Manager.");
                recipeManagerButton.IsChecked = true;
                Pump(100);
                FindNamedVisualChild<ToggleButton>(shellHost, "recipeAdvancedReviewToggle")!.IsChecked = true;
                Pump(60);
                FindNamedVisualChild<TabItem>(shellHost, "tabRecipePipeline")!.IsSelected = true;
                Pump(40);
                FindNamedVisualChild<TabItem>(shellHost, "tabRecipePipelineXmlSteps")!.IsSelected = true;
                Pump(40);

                shellHost.RecipeCommands.SelectedPipelinePreviewStep =
                    shellHost.RecipeCommands.SelectedRecipeSummary.PipelinePreviewSteps.Single(item => item.Name == "NormalizeFromThreePoints");
                shellHost.RecipeCommands.LoadSelectedStepParametersCommand.Execute(null);
                Pump(180);

                FrameworkElement propertyGridHost = FindVisualChildren<FrameworkElement>(shellHost)
                    .FirstOrDefault(item => item.IsVisible && string.Equals(
                        AutomationProperties.GetAutomationId(item),
                        "HostRecipeSelectedStepPropertyGridHost",
                        StringComparison.Ordinal))
                    ?? throw new InvalidOperationException("P219 AffineTransform PropertyGrid host was not visible.");
                System.Windows.Controls.WpfPropertyGrid.PropertyGrid grid =
                    FindVisualChildren<System.Windows.Controls.WpfPropertyGrid.PropertyGrid>(propertyGridHost)
                        .FirstOrDefault(item => item.IsVisible && item.SelectedObject != null)
                    ?? throw new InvalidOperationException("P219 AffineTransform PropertyGrid did not load.");
                PropertyDescriptorCollection descriptors = TypeDescriptor.GetProperties(grid.SelectedObject);
                foreach (string required in new[]
                {
                    "UseDetectedSourcePoints",
                    "SourcePoint1Feature",
                    "SourcePoint2Feature",
                    "SourcePoint3Feature",
                    "SourcePoint1X",
                    "SourcePoint1Y",
                    "SourcePoint2X",
                    "SourcePoint2Y",
                    "SourcePoint3X",
                    "SourcePoint3Y"
                })
                {
                    if (descriptors.Find(required, true) == null)
                    {
                        throw new InvalidOperationException("P219 AffineTransform PropertyGrid missed " + required + ".");
                    }
                }

                PropertyDescriptor sourcePoint1Feature = descriptors.Find("SourcePoint1Feature", true)!;
                TypeConverter.StandardValuesCollection? choices =
                    sourcePoint1Feature.Converter.GetStandardValues(new PropertyContext(grid.SelectedObject, sourcePoint1Feature));
                string[] references = choices?.Cast<object>()
                    .Select(item => Convert.ToString(item) ?? string.Empty)
                    .Where(value => !string.IsNullOrWhiteSpace(value))
                    .ToArray()
                    ?? Array.Empty<string>();
                foreach (string expected in new[] { "LocateTopLeft/Center", "LocateTopRight/Center", "LocateBottomLeft/Center" })
                {
                    if (!references.Contains(expected, StringComparer.OrdinalIgnoreCase))
                    {
                        throw new InvalidOperationException("P219 Point picker missed " + expected + ".");
                    }
                }

                int runsBefore = shellHost.NativePreviewRunCount;
                shellHost.RecipeCommands.ApplySelectedStepParametersCommand.Execute(null);
                Pump(180);
                VisionPipeline saved = VisionPipelineStorage.Load(recipeName, pipeline.Name);
                VisionPipelineStep savedAffine = saved.Steps.Single(item => item.Name == "NormalizeFromThreePoints");
                if (savedAffine.Parameters.GetValueOrDefault(VisionPipelineAffinePointBindingService.UseDetectedSourcePointsParameter) != "True"
                    || savedAffine.Parameters.GetValueOrDefault(VisionPipelineAffinePointBindingService.SourcePoint1FeatureParameter) != "LocateTopLeft/Center"
                    || savedAffine.Parameters.GetValueOrDefault(VisionPipelineAffinePointBindingService.SourcePoint3FeatureParameter) != "LocateBottomLeft/Center"
                    || shellHost.NativePreviewRunCount != runsBefore)
                {
                    throw new InvalidOperationException("P219 detected Point bindings did not round-trip or triggered Preview/Run.");
                }

                TextBox search = GetActivePropertyGridSearchTextBox(grid, "P219 AffineTransform recipe step");
                search.Text = "Source point";
                search.GetBindingExpression(TextBox.TextProperty)?.UpdateSource();
                grid.UpdateLayout();
                Pump(60);
                ScrollViewer pipelineScroll = FindNamedVisualChild<ScrollViewer>(shellHost, "recipePipelineTabScrollViewer")
                    ?? throw new InvalidOperationException("P219 Pipeline scroll viewer was not found.");
                pipelineScroll.ScrollToBottom();
                pipelineScroll.UpdateLayout();
                Pump(80);
                if (grid.IsSearchEmptyMessageVisibleForTest || shellHost.NativePreviewRunCount != 0)
                {
                    throw new InvalidOperationException("P219 source-point search failed or changed Preview/Run state.");
                }
            }, captureFloatingToolWindow: false, captureScreen: true);
        }
        finally
        {
            RecipeWorkspaceService.DeleteVisionWorkspace(recipeName);
        }
    }

    private static void AssertP213GeometryCore(string screenshotOutputPath)
    {
        string directory = Path.GetDirectoryName(screenshotOutputPath) ?? ".";
        Directory.CreateDirectory(directory);
        using CvMat lineImage = new(300, 400, OpenCvSharp.MatType.CV_8UC1, OpenCvSharp.Scalar.White);
        Cv.Rectangle(lineImage, new OpenCvSharp.Rect(200, 0, 200, 300), OpenCvSharp.Scalar.Black, -1);
        VisionPipelineStep lineStep = new() { Name = "LineFeature", ToolType = "Line", InputLayer = "Reference", OutputLayer = "Line_Result" };
        AddParameters(lineStep,
            ("USE_ROI", "true"), ("CvROI", "150,30,100,240"),
            ("PRJ_DIR", "X_LTOR"), ("PRJ_PORALITY", "WTOB"),
            ("CONTRAST", "20"), ("THICKNESS", "3"), ("SAMPLING_STEP", "8"),
            ("SHOW_EDGE", "true"), ("SHOW_FITLINE", "true"));
        IVisionTool lineTool = VisionPipelineAppToolFactory.Create(lineStep);
        VisionToolResult lineResult = lineTool.Execute(lineImage);
        VisionPipelineGeometryFeatureCaptureService.Capture(lineStep, lineImage, lineTool, lineResult);
        IReadOnlyList<VisionPipelineGeometryFeatureResult> lineFeatures = VisionPipelineGeometryFeatureStore.Get(lineResult);
        if (lineResult?.Success != true
            || lineFeatures.Count != 4
            || lineFeatures.Single(item => item.FeatureName == "Segment").Kind != VisionPipelineGeometryKind.Segment)
        {
            throw new InvalidOperationException("P213 existing Line typed-feature export failed. " + (lineResult?.Message ?? "no result"));
        }
        Cv.ImWrite(Path.Combine(directory, "line_typed_feature_export.png"), lineResult.ResultImage);

        using CvMat circleImage = new(300, 400, OpenCvSharp.MatType.CV_8UC1, OpenCvSharp.Scalar.White);
        Cv.Circle(circleImage, new OpenCvSharp.Point(200, 150), 70, OpenCvSharp.Scalar.Black, 4, OpenCvSharp.LineTypes.AntiAlias);
        VisionPipelineStep circleStep = new()
        {
            Name = "CircleFeature", ToolType = "CircleGauge", InputLayer = "Reference", OutputLayer = "Circle_Result"
        };
        AddParameters(circleStep,
            ("USE_ROI", "true"), ("CvROI", "100,50,200,200"),
            ("CENTER_X", "200"), ("CENTER_Y", "150"),
            ("RADIUS_MIN", "60"), ("RADIUS_MAX", "80"),
            ("START_ANGLE_DEG", "0"), ("SWEEP_ANGLE_DEG", "360"),
            ("SCAN_COUNT", "180"), ("EDGE_POLARITY", "LightToDark"),
            ("MIN_CONTRAST", "20"), ("MIN_SUPPORT_RATIO", "0.8"),
            ("MAX_FIT_RESIDUAL_PX", "2"));
        VisionToolResult circleResult = VisionPipelineAppToolFactory.Create(circleStep).Execute(circleImage);
        if (circleResult?.Success != true
            || !circleResult.Metrics.TryGetValue(VisionPipelineKnownMetrics.CircleRadiusPx, out double radius)
            || Math.Abs(radius - 68D) > 4D
            || VisionPipelineGeometryFeatureStore.Get(circleResult).Count != 2)
        {
            throw new InvalidOperationException("P213 CircleGauge full-circle contract failed. " + (circleResult?.Message ?? "no result"));
        }
        Cv.ImWrite(Path.Combine(directory, "circle_gauge_full_circle.png"), circleResult.ResultImage);

        VisionPipelineStep partialStep = CloneStep(circleStep);
        partialStep.Name = "PartialArc";
        partialStep.Parameters["START_ANGLE_DEG"] = "20";
        partialStep.Parameters["SWEEP_ANGLE_DEG"] = "160";
        partialStep.Parameters["SCAN_COUNT"] = "80";
        VisionToolResult partialResult = VisionPipelineAppToolFactory.Create(partialStep).Execute(circleImage);
        if (partialResult?.Success != true || partialResult.Metrics.GetValueOrDefault(VisionPipelineKnownMetrics.CircleCoverageDeg) < 150D)
        {
            throw new InvalidOperationException("P213 CircleGauge partial-arc contract failed. " + partialResult?.Message);
        }
        Cv.ImWrite(Path.Combine(directory, "circle_gauge_partial_arc.png"), partialResult.ResultImage);

        using CvMat noEdgeImage = new(300, 400, OpenCvSharp.MatType.CV_8UC1, OpenCvSharp.Scalar.White);
        VisionToolResult noEdgeResult = VisionPipelineAppToolFactory.Create(circleStep).Execute(noEdgeImage);
        if (noEdgeResult.Success || !noEdgeResult.Message.Contains("support", StringComparison.OrdinalIgnoreCase))
        {
            throw new InvalidOperationException("P213 CircleGauge no-edge/support gate did not fail closed.");
        }
        Cv.ImWrite(Path.Combine(directory, "circle_gauge_no_edge_reject.png"), noEdgeResult.ResultImage);

        using CvMat polarityImage = new(300, 400, OpenCvSharp.MatType.CV_8UC1, OpenCvSharp.Scalar.White);
        Cv.Circle(polarityImage, new OpenCvSharp.Point(200, 150), 70, OpenCvSharp.Scalar.Black, -1, OpenCvSharp.LineTypes.AntiAlias);
        VisionToolResult polarityResult = VisionPipelineAppToolFactory.Create(circleStep).Execute(polarityImage);
        if (polarityResult.Success || !polarityResult.Message.Contains("support", StringComparison.OrdinalIgnoreCase))
        {
            throw new InvalidOperationException("P213 CircleGauge wrong-polarity gate did not fail closed.");
        }
        Cv.ImWrite(Path.Combine(directory, "circle_gauge_wrong_polarity_reject.png"), polarityResult.ResultImage);

        VisionPipelineStep missingRoiCircleStep = CloneStep(circleStep);
        missingRoiCircleStep.Parameters["USE_ROI"] = "false";
        VisionToolResult missingRoiResult = VisionPipelineAppToolFactory.Create(missingRoiCircleStep).Execute(circleImage);
        if (missingRoiResult.Success || !missingRoiResult.Message.Contains("USE_ROI=true", StringComparison.OrdinalIgnoreCase))
        {
            throw new InvalidOperationException("P213 CircleGauge reviewed-ROI gate did not fail closed.");
        }
        missingRoiResult.ResultImage?.Dispose();

        using CvMat sparseArcImage = new(300, 400, OpenCvSharp.MatType.CV_8UC1, OpenCvSharp.Scalar.White);
        Cv.Ellipse(sparseArcImage, new OpenCvSharp.Point(200, 150), new OpenCvSharp.Size(70, 70), 0, 0, 80, OpenCvSharp.Scalar.Black, 4, OpenCvSharp.LineTypes.AntiAlias);
        VisionToolResult sparseResult = VisionPipelineAppToolFactory.Create(circleStep).Execute(sparseArcImage);
        if (sparseResult.Success || !sparseResult.Message.Contains("support", StringComparison.OrdinalIgnoreCase))
        {
            throw new InvalidOperationException("P213 CircleGauge insufficient-coverage gate did not fail closed.");
        }
        Cv.ImWrite(Path.Combine(directory, "circle_gauge_insufficient_coverage_reject.png"), sparseResult.ResultImage);

        using CvMat ellipseImage = new(300, 400, OpenCvSharp.MatType.CV_8UC1, OpenCvSharp.Scalar.White);
        Cv.Ellipse(ellipseImage, new OpenCvSharp.Point(200, 150), new OpenCvSharp.Size(70, 60), 0, 0, 360, OpenCvSharp.Scalar.Black, 4, OpenCvSharp.LineTypes.AntiAlias);
        VisionPipelineStep residualStep = CloneStep(circleStep);
        residualStep.Parameters["RADIUS_MIN"] = "50";
        residualStep.Parameters["MAX_FIT_RESIDUAL_PX"] = "0.5";
        VisionToolResult residualResult = VisionPipelineAppToolFactory.Create(residualStep).Execute(ellipseImage);
        if (residualResult.Success || !residualResult.Message.Contains("residual", StringComparison.OrdinalIgnoreCase))
        {
            throw new InvalidOperationException("P213 CircleGauge excessive-residual gate did not fail closed. " + residualResult.Message);
        }
        Cv.ImWrite(Path.Combine(directory, "circle_gauge_excessive_residual_reject.png"), residualResult.ResultImage);

        using CvMat geometryImage = new(400, 500, OpenCvSharp.MatType.CV_8UC3, new OpenCvSharp.Scalar(32, 32, 32));
        foreach (GeometryMeasurementMode mode in Enum.GetValues<GeometryMeasurementMode>())
        {
            (VisionPipelineGeometryFeatureResult a, VisionPipelineGeometryFeatureResult b) = CreateGeometrySmokeInputs(mode);
            VisionPipelineRunResult priorRun = CreateGeometryPriorRun(a, b, geometryImage);
            VisionPipelineStep measure = CreateGeometryMeasureStep(mode, a, b);
            VisionToolResult measured = VisionPipelineGeometryMeasureService.Execute(measure, geometryImage, priorRun);
            if (measured?.Success != true || measured.Metrics.GetValueOrDefault(VisionPipelineKnownMetrics.ResultCount) != 1D)
            {
                throw new InvalidOperationException($"P213 geometry mode {mode} failed: {measured?.Message}");
            }
            Cv.ImWrite(Path.Combine(directory, "geometry_" + mode + ".png"), measured.ResultImage);
            measured.ResultImage?.Dispose();
            DisposePriorRun(priorRun);
        }

        VisionPipelineGeometryFeatureResult farA = Segment("LineA", 10, 10, 20, 10);
        VisionPipelineGeometryFeatureResult farB = Segment("LineB", 200, 200, 200, 220);
        VisionPipelineRunResult farRun = CreateGeometryPriorRun(farA, farB, geometryImage);
        VisionPipelineStep farMeasure = CreateGeometryMeasureStep(GeometryMeasurementMode.LineLineIntersection, farA, farB);
        farMeasure.Parameters[VisionPipelineGeometryMeasureService.MaximumExtensionAParameter] = "5";
        farMeasure.Parameters[VisionPipelineGeometryMeasureService.MaximumExtensionBParameter] = "5";
        VisionToolResult farResult = VisionPipelineGeometryMeasureService.Execute(farMeasure, geometryImage, farRun);
        if (farResult.Success || !farResult.Message.Contains("extension", StringComparison.OrdinalIgnoreCase))
        {
            throw new InvalidOperationException("P213 far-intersection gate did not fail closed.");
        }
        farResult.ResultImage?.Dispose();
        DisposePriorRun(farRun);

        AssertP213GeometryReject(
            geometryImage,
            GeometryMeasurementMode.PointPointDistance,
            Segment("WrongKind", 10, 10, 20, 10),
            PointFeature("PointB", 30, 30),
            "kind mismatch");

        VisionPipelineGeometryFeatureResult mismatchedFrame = PointFeature("PointA", 30, 30);
        mismatchedFrame.ImageWidth = 499;
        AssertP213GeometryReject(
            geometryImage,
            GeometryMeasurementMode.PointPointDistance,
            mismatchedFrame,
            PointFeature("PointB", 40, 40),
            "coordinate frame");

        AssertP213GeometryReject(
            geometryImage,
            GeometryMeasurementMode.LineLineAngle,
            Segment("Degenerate", 20, 20, 20, 20),
            Segment("LineB", 20, 20, 100, 20),
            "greater than zero");

        VisionPipelineGeometryFeatureResult roiA = Segment("LineA", 20, 100, 180, 100);
        VisionPipelineGeometryFeatureResult roiB = Segment("LineB", 100, 20, 100, 180);
        VisionPipelineRunResult invalidRoiRun = CreateGeometryPriorRun(roiA, roiB, geometryImage);
        VisionPipelineStep invalidRoiMeasure = CreateGeometryMeasureStep(GeometryMeasurementMode.LineLineIntersection, roiA, roiB);
        invalidRoiMeasure.Parameters["USE_ROI"] = "true";
        VisionToolResult invalidRoiResult = VisionPipelineGeometryMeasureService.Execute(invalidRoiMeasure, geometryImage, invalidRoiRun);
        if (invalidRoiResult.Success || !invalidRoiResult.Message.Contains("valid CvROI", StringComparison.OrdinalIgnoreCase))
        {
            throw new InvalidOperationException("P213 invalid intersection result-ROI gate did not fail closed.");
        }
        invalidRoiResult.ResultImage?.Dispose();
        DisposePriorRun(invalidRoiRun);

        AssertP213PropertyRoundTrip(circleStep);
        VisionPipeline pipeline = new() { Name = "P213Validation" };
        VisionPipelineStep lineA = new() { Name = "LineA", ToolType = "Line", Enabled = true, InputLayer = "Reference", OutputLayer = "LineA_Result" };
        VisionPipelineStep lineB = new() { Name = "LineB", ToolType = "Line", Enabled = true, InputLayer = "Reference", OutputLayer = "LineB_Result" };
        VisionPipelineStep geometry = CreateGeometryMeasureStep(GeometryMeasurementMode.LineLineAngle, Segment("LineA", 10, 10, 100, 10), Segment("LineB", 10, 10, 10, 100));
        geometry.InputLayer = "Reference";
        pipeline.Steps.Add(lineA); pipeline.Steps.Add(lineB); pipeline.Steps.Add(geometry);
        VisionPipelineValidationResult validation = VisionPipelineValidator.Validate(pipeline, new[] { "Reference" });
        if (!validation.Success)
        {
            throw new InvalidOperationException("P213 valid geometry pipeline did not validate: " + validation.FormatErrors());
        }

        VisionPipeline invalidCirclePipeline = new() { Name = "P213InvalidCircle" };
        invalidCirclePipeline.Steps.Add(missingRoiCircleStep);
        VisionPipelineValidationResult invalidCircleValidation = VisionPipelineValidator.Validate(invalidCirclePipeline, new[] { "Reference" });
        if (invalidCircleValidation.Success
            || !invalidCircleValidation.FormatErrors().Contains("USE_ROI=true", StringComparison.OrdinalIgnoreCase))
        {
            throw new InvalidOperationException("P213 validator accepted CircleGauge without a reviewed ROI.");
        }

        AssertP213GeometryReportPersistence(directory, lineFeatures);

        circleResult.ResultImage?.Dispose();
        lineResult.ResultImage?.Dispose();
        partialResult.ResultImage?.Dispose();
        noEdgeResult.ResultImage?.Dispose();
        polarityResult.ResultImage?.Dispose();
        sparseResult.ResultImage?.Dispose();
        residualResult.ResultImage?.Dispose();
    }

    private static void AssertP213GeometryReject(
        CvMat image,
        GeometryMeasurementMode mode,
        VisionPipelineGeometryFeatureResult a,
        VisionPipelineGeometryFeatureResult b,
        string expectedMessage)
    {
        VisionPipelineRunResult priorRun = CreateGeometryPriorRun(a, b, image);
        try
        {
            VisionPipelineStep measure = CreateGeometryMeasureStep(mode, a, b);
            VisionToolResult result = VisionPipelineGeometryMeasureService.Execute(measure, image, priorRun);
            try
            {
                if (result.Success || !result.Message.Contains(expectedMessage, StringComparison.OrdinalIgnoreCase))
                {
                    throw new InvalidOperationException(
                        $"P213 {mode} negative gate did not fail with '{expectedMessage}': {result.Message}");
                }
            }
            finally
            {
                result.ResultImage?.Dispose();
            }
        }
        finally
        {
            DisposePriorRun(priorRun);
        }
    }

    private static void AssertP213GeometryReportPersistence(
        string artifactDirectory,
        IReadOnlyList<VisionPipelineGeometryFeatureResult> features)
    {
        string recipeName = "Smoke_P213Geometry_" + Guid.NewGuid().ToString("N");
        try
        {
            VisionPipelineStep step = new() { Name = "LineFeature", ToolType = "Line", Enabled = true, InputLayer = "Reference", OutputLayer = "Line_Result" };
            VisionPipeline pipeline = new() { Name = "GeometryPersistence" };
            pipeline.Steps.Add(step);
            DateTime started = DateTime.UtcNow;

            VisionToolResult directToolResult = VisionToolResult.Passed(null, TimeSpan.Zero);
            VisionPipelineGeometryFeatureStore.Set(directToolResult, features);
            VisionPipelineRunResult directRun = new();
            directRun.StepResults.Add(new VisionPipelineStepResult { Step = step, ToolResult = directToolResult, AcceptancePassed = true });
            string directPath = VisionPipelineRunReportStorage.Save(recipeName, pipeline, directRun, started, started.AddMilliseconds(1), false, "GeometryDirect");
            VisionPipelineRunReport directReport = VisionPipelineRunReportStorage.Load(directPath)
                ?? throw new InvalidOperationException("P213 direct geometry report could not be loaded.");
            AssertGeometryRows(directReport, "direct");

            using VisionRecipeRunResult recipeResult = new()
            {
                PipelineName = pipeline.Name,
                Success = true,
                Steps = new List<VisionRecipeStepRunSummary>
                {
                    new VisionRecipeStepRunSummary
                    {
                        Index = 1, Name = step.Name, ToolType = step.ToolType, Enabled = true,
                        InputLayer = step.InputLayer, OutputLayer = step.OutputLayer,
                        Status = "OK", ToolSuccess = true, Success = true, AcceptancePassed = true,
                        GeometryFeatures = features.Select(item => item.Clone()).ToList()
                    }
                }
            };
            string recipePath = VisionPipelineRunReportStorage.Save(recipeName, pipeline, recipeResult, started, started.AddMilliseconds(1), "GeometryRecipe");
            VisionPipelineRunReport recipeReport = VisionPipelineRunReportStorage.Load(recipePath)
                ?? throw new InvalidOperationException("P213 recipe geometry report could not be loaded.");
            AssertGeometryRows(recipeReport, "recipe");

            File.Copy(directPath, Path.Combine(artifactDirectory, "geometry_direct_report.xml"), true);
            File.Copy(recipePath, Path.Combine(artifactDirectory, "geometry_recipe_report.xml"), true);
        }
        finally
        {
            RecipeWorkspaceService.DeleteVisionWorkspace(recipeName);
        }
    }

    private static void AssertGeometryRows(VisionPipelineRunReport report, string context)
    {
        List<VisionPipelineGeometryFeatureResult> rows = report?.Steps?.SingleOrDefault()?.GeometryFeatures
            ?? new List<VisionPipelineGeometryFeatureResult>();
        if (rows.Count != 4
            || rows.SingleOrDefault(item => item.FeatureName == "Segment")?.Kind != VisionPipelineGeometryKind.Segment
            || rows.Any(item => item.CoordinateLayer != "Reference" || item.ImageWidth <= 0 || item.ImageHeight <= 0))
        {
            throw new InvalidOperationException("P213 " + context + " report did not preserve typed geometry rows and provenance.");
        }
    }

    private static void AssertP213PropertyRoundTrip(VisionPipelineStep circleStep)
    {
        object circleProperty = VisionPipelineStepPropertyMapper.CreateProperty(circleStep)
            ?? throw new InvalidOperationException("P213 CircleGauge PropertyGrid mapping returned null.");
        VisionPipelineStep circleRoundTrip = CloneStep(circleStep);
        if (!VisionPipelineStepPropertyMapper.ApplyProperty(circleRoundTrip, circleProperty)
            || circleRoundTrip.ToolType != "CircleGauge"
            || circleRoundTrip.Parameters.GetValueOrDefault("EDGE_POLARITY") != "LightToDark"
            || circleRoundTrip.Parameters.GetValueOrDefault("SCAN_COUNT") != "180")
        {
            throw new InvalidOperationException("P213 CircleGauge PropertyGrid round trip failed.");
        }

        VisionPipelineStep geometry = CreateGeometryMeasureStep(
            GeometryMeasurementMode.LineLineIntersection,
            Segment("LineA", 0, 0, 100, 0),
            Segment("LineB", 50, -50, 50, 50));
        VisionPipeline pipeline = new() { Name = "FeaturePicker" };
        pipeline.Steps.Add(new VisionPipelineStep { Name = "LineA", ToolType = "Line", InputLayer = "Reference", OutputLayer = "A" });
        pipeline.Steps.Add(new VisionPipelineStep { Name = "LineB", ToolType = "Line", InputLayer = "Reference", OutputLayer = "B" });
        pipeline.Steps.Add(geometry);
        object property = VisionPipelineStepPropertyMapper.CreateProperty(
            geometry,
            new VisionPipelinePropertyContext(pipeline, 2))
            ?? throw new InvalidOperationException("P213 GeometryMeasure PropertyGrid mapping returned null.");
        PropertyDescriptor sourceAProperty = TypeDescriptor.GetProperties(property)["SourceA"]
            ?? throw new InvalidOperationException("P213 feature picker SourceA property is missing.");
        TypeConverter.StandardValuesCollection? values = sourceAProperty.Converter.GetStandardValues(new PropertyContext(property, sourceAProperty));
        if (values == null || !values.Cast<object>().Select(item => Convert.ToString(item) ?? string.Empty).Contains("LineA/Segment", StringComparer.OrdinalIgnoreCase))
        {
            throw new InvalidOperationException("P213 compatible feature picker did not list the earlier Line segment.");
        }
        VisionPipelineStep roundTrip = CloneStep(geometry);
        if (!VisionPipelineStepPropertyMapper.ApplyProperty(roundTrip, property)
            || roundTrip.Parameters.GetValueOrDefault(VisionPipelineGeometryMeasureService.SourceFeatureAParameter) != "Segment")
        {
            throw new InvalidOperationException("P213 GeometryMeasure PropertyGrid round trip failed.");
        }

        VisionPipelineStep geometryAlias = CloneStep(geometry);
        geometryAlias.ToolType = "GeometricMeasurementTool";
        object geometryAliasProperty = VisionPipelineStepPropertyMapper.CreateProperty(
            geometryAlias,
            new VisionPipelinePropertyContext(pipeline, 2))
            ?? throw new InvalidOperationException("P213 GeometricMeasurementTool alias returned no property object.");
        VisionPipelineStep geometryAliasRoundTrip = new();
        if (!VisionPipelineStepPropertyMapper.ApplyProperty(
                geometryAliasRoundTrip,
                geometryAliasProperty)
            || geometryAliasRoundTrip.ToolType != "GeometryMeasure"
            || geometryAliasRoundTrip.Parameters.GetValueOrDefault(
                VisionPipelineGeometryMeasureService.SourceFeatureAParameter) != "Segment")
        {
            throw new InvalidOperationException("P213 GeometricMeasurementTool alias round trip changed.");
        }

        VisionPipelineStep circleAlias = CloneStep(circleStep);
        circleAlias.ToolType = "CircleGaugeTool";
        object circleAliasProperty = VisionPipelineStepPropertyMapper.CreateProperty(circleAlias)
            ?? throw new InvalidOperationException("P213 CircleGaugeTool alias returned no property object.");
        VisionPipelineStep circleAliasRoundTrip = new();
        if (!VisionPipelineStepPropertyMapper.ApplyProperty(
                circleAliasRoundTrip,
                circleAliasProperty)
            || circleAliasRoundTrip.ToolType != "CircleGauge"
            || circleAliasRoundTrip.Parameters.GetValueOrDefault("SCAN_COUNT") != "180")
        {
            throw new InvalidOperationException("P213 CircleGaugeTool alias round trip changed.");
        }
    }

    private static VisionPipelineStep CreateGeometryMeasureStep(GeometryMeasurementMode mode, VisionPipelineGeometryFeatureResult a, VisionPipelineGeometryFeatureResult b)
    {
        VisionPipelineStep step = new() { Name = "Measure", ToolType = "GeometryMeasure", InputLayer = "Reference", OutputLayer = "Measure_Result" };
        AddParameters(step,
            (VisionPipelineGeometryMeasureService.ModeParameter, mode.ToString()),
            (VisionPipelineGeometryMeasureService.SourceStepAParameter, a.SourceStep),
            (VisionPipelineGeometryMeasureService.SourceFeatureAParameter, a.FeatureName),
            (VisionPipelineGeometryMeasureService.SourceStepBParameter, b.SourceStep),
            (VisionPipelineGeometryMeasureService.SourceFeatureBParameter, b.FeatureName),
            (VisionPipelineGeometryMeasureService.MaximumParallelAngleDeltaParameter, "3"),
            (VisionPipelineGeometryMeasureService.MaximumExtensionAParameter, "500"),
            (VisionPipelineGeometryMeasureService.MaximumExtensionBParameter, "500"),
            (VisionPipelineGeometryMeasureService.RequireResultInImageParameter, "true"),
            (VisionPipelineNormalizer.AllowBranchInputParameter, "true"));
        return step;
    }

    private static (VisionPipelineGeometryFeatureResult A, VisionPipelineGeometryFeatureResult B) CreateGeometrySmokeInputs(GeometryMeasurementMode mode)
    {
        return mode switch
        {
            GeometryMeasurementMode.PointPointDistance => (PointFeature("PointA", 50, 50), PointFeature("PointB", 80, 90)),
            GeometryMeasurementMode.PointLineDistance => (PointFeature("PointA", 50, 80), Segment("LineB", 20, 40, 160, 40)),
            GeometryMeasurementMode.SegmentSegmentDistance => (Segment("LineA", 20, 40, 120, 40), Segment("LineB", 150, 70, 150, 160)),
            GeometryMeasurementMode.LineLineDistance => (Segment("LineA", 20, 40, 180, 40), Segment("LineB", 20, 90, 180, 90)),
            GeometryMeasurementMode.LineLineAngle => (Segment("LineA", 20, 40, 180, 40), Segment("LineB", 50, 20, 50, 180)),
            GeometryMeasurementMode.LineLineIntersection => (Segment("LineA", 20, 100, 180, 100), Segment("LineB", 100, 20, 100, 180)),
            GeometryMeasurementMode.CircleSegmentClearance => (CircleFeature("CircleA", 100, 100, 30), Segment("LineB", 160, 20, 160, 180)),
            _ => throw new ArgumentOutOfRangeException(nameof(mode))
        };
    }

    private static VisionPipelineRunResult CreateGeometryPriorRun(VisionPipelineGeometryFeatureResult a, VisionPipelineGeometryFeatureResult b, CvMat image)
    {
        VisionPipelineRunResult run = new();
        foreach (IGrouping<string, VisionPipelineGeometryFeatureResult> group in new[] { a, b }.GroupBy(item => item.SourceStep, StringComparer.OrdinalIgnoreCase))
        {
            VisionToolResult toolResult = VisionToolResult.Passed(image.Clone(), TimeSpan.Zero);
            VisionPipelineGeometryFeatureStore.Set(toolResult, group);
            run.StepResults.Add(new VisionPipelineStepResult
            {
                Step = new VisionPipelineStep { Name = group.Key, ToolType = group.First().Kind == VisionPipelineGeometryKind.Circle ? "CircleGauge" : "Line", Enabled = true, InputLayer = "Reference", OutputLayer = group.Key + "_Result" },
                ToolResult = toolResult,
                AcceptancePassed = true
            });
        }
        return run;
    }

    private static void DisposePriorRun(VisionPipelineRunResult run)
    {
        foreach (VisionPipelineStepResult item in run.StepResults) item.ToolResult?.ResultImage?.Dispose();
    }

    private static VisionPipelineGeometryFeatureResult PointFeature(string step, double x, double y) => new()
    {
        SourceStep = step, FeatureName = "Midpoint", Kind = VisionPipelineGeometryKind.Point,
        CoordinateLayer = "Reference", ImageWidth = 500, ImageHeight = 400,
        X1 = x, Y1 = y, CenterX = x, CenterY = y, SupportCount = 1, SupportRatio = 1
    };
    private static VisionPipelineGeometryFeatureResult Segment(string step, double x1, double y1, double x2, double y2) => new()
    {
        SourceStep = step, FeatureName = "Segment", Kind = VisionPipelineGeometryKind.Segment,
        CoordinateLayer = "Reference", ImageWidth = 500, ImageHeight = 400,
        X1 = x1, Y1 = y1, X2 = x2, Y2 = y2, CenterX = (x1 + x2) / 2, CenterY = (y1 + y2) / 2,
        SupportCount = 12, SupportRatio = 1
    };
    private static VisionPipelineGeometryFeatureResult CircleFeature(string step, double x, double y, double radius) => new()
    {
        SourceStep = step, FeatureName = "Circle", Kind = VisionPipelineGeometryKind.Circle,
        CoordinateLayer = "Reference", ImageWidth = 500, ImageHeight = 400,
        X1 = x, Y1 = y, CenterX = x, CenterY = y, RadiusPx = radius,
        SupportCount = 120, SupportRatio = 1, CoverageDeg = 360
    };

    private static void AddParameters(VisionPipelineStep step, params (string Key, string Value)[] parameters)
    {
        foreach ((string key, string value) in parameters) step.Parameters[key] = value;
    }

    private static VisionPipelineStep CloneStep(VisionPipelineStep source)
    {
        VisionPipelineStep clone = new() { Name = source.Name, ToolType = source.ToolType, Enabled = source.Enabled, InputLayer = source.InputLayer, OutputLayer = source.OutputLayer };
        foreach (KeyValuePair<string, string> item in source.Parameters) clone.Parameters[item.Key] = item.Value;
        return clone;
    }

    private static void AssertSingleLineGaugePropertyMapperRoundTrip(VisionPipelineStep source)
    {
        if (source == null
            || !string.Equals(source.ToolType, "LineGauge", StringComparison.Ordinal)
            || source.Parameters == null)
        {
            throw new InvalidOperationException("Line Edge Tool View did not create a canonical LineGauge Step.");
        }

        foreach (string alias in new[] { "LineTool", "LineGaugeTool" })
        {
            VisionPipelineStep aliasStep = CloneStep(source);
            aliasStep.ToolType = alias;
            if (VisionPipelineStepPropertyMapper.CreateProperty(aliasStep) is not LineGaugeProperty)
            {
                throw new InvalidOperationException(
                    $"Single LineGauge alias '{alias}' did not create the PropertyGrid model.");
            }
        }

        VisionPipelineStep applyStep = CloneStep(source);
        applyStep.Name = "Single Line Reviewed";
        applyStep.Parameters["Name"] = applyStep.Name;
        applyStep.ToolType = "LineTool";
        applyStep.InputLayer = "ReviewedInput";
        applyStep.OutputLayer = "ReviewedLineOutput";
        applyStep.Enabled = false;
        applyStep.UseAcceptance = true;
        applyStep.ExpectedSuccess = false;
        applyStep.MaxElapsedMilliseconds = 76;
        applyStep.RequiredMessageText = "line-reviewed";
        applyStep.AcceptanceMetricName = "LineLengthMax";
        applyStep.UseAcceptanceMetricMinimum = true;
        applyStep.AcceptanceMetricMinimum = 20;
        applyStep.UseAcceptanceMetricMaximum = true;
        applyStep.AcceptanceMetricMaximum = 240;
        AddParameters(
            applyStep,
            ("PIXELPERMM", "0.025"),
            ("USE_ROI", "true"),
            ("CvROI", "12,18,160,120"),
            ("USE_THRESHOLD", "false"),
            ("USE_ADAPTIVE_THRESHOLD", "false"),
            ("PRJ_PORALITY", "WTOB"),
            ("PRJ_DIR", "Y_TTOB"),
            ("CONTRAST", "42"),
            ("THICKNESS", "7"),
            ("SAMPLING_STEP", "11"),
            ("VER_PRJ_DIR", "Y_BTOT"),
            ("POINT_RANGE", "14"),
            ("USE_MANUAL_ANGLE", "true"),
            ("MANUAL_ANGLE_VALUE", "12.5"),
            ("USE_EXTEND_FIT_LINE", "true"),
            ("EXTEND_FIT_LINE_VALUE", "120"),
            ("AVERAGE_Diff", "88"),
            ("USE_AVERAGE_FILTER", "true"),
            ("AVERAGE_FILTER_TYPE", "X"),
            ("SHOW_VERTICAL_LINE", "false"),
            ("SHOW_EDGE", "true"),
            ("SHOW_CONTOUR", "false"),
            ("SHOW_FITLINE", "true"));
        object applyProperty = VisionPipelineStepPropertyMapper.CreateProperty(applyStep);
        applyStep.Name = "Changed";
        applyStep.ToolType = "Mean";
        applyStep.InputLayer = "ChangedInput";
        applyStep.OutputLayer = "ChangedOutput";
        applyStep.Enabled = true;
        applyStep.UseAcceptance = false;
        applyStep.ExpectedSuccess = true;
        applyStep.MaxElapsedMilliseconds = 0;
        applyStep.RequiredMessageText = string.Empty;
        applyStep.AcceptanceMetricName = string.Empty;
        applyStep.UseAcceptanceMetricMinimum = false;
        applyStep.AcceptanceMetricMinimum = 0;
        applyStep.UseAcceptanceMetricMaximum = false;
        applyStep.AcceptanceMetricMaximum = 0;
        applyStep.Parameters.Clear();
        applyStep.Parameters["Name"] = "Changed";
        if (!VisionPipelineStepPropertyMapper.ApplyProperty(applyStep, applyProperty)
            || !string.Equals(applyStep.Name, "Single Line Reviewed", StringComparison.Ordinal)
            || !string.Equals(applyStep.ToolType, "LineGauge", StringComparison.Ordinal)
            || !string.Equals(applyStep.InputLayer, "ReviewedInput", StringComparison.Ordinal)
            || !string.Equals(applyStep.OutputLayer, "ReviewedLineOutput", StringComparison.Ordinal)
            || applyStep.Enabled
            || !applyStep.UseAcceptance
            || applyStep.ExpectedSuccess
            || Math.Abs(applyStep.MaxElapsedMilliseconds - 76D) > 0.000001D
            || !string.Equals(applyStep.RequiredMessageText, "line-reviewed", StringComparison.Ordinal)
            || !string.Equals(applyStep.AcceptanceMetricName, "LineLengthMax", StringComparison.Ordinal)
            || !applyStep.UseAcceptanceMetricMinimum
            || Math.Abs(applyStep.AcceptanceMetricMinimum - 20D) > 0.000001D
            || !applyStep.UseAcceptanceMetricMaximum
            || Math.Abs(applyStep.AcceptanceMetricMaximum - 240D) > 0.000001D)
        {
            throw new InvalidOperationException(
                "Single LineGauge alias/apply metadata and layer round trip changed.");
        }

        foreach ((string key, object expected) in new (string, object)[]
        {
            ("PIXELPERMM", 0.025D),
            ("USE_ROI", true),
            ("CvROI", "12,18,160,120"),
            ("USE_THRESHOLD", false),
            ("USE_ADAPTIVE_THRESHOLD", false),
            ("PRJ_PORALITY", "WTOB"),
            ("PRJ_DIR", "Y_TTOB"),
            ("CONTRAST", 42D),
            ("THICKNESS", 7D),
            ("SAMPLING_STEP", 11D),
            ("VER_PRJ_DIR", "Y_BTOT"),
            ("POINT_RANGE", 14D),
            ("USE_MANUAL_ANGLE", true),
            ("MANUAL_ANGLE_VALUE", 12.5D),
            ("USE_EXTEND_FIT_LINE", true),
            ("EXTEND_FIT_LINE_VALUE", 120D),
            ("AVERAGE_Diff", 88D),
            ("USE_AVERAGE_FILTER", true),
            ("AVERAGE_FILTER_TYPE", "X"),
            ("SHOW_VERTICAL_LINE", false),
            ("SHOW_EDGE", true),
            ("SHOW_CONTOUR", false),
            ("SHOW_FITLINE", true)
        })
        {
            AssertParameterValue(applyStep, key, expected);
        }
    }

    private sealed class ParameterGuideFallbackProbe
    {
        [Category("Probe")]
        [DisplayName("Unregistered parameter")]
        [Description("A smoke-only property used to verify the Basic fallback contract.")]
        public bool UNREGISTERED_PARAMETER { get; set; } = true;
    }

    private sealed class PropertyContext : ITypeDescriptorContext
    {
        public PropertyContext(object instance, PropertyDescriptor descriptor) { Instance = instance; PropertyDescriptor = descriptor; }
        public IContainer? Container => null;
        public object Instance { get; }
        public PropertyDescriptor PropertyDescriptor { get; }
        public object? GetService(Type serviceType) => null;
        public bool OnComponentChanging() => true;
        public void OnComponentChanged() { }
    }

    private static CaptureResult CaptureShellHostPipelineReview(string outputPath)
    {
        return CaptureShellHostPipelineReview(outputPath, OpenVisionLanguage.Korean);
    }

    private static CaptureResult CaptureShellHostPipelineReview(
        string outputPath,
        OpenVisionLanguage language)
    {
        OpenVisionLanguageService.SetLanguage(language, false);
        string recipeName = "Smoke_WpfPipelineReview_" + Guid.NewGuid().ToString("N");
        OpenVisionShellHostView shellHost = CreateShellHost(recipeName);
        OpenVisionLanguageService.SetLanguage(language, false);
        VisionPipeline pipeline = CreatePipelineReviewReadabilityPipeline();
        VisionPipelineStorage.Save(recipeName, pipeline);
        VisionPipelineStorage.SaveActivePipelineName(recipeName, pipeline.Name);
        return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
        {
            shellHost.SelectToolForTest(VISION_MENU.Pipeline);
            Pump(24);
            OpenVisionLanguageService.SetLanguage(language, false);
            Pump(24);
            Window reviewWindow = GetActiveFloatingToolWindow("Pipeline review readiness");
            AssertVisibleAutomationIds(
                reviewWindow,
                "Pipeline review readiness",
                "PipelineReviewReadinessStrip",
                "PipelineReviewReadinessSummary",
                "PipelineReviewReadinessInput",
                "PipelineReviewReadinessRoute",
                "PipelineReviewReadinessAcceptance",
                "PipelineReviewReadinessGoodBad",
                "PipelineReviewReadinessCalibration");
            string expectedKoreanReadinessSummary = string.Format(
                CultureInfo.CurrentCulture,
                OpenVisionLanguageService.T("PipelineReview.Readiness.SummaryChecksAndAdviceFormat"),
                1,
                2);
            string readinessSummary = ReadVisibleTextByAutomationId(reviewWindow, "PipelineReviewReadinessSummary");
            string acceptanceReadiness = ReadVisibleTextByAutomationId(reviewWindow, "PipelineReviewReadinessAcceptanceStatus");
            string calibrationReadiness = ReadVisibleTextByAutomationId(reviewWindow, "PipelineReviewReadinessCalibrationStatus");
            if (!string.Equals(readinessSummary, expectedKoreanReadinessSummary, StringComparison.Ordinal)
                || !string.Equals(
                    acceptanceReadiness,
                    OpenVisionLanguageService.T("PipelineReview.Readiness.AcceptanceMissing"),
                    StringComparison.Ordinal)
                || !string.Equals(
                    calibrationReadiness,
                    OpenVisionLanguageService.T("PipelineReview.Readiness.CalibrationNotApplicable"),
                    StringComparison.Ordinal)
                || shellHost.NativePreviewRunCount != 0)
            {
                throw new InvalidOperationException(
                    "Pipeline review readiness did not expose the expected read-only preflight state. "
                    + $"Summary='{readinessSummary}', Acceptance='{acceptanceReadiness}', Calibration='{calibrationReadiness}', "
                    + $"Runs={shellHost.NativePreviewRunCount}");
            }
            AssertPipelineReviewCalibrationReadiness();

            string koreanBeforeRunDetail = OpenVisionLanguageService.T("PipelineReview.Guide.BeforeRunDetail");
            string koreanBranchFlow = string.Format(
                CultureInfo.CurrentCulture,
                OpenVisionLanguageService.T("PipelineReview.Flow.BranchInputFormat"),
                "Main",
                "Morphology_Preview");
            string koreanBranchDetail = string.Format(
                CultureInfo.CurrentCulture,
                OpenVisionLanguageService.T("PipelineReview.Guide.BranchDetailFormat"),
                "Main",
                "Morphology_Preview");
            string koreanFinalNextAction = OpenVisionLanguageService.T("PipelineReview.Guide.OkFinalNext");
            string koreanFinalDetail = OpenVisionLanguageService.T("PipelineReview.Guide.OkFinalDetail");
            if (shellHost.PipelineReviewStepCount != 3
                || !shellHost.PipelineReviewSelectedStepName.Contains("Threshold", StringComparison.OrdinalIgnoreCase)
                || string.IsNullOrWhiteSpace(shellHost.PipelineReviewFlowSummaryText)
                || string.IsNullOrWhiteSpace(shellHost.PipelineReviewParameterSummaryText))
            {
                throw new InvalidOperationException("Pipeline review did not show the configured multi-step pipeline.");
            }

            if (!shellHost.PipelineReviewGuideStageText.Contains("1/3", StringComparison.Ordinal)
                || !shellHost.PipelineReviewGuideCurrentStepText.Contains("Threshold", StringComparison.OrdinalIgnoreCase)
                || !shellHost.PipelineReviewGuideCurrentStepText.Contains("Main", StringComparison.OrdinalIgnoreCase)
                || string.IsNullOrWhiteSpace(shellHost.PipelineReviewGuideNextActionText)
                || string.IsNullOrWhiteSpace(shellHost.PipelineReviewGuideResultDecisionText)
                || shellHost.PipelineReviewGuideResultDecisionText.Contains("OK", StringComparison.OrdinalIgnoreCase)
                || !shellHost.PipelineReviewGuideDetailText.Contains(koreanBeforeRunDetail, StringComparison.Ordinal)
                || shellHost.CanSelectPreviousPipelineReviewStepForTest
                || !shellHost.CanSelectNextPipelineReviewStepForTest)
            {
                throw new InvalidOperationException(
                    "Pipeline review guide did not expose a beginner-readable pre-run state. "
                    + $"Stage='{shellHost.PipelineReviewGuideStageText}', Current='{shellHost.PipelineReviewGuideCurrentStepText}', "
                    + $"Next='{shellHost.PipelineReviewGuideNextActionText}', Decision='{shellHost.PipelineReviewGuideResultDecisionText}', "
                    + $"Detail='{shellHost.PipelineReviewGuideDetailText}', Prev={shellHost.CanSelectPreviousPipelineReviewStepForTest}, Next={shellHost.CanSelectNextPipelineReviewStepForTest}");
            }

            shellHost.SelectPipelineReviewStepForTest(0, OpenVisionLab.Pipeline.Controls.PipelineFlowPreviewMode.Input);
            Pump(8);
            if (!shellHost.HasPipelineReviewInputPreview)
            {
                throw new InvalidOperationException("Pipeline review did not expose the selected input preview.");
            }

            ClickVisibleButtonByName("btnNextStep", "Pipeline review next step button");
            string pendingInputNext = OpenVisionLanguageService.T("PipelineReview.Guide.InputPendingNext");
            string pendingInputDetail = OpenVisionLanguageService.T("PipelineReview.Guide.InputPendingDetail");
            if (!shellHost.PipelineReviewSelectedStepName.Contains("Morphology", StringComparison.OrdinalIgnoreCase)
                || !shellHost.PipelineReviewGuideStageText.Contains("2/3", StringComparison.Ordinal)
                || !string.Equals(shellHost.PipelineReviewSelectedStatusText, "WAIT", StringComparison.Ordinal)
                || !shellHost.PipelineReviewGuideNextActionText.Contains(pendingInputNext, StringComparison.Ordinal)
                || !shellHost.PipelineReviewGuideDetailText.Contains(pendingInputDetail, StringComparison.Ordinal)
                || !shellHost.CanSelectPreviousPipelineReviewStepForTest
                || !shellHost.CanSelectNextPipelineReviewStepForTest)
            {
                throw new InvalidOperationException(
                    "Pipeline review next-step button did not select the second step. "
                    + $"Selected='{shellHost.PipelineReviewSelectedStepName}', Stage='{shellHost.PipelineReviewGuideStageText}', "
                    + $"Status='{shellHost.PipelineReviewSelectedStatusText}', NextAction='{shellHost.PipelineReviewGuideNextActionText}', "
                    + $"Detail='{shellHost.PipelineReviewGuideDetailText}', Prev={shellHost.CanSelectPreviousPipelineReviewStepForTest}, "
                    + $"Next={shellHost.CanSelectNextPipelineReviewStepForTest}");
            }

            ClickVisibleButtonByName("btnNextStep", "Pipeline review branch step button");
            if (!shellHost.PipelineReviewSelectedStepName.Contains("Filter", StringComparison.OrdinalIgnoreCase)
                || !shellHost.PipelineReviewGuideStageText.Contains("3/3", StringComparison.Ordinal)
                || !shellHost.PipelineReviewFlowSummaryText.Contains(koreanBranchFlow, StringComparison.Ordinal)
                || !shellHost.PipelineReviewGuideDetailText.Contains(koreanBranchDetail, StringComparison.Ordinal)
                || !shellHost.CanSelectPreviousPipelineReviewStepForTest
                || shellHost.CanSelectNextPipelineReviewStepForTest)
            {
                throw new InvalidOperationException(
                    "Pipeline review did not expose the branch-step explanation. "
                    + $"Selected='{shellHost.PipelineReviewSelectedStepName}', Stage='{shellHost.PipelineReviewGuideStageText}', "
                    + $"Flow='{shellHost.PipelineReviewFlowSummaryText}', Detail='{shellHost.PipelineReviewGuideDetailText}', "
                    + $"Prev={shellHost.CanSelectPreviousPipelineReviewStepForTest}, Next={shellHost.CanSelectNextPipelineReviewStepForTest}");
            }

            if (language == OpenVisionLanguage.Korean)
            {
                OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.English, false);
                Pump(16);
                string expectedEnglishReadinessSummary = string.Format(
                    CultureInfo.CurrentCulture,
                    OpenVisionLanguageService.T("PipelineReview.Readiness.SummaryChecksAndAdviceFormat"),
                    1,
                    2);
                if (!shellHost.PipelineReviewGuideCurrentStepText.Contains("Filter", StringComparison.OrdinalIgnoreCase)
                    || !shellHost.PipelineReviewGuideDetailText.Contains("Branch:", StringComparison.Ordinal)
                    || !shellHost.PipelineReviewGuideNextActionText.Contains("Run Review", StringComparison.Ordinal)
                    || !string.Equals(
                        ReadVisibleTextByAutomationId(reviewWindow, "PipelineReviewReadinessSummary"),
                        expectedEnglishReadinessSummary,
                        StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        "Pipeline review guide and readiness did not recalculate dynamic text after switching to English. "
                        + $"Current='{shellHost.PipelineReviewGuideCurrentStepText}', Stage='{shellHost.PipelineReviewGuideStageText}', "
                        + $"Flow='{shellHost.PipelineReviewFlowSummaryText}', Next='{shellHost.PipelineReviewGuideNextActionText}', "
                        + $"Detail='{shellHost.PipelineReviewGuideDetailText}'");
                }

                OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
                Pump(16);
            }
            WaitForTaskWithPump(shellHost.RunPipelineReviewForTestAsync(), 30000, "Pipeline review execution");
            Pump(32);
            if (string.IsNullOrWhiteSpace(shellHost.PipelineReviewValidationStatusText)
                || !shellHost.PipelineReviewResultSummaryText.Contains("OK", StringComparison.OrdinalIgnoreCase)
                || string.IsNullOrWhiteSpace(shellHost.PipelineReviewRunLogText))
            {
                throw new InvalidOperationException("Pipeline review did not complete with a visible OK result. Validation='"
                    + shellHost.PipelineReviewValidationStatusText
                    + "', Result='"
                    + shellHost.PipelineReviewResultSummaryText
                    + "'.");
            }

            if (!shellHost.HasPipelineReviewOutputPreview)
            {
                throw new InvalidOperationException("Pipeline review did not expose the selected branch output preview after review.");
            }

            if (!shellHost.PipelineReviewGuideResultDecisionText.Contains("OK", StringComparison.OrdinalIgnoreCase)
                || !shellHost.PipelineReviewGuideNextActionText.Contains(koreanFinalNextAction, StringComparison.Ordinal)
                || !shellHost.PipelineReviewGuideCurrentStepText.Contains("Filter", StringComparison.OrdinalIgnoreCase)
                || !shellHost.PipelineReviewGuideDetailText.Contains(koreanFinalDetail, StringComparison.Ordinal))
            {
                throw new InvalidOperationException(
                    "Pipeline review guide did not expose the completed OK decision state. "
                    + $"Current='{shellHost.PipelineReviewGuideCurrentStepText}', "
                    + $"Next='{shellHost.PipelineReviewGuideNextActionText}', Decision='{shellHost.PipelineReviewGuideResultDecisionText}', "
                    + $"Detail='{shellHost.PipelineReviewGuideDetailText}'");
            }
        });
    }

    private static CaptureResult CaptureShellHostPipelineReviewNg(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        string recipeName = "Smoke_WpfPipelineReviewNg_" + Guid.NewGuid().ToString("N");
        OpenVisionShellHostView shellHost = CreateShellHost(recipeName);
        VisionPipeline pipeline = CreatePipelineReviewAcceptanceNgPipeline();
        VisionPipelineStorage.Save(recipeName, pipeline);
        VisionPipelineStorage.SaveActivePipelineName(recipeName, pipeline.Name);
        return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
        {
            shellHost.SelectToolForTest(VISION_MENU.Pipeline);
            Pump(24);
            if (shellHost.PipelineReviewStepCount != 3
                || !shellHost.PipelineReviewSelectedStepName.Contains("Threshold", StringComparison.OrdinalIgnoreCase)
                || !shellHost.PipelineReviewGuideResultDecisionText.Contains(OpenVisionLanguageService.T("PipelineReview.Guide.NoRunDecision"), StringComparison.Ordinal))
            {
                throw new InvalidOperationException(
                    "Pipeline review NG smoke did not start from the expected pre-run threshold step. "
                    + $"Steps={shellHost.PipelineReviewStepCount}, Selected='{shellHost.PipelineReviewSelectedStepName}', "
                    + $"Decision='{shellHost.PipelineReviewGuideResultDecisionText}'.");
            }

            WaitForTaskWithPump(shellHost.RunPipelineReviewForTestAsync(), 30000, "Pipeline review NG execution");
            Pump(32);
            string ngNextAction = OpenVisionLanguageService.T("PipelineReview.Guide.NgNext");
            string fixDetailPrefix = OpenVisionLanguageService.T("PipelineReview.Guide.FixDetailPrefix");
            string parameterLocationPrefix = OpenVisionLanguageService.T("PipelineReview.Guide.ParameterLocationPrefix");
            string resultWidthMetricText = OpenVisionLanguageService.T("PipelineReview.Metric.ResultImageWidth");
            string waitText = OpenVisionLanguageService.T("PipelineReview.Progress.CountsFormat")
                .Contains("대기", StringComparison.Ordinal)
                    ? "대기"
                    : "WAIT";
            if (string.IsNullOrWhiteSpace(shellHost.PipelineReviewValidationStatusText)
                || !shellHost.PipelineReviewResultSummaryText.Contains("NG", StringComparison.OrdinalIgnoreCase)
                || !shellHost.PipelineReviewProgressText.Contains("OK 0", StringComparison.OrdinalIgnoreCase)
                || !shellHost.PipelineReviewProgressText.Contains("NG 1", StringComparison.OrdinalIgnoreCase)
                || !shellHost.PipelineReviewProgressText.Contains(waitText, StringComparison.OrdinalIgnoreCase)
                || shellHost.PipelineReviewProgressText.Contains(OpenVisionLanguageService.T("PipelineReview.Progress.Running"), StringComparison.Ordinal)
                || !shellHost.PipelineReviewGuideResultDecisionText.Contains("NG", StringComparison.OrdinalIgnoreCase)
                || !shellHost.PipelineReviewGuideNextActionText.Contains(ngNextAction, StringComparison.Ordinal)
                || !shellHost.PipelineReviewGuideNextActionText.Contains(resultWidthMetricText, StringComparison.Ordinal)
                || !shellHost.PipelineReviewGuideDetailText.Contains("NG", StringComparison.OrdinalIgnoreCase)
                || !shellHost.PipelineReviewGuideDetailText.Contains(fixDetailPrefix, StringComparison.Ordinal)
                || !shellHost.PipelineReviewGuideDetailText.Contains(parameterLocationPrefix, StringComparison.Ordinal)
                || !shellHost.PipelineReviewGuideDetailText.Contains("파라미터 패널", StringComparison.Ordinal)
                || !shellHost.PipelineReviewGuideParameterFocusText.Contains(parameterLocationPrefix, StringComparison.Ordinal)
                || !shellHost.PipelineReviewGuideParameterFocusText.Contains("파라미터 패널", StringComparison.Ordinal)
                || !shellHost.PipelineReviewGuideDetailText.Contains(resultWidthMetricText, StringComparison.Ordinal)
                || !shellHost.PipelineReviewGuideDetailText.Contains("<= 1", StringComparison.OrdinalIgnoreCase)
                || !shellHost.PipelineReviewGuideDetailText.Contains("511", StringComparison.Ordinal)
                || shellHost.PipelineReviewGuideDetailText.Contains("Result Width", StringComparison.OrdinalIgnoreCase)
                || !shellHost.PipelineReviewResultDetailText.Contains(resultWidthMetricText, StringComparison.Ordinal)
                || !shellHost.PipelineReviewResultDetailText.Contains("511", StringComparison.Ordinal)
                || shellHost.PipelineReviewResultDetailText.Contains("Result Width", StringComparison.OrdinalIgnoreCase)
                || string.IsNullOrWhiteSpace(shellHost.PipelineReviewRunLogText))
            {
                throw new InvalidOperationException(
                    "Pipeline review did not expose the acceptance NG decision and beginner-readable fix guidance. "
                    + $"Validation='{shellHost.PipelineReviewValidationStatusText}', Result='{shellHost.PipelineReviewResultSummaryText}', "
                    + $"Progress='{shellHost.PipelineReviewProgressText}', Next='{shellHost.PipelineReviewGuideNextActionText}', Decision='{shellHost.PipelineReviewGuideResultDecisionText}', "
                    + $"Detail='{shellHost.PipelineReviewGuideDetailText}', ResultDetail='{shellHost.PipelineReviewResultDetailText}', "
                    + $"RunLog='{shellHost.PipelineReviewRunLogText}'.");
            }

            if (!shellHost.HasPipelineReviewOutputPreview)
            {
                throw new InvalidOperationException("Pipeline review NG did not keep the failed step output image visible for inspection.");
            }

            int nativePreviewRunsAfterReview = shellHost.NativePreviewRunCount;
            shellHost.SelectPipelineReviewStepForTest(2, OpenVisionLab.Pipeline.Controls.PipelineFlowPreviewMode.Output);
            Pump(32);
            if (!shellHost.PipelineReviewSelectedStepName.Contains("Filter", StringComparison.OrdinalIgnoreCase)
                || !shellHost.CanSelectFirstIssuePipelineReviewStepForTest)
            {
                throw new InvalidOperationException(
                    "Pipeline review NG smoke could not move away from the first issue while keeping first-issue navigation available. "
                    + $"Selected='{shellHost.PipelineReviewSelectedStepName}', FirstIssue={shellHost.CanSelectFirstIssuePipelineReviewStepForTest}");
            }

            ClickFloatingButtonByName("btnFirstIssueStep", "Pipeline review first-issue navigation button");
            Pump(32);
            if (!shellHost.PipelineReviewSelectedStepName.Contains("Threshold", StringComparison.OrdinalIgnoreCase)
                || !shellHost.PipelineReviewGuideStageText.Contains("1/3", StringComparison.Ordinal)
                || !shellHost.PipelineReviewResultSummaryText.Contains("NG", StringComparison.OrdinalIgnoreCase))
            {
                throw new InvalidOperationException(
                    "Pipeline review first-issue navigation did not select the first NG step. "
                    + $"Selected='{shellHost.PipelineReviewSelectedStepName}', Stage='{shellHost.PipelineReviewGuideStageText}', Result='{shellHost.PipelineReviewResultSummaryText}'");
            }

            if (shellHost.NativePreviewRunCount != nativePreviewRunsAfterReview)
            {
                throw new InvalidOperationException(
                    "Pipeline review first-issue navigation triggered an unexpected native Preview/Run. "
                    + $"RunsBefore={nativePreviewRunsAfterReview}, RunsAfter={shellHost.NativePreviewRunCount}");
            }

            if (!FloatingToolTextContains(resultWidthMetricText))
            {
                throw new InvalidOperationException(
                    "Pipeline review NG visible detail did not keep the acceptance metric localized. "
                    + $"ExpectedMetric='{resultWidthMetricText}', Detail='{shellHost.PipelineReviewGuideDetailText}'.");
            }
        });
    }

    private static VisionPipeline CreatePipelineReviewReadabilityPipeline()
    {
        VisionPipeline pipeline = new()
        {
            Name = "Pipeline"
        };

        ThresholdToolProperty threshold = new()
        {
            Threshold = 112,
            MaxValue = 255,
            RangeMin = 40,
            RangeMax = 220,
            BlockSize = 25,
            Weight = 5
        };
        MorphologyToolProperty morphology = new()
        {
            KernelWidth = 3,
            KernelHeight = 3,
            Iterations = 1
        };
        FilterToolProperty branchFilter = new()
        {
            KernelWidth = 3,
            KernelHeight = 3,
            MedianKernelSize = 3,
            Diameter = 3,
            SigmaColor = 3,
            SigmaSpace = 3
        };

        pipeline.Steps.Add(VisionPipelineStepBuilder.FromThresholdProperty(threshold, "Threshold_Main", "Main", "Threshold_Preview"));
        pipeline.Steps.Add(VisionPipelineStepBuilder.FromMorphologyProperty(morphology, "Morphology_From_Threshold", "Threshold_Preview", "Morphology_Preview"));
        pipeline.Steps.Add(VisionPipelineStepBuilder.FromFilterProperty(branchFilter, "Filter_Branch_Main", "Main", "Filter_Branch_Preview"));
        return pipeline;
    }

    private static void AssertPipelineReviewCalibrationReadiness()
    {
        VisionPipeline pipeline = new() { Name = "Calibration_Readiness" };
        VisionPipelineStep step = new()
        {
            Name = "01 Distance Mm",
            ToolType = "LineDistance",
            Enabled = true,
            InputLayer = "Main",
            OutputLayer = "Distance_Preview",
            UseAcceptance = true,
            AcceptanceMetricName = "DistanceMmAvg",
            UseAcceptanceMetricMinimum = true,
            AcceptanceMetricMinimum = 0.1,
            UseAcceptanceMetricMaximum = true,
            AcceptanceMetricMaximum = 1.0
        };
        step.Parameters["PIXELPERMM"] = "0.006";
        pipeline.Steps.Add(step);

        OpenVisionPipelineReviewReadinessItem configuredItem = OpenVisionPipelineReviewReadinessPresenter.Create(
                pipeline,
                VisionPipelineValidator.Validate(pipeline, new[] { "Main" }),
                _ => true,
                false,
                false)
            .Items
            .Single(item => string.Equals(item.Key, "Calibration", StringComparison.Ordinal));
        string expectedConfigured = string.Format(
            CultureInfo.CurrentCulture,
            OpenVisionLanguageService.T("PipelineReview.Readiness.CalibrationReferenceCheckFormat"),
            0.006D.ToString("0.######", CultureInfo.CurrentCulture));
        if (!configuredItem.IsAdvisory || !string.Equals(configuredItem.StatusText, expectedConfigured, StringComparison.Ordinal))
        {
            throw new InvalidOperationException(
                "Pipeline review readiness did not keep a configured mm scale in reference-check status. "
                + $"Advisory={configuredItem.IsAdvisory}, Status='{configuredItem.StatusText}', Expected='{expectedConfigured}'");
        }

        step.AcceptanceMetricName = "DistancePxAvg";
        step.Parameters["PIXELPERMM"] = "0";
        OpenVisionPipelineReviewReadinessItem pixelOnlyItem = OpenVisionPipelineReviewReadinessPresenter.Create(
                pipeline,
                VisionPipelineValidator.Validate(pipeline, new[] { "Main" }),
                _ => true,
                false,
                false)
            .Items
            .Single(item => string.Equals(item.Key, "Calibration", StringComparison.Ordinal));
        if (!pixelOnlyItem.IsNotApplicable)
        {
            throw new InvalidOperationException(
                "Pipeline review readiness did not preserve a px-only acceptance gate without calibration warning. "
                + $"NotApplicable={pixelOnlyItem.IsNotApplicable}, Status='{pixelOnlyItem.StatusText}'");
        }

        step.AcceptanceMetricName = "DistanceMmAvg";
        OpenVisionPipelineReviewReadinessItem missingItem = OpenVisionPipelineReviewReadinessPresenter.Create(
                pipeline,
                VisionPipelineValidator.Validate(pipeline, new[] { "Main" }),
                _ => true,
                false,
                false)
            .Items
            .Single(item => string.Equals(item.Key, "Calibration", StringComparison.Ordinal));
        if (!missingItem.IsCheck)
        {
            throw new InvalidOperationException(
                "Pipeline review readiness did not flag a non-positive PIXELPERMM value. "
                + $"Check={missingItem.IsCheck}, Status='{missingItem.StatusText}'");
        }
    }

    private static VisionPipeline CreatePipelineReviewInputStatePipeline()
    {
        VisionPipeline pipeline = new()
        {
            Name = "Pipeline_Input_State"
        };

        ThresholdToolProperty threshold = new()
        {
            Threshold = 112,
            MaxValue = 255
        };
        FilterToolProperty missingInputFilter = new()
        {
            KernelWidth = 3,
            KernelHeight = 3,
            MedianKernelSize = 3
        };

        pipeline.Steps.Add(VisionPipelineStepBuilder.FromThresholdProperty(threshold, "01 Source Threshold", "Main", "Threshold_Preview"));
        pipeline.Steps.Add(VisionPipelineStepBuilder.FromFilterProperty(missingInputFilter, "02 Missing External Input", "Unloaded_External", "Missing_Input_Preview"));
        return pipeline;
    }

    private static VisionPipeline CreatePipelineReviewAcceptanceNgPipeline()
    {
        VisionPipeline pipeline = CreatePipelineReviewReadabilityPipeline();
        pipeline.Name = "Pipeline_NG";

        VisionPipelineStep thresholdStep = pipeline.Steps.First();
        thresholdStep.UseAcceptance = true;
        thresholdStep.ExpectedSuccess = true;
        thresholdStep.RequiredMessageText = string.Empty;
        thresholdStep.AcceptanceMetricName = VisionPipelineKnownMetrics.ResultImageWidth;
        thresholdStep.UseAcceptanceMetricMinimum = false;
        thresholdStep.AcceptanceMetricMinimum = 0;
        thresholdStep.UseAcceptanceMetricMaximum = true;
        thresholdStep.AcceptanceMetricMaximum = 1;
        return pipeline;
    }

    private static void WaitForTaskWithPump(Task task, int timeoutMilliseconds, string description)
    {
        if (task == null)
        {
            return;
        }

        DateTime deadline = DateTime.UtcNow.AddMilliseconds(Math.Max(1000, timeoutMilliseconds));
        while (!task.IsCompleted && DateTime.UtcNow < deadline)
        {
            Pump(4);
            Thread.Sleep(10);
        }

        if (!task.IsCompleted)
        {
            throw new TimeoutException(description + " timed out.");
        }

        task.GetAwaiter().GetResult();
    }

    private static CaptureResult CaptureThresholdOutputThenBlobOpen(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        OpenVisionShellHostView shellHost = CreateShellHost("Smoke_WpfThresholdOutputThenBlobOpen", seedMainLayer: false);
        using Bitmap mainBitmap = CreateWorkspaceSeedSmokeBitmap();
        shellHost.SetMainLayerImageForTest(mainBitmap);

        return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
        {
            shellHost.SelectToolForTest(VISION_MENU.Threshold);
            Pump(16);
            RadioButton? basicInvert = Application.Current.Windows
                .OfType<Window>()
                .Where(item => item.IsVisible && item.GetType().Name == "OpenVisionFloatingToolWindow")
                .SelectMany(FindVisualChildren<RadioButton>)
                .FirstOrDefault(item => string.Equals(item.Name, "rbBasicInvert", StringComparison.Ordinal));
            if (basicInvert == null)
            {
                throw new InvalidOperationException("Threshold BinaryInv option was not found for Blob detection teaching.");
            }

            basicInvert.IsChecked = true;
            Pump(12);
            shellHost.CreateActiveNativeOutputLayerForTest();
            Pump(12);
            shellHost.RunActiveNativePreviewForTest();
            Pump(24);

            if (!shellHost.HasNativePreviewResult
                || !string.Equals(shellHost.ActiveNativeRouteInputLayerNameForTest, "Main", StringComparison.OrdinalIgnoreCase)
                || !string.Equals(shellHost.ActiveNativeRouteOutputLayerNameForTest, "Threshold_Preview", StringComparison.OrdinalIgnoreCase))
            {
                throw new InvalidOperationException(
                    "Threshold did not publish a stable Main -> Threshold_Preview result before Blob open. "
                    + $"Input={shellHost.ActiveNativeRouteInputLayerNameForTest}, Output={shellHost.ActiveNativeRouteOutputLayerNameForTest}, Status={shellHost.ActiveNativeStatusText}");
            }

            AssertNoAutoDockedLayers(shellHost, "Threshold auto-preview");

            shellHost.SelectToolForTest(VISION_MENU.Blob);
            Pump(20);
            ComboBox inputLayerCombo = FindFloatingComboBox("cbInputLayer");
            AssertVisionToolComboTemplate(inputLayerCombo, "Blob after Threshold input layer combo");
            AssertComboBoxPopupLayout(inputLayerCombo, "Blob after Threshold input layer combo");
            AssertComboBoxOpensFromPreviewMouseClick(inputLayerCombo, "Blob after Threshold input layer combo");
            if (!shellHost.IsNativeDocumentActive
                || !shellHost.ActiveNativeDocumentTypeName.Contains("BlobToolWpfView", StringComparison.Ordinal)
                || !ComboBoxContainsText(inputLayerCombo, "Main")
                || !ComboBoxContainsText(inputLayerCombo, "Threshold_Preview"))
            {
                throw new InvalidOperationException(
                    "Blob did not open correctly after Threshold output creation. "
                    + $"Document={shellHost.ActiveNativeDocumentTypeName}, Combo={GetComboBoxCurrentText(inputLayerCombo)}");
            }
        });
    }

    private static CaptureResult CaptureThresholdToBlobDetectionE2E(string outputPath)
    {
        OpenVisionLanguageService.SetLanguage(OpenVisionLanguage.Korean, false);
        OpenVisionShellHostView shellHost = CreateShellHost("Smoke_WpfThresholdToBlobDetection", seedMainLayer: false);
        using Bitmap mainBitmap = CreateWorkspaceSeedSmokeBitmap();
        shellHost.SetMainLayerImageForTest(mainBitmap);

        return CaptureWindowWithContent(shellHost, outputPath, 1600, 900, () =>
        {
            shellHost.SelectToolForTest(VISION_MENU.Threshold);
            Pump(16);
            if (!shellHost.ConfigureActiveThresholdBasicInvertForTest(true))
            {
                throw new InvalidOperationException("Threshold -> Blob detection could not configure Threshold as BinaryInv.");
            }

            Pump(8);
            int beforeThresholdRuns = shellHost.NativePreviewRunCount;
            SetFloatingSliderValueByName("Threshold basic slider", "sliderThreshold", 84D);
            Thread.Sleep(180);
            Pump(30);
            if (shellHost.HasNativePreviewResult || shellHost.NativePreviewRunCount != beforeThresholdRuns)
            {
                throw new InvalidOperationException(
                    "Threshold slider change must wait for explicit Preview. "
                    + $"RunsBefore={beforeThresholdRuns}, RunsAfter={shellHost.NativePreviewRunCount}, Status={shellHost.ActiveNativeStatusText}");
            }

            shellHost.RunActiveNativePreviewForTest();
            Pump(30);
            if (!shellHost.HasNativePreviewResult || shellHost.NativePreviewRunCount != beforeThresholdRuns + 1)
            {
                throw new InvalidOperationException(
                    "Explicit Threshold Preview did not produce Threshold_Preview exactly once. "
                    + $"RunsBefore={beforeThresholdRuns}, RunsAfter={shellHost.NativePreviewRunCount}, Status={shellHost.ActiveNativeStatusText}");
            }

            using Bitmap mainLayer = shellHost.GetLayerImageCloneForTest("Main");
            using Bitmap thresholdLayer = shellHost.GetLayerImageCloneForTest("Threshold_Preview");
            AssertBitmapPresent(mainLayer, "Main layer after Threshold preview");
            AssertBitmapPresent(thresholdLayer, "Threshold_Preview layer after Threshold preview");
            AssertBitmapVisiblyDifferent(mainLayer, thresholdLayer, "Threshold output should visibly differ from Main");
            AssertBitmapBinaryLike(thresholdLayer, "Threshold_Preview output");
            SaveDiagnosticBitmap(outputPath, "threshold-to-blob-main.png", mainLayer);
            SaveDiagnosticBitmap(outputPath, "threshold-to-blob-threshold.png", thresholdLayer);

            if (!shellHost.HasNativePreviewResult
                || !string.Equals(shellHost.ActiveNativeRouteInputLayerNameForTest, "Main", StringComparison.OrdinalIgnoreCase)
                || !string.Equals(shellHost.ActiveNativeRouteOutputLayerNameForTest, "Threshold_Preview", StringComparison.OrdinalIgnoreCase))
            {
                throw new InvalidOperationException(
                    "Threshold did not publish a teachable binary output before Blob detection. "
                    + $"Input={shellHost.ActiveNativeRouteInputLayerNameForTest}, Output={shellHost.ActiveNativeRouteOutputLayerNameForTest}, Status={shellHost.ActiveNativeStatusText}");
            }

            shellHost.SelectToolForTest(VISION_MENU.Blob);
            Pump(20);
            ComboBox inputLayerCombo = FindFloatingComboBox("cbInputLayer");
            if (inputLayerCombo == null)
            {
                throw new InvalidOperationException("Blob input layer combo was not found for Threshold_Preview detection.");
            }

            AssertVisionToolComboTemplate(inputLayerCombo, "Blob Threshold_Preview input layer combo");
            AssertComboBoxPopupLayout(inputLayerCombo, "Blob Threshold_Preview input layer combo");
            AssertFloatingPropertyGridRowsRendered("Threshold -> Blob property grid");
            Pump(80);
            SelectComboBoxItemText(inputLayerCombo, "Threshold_Preview", "Blob Threshold_Preview input layer combo");
            Pump(24);

            if (!string.Equals(shellHost.ActiveNativeRouteInputLayerNameForTest, "Threshold_Preview", StringComparison.OrdinalIgnoreCase)
                || !HasFloatingToolPreviewImageSource())
            {
                throw new InvalidOperationException(
                    "Blob did not switch its input preview to the Threshold_Preview layer. "
                    + $"Combo={GetComboBoxCurrentText(inputLayerCombo)}, Route={shellHost.ActiveNativeRouteInputLayerNameForTest}");
            }

            shellHost.RunActiveNativePreviewForTest();
            Pump(32);
            if (!shellHost.IsNativeDocumentActive
                || !shellHost.HasNativePreviewResult
                || !string.Equals(shellHost.ActiveNativeRouteOutputLayerNameForTest, "Blob_Preview", StringComparison.OrdinalIgnoreCase))
            {
                throw new InvalidOperationException(
                    "Blob did not produce a detection preview from Threshold_Preview. "
                    + $"Output={shellHost.ActiveNativeRouteOutputLayerNameForTest}, Status={shellHost.ActiveNativeStatusText}");
            }

            AssertResultReviewVisible("Threshold -> Blob detection", "Blob /", "검출", "중심", "박스");
            AssertResultReviewDoesNotContain("Threshold -> Blob detection", "검출 0", "블랍 없음", "박스 512x384");
            AssertNoAutoDockedLayers(shellHost, "Blob preview from Threshold_Preview");

            using Bitmap blobLayer = shellHost.GetLayerImageCloneForTest("Blob_Preview");
            AssertBitmapPresent(blobLayer, "Blob_Preview layer after detection");
            SaveDiagnosticBitmap(outputPath, "threshold-to-blob-blob.png", blobLayer);

            shellHost.SelectToolForTest(VISION_MENU.Contour);
            Pump(20);
            inputLayerCombo = FindFloatingComboBox("cbInputLayer");
            AssertVisionToolComboTemplate(inputLayerCombo, "Contour Threshold_Preview input layer combo");
            AssertComboBoxPopupLayout(inputLayerCombo, "Contour Threshold_Preview input layer combo");
            AssertFloatingPropertyGridRowsRendered("Threshold -> Contour property grid");
            SelectComboBoxItemText(inputLayerCombo, "Threshold_Preview", "Contour Threshold_Preview input layer combo");
            Pump(24);

            if (!string.Equals(shellHost.ActiveNativeRouteInputLayerNameForTest, "Threshold_Preview", StringComparison.OrdinalIgnoreCase)
                || !HasFloatingToolPreviewImageSource())
            {
                throw new InvalidOperationException(
                    "Contour did not switch its input preview to the Threshold_Preview layer. "
                    + $"Combo={GetComboBoxCurrentText(inputLayerCombo)}, Route={shellHost.ActiveNativeRouteInputLayerNameForTest}");
            }

            shellHost.RunActiveNativePreviewForTest();
            Pump(32);
            if (!shellHost.IsNativeDocumentActive
                || !shellHost.HasNativePreviewResult
                || !string.Equals(shellHost.ActiveNativeRouteOutputLayerNameForTest, "Contour_Preview", StringComparison.OrdinalIgnoreCase))
            {
                throw new InvalidOperationException(
                    "Contour did not produce a detection preview from Threshold_Preview. "
                    + $"Output={shellHost.ActiveNativeRouteOutputLayerNameForTest}, Status={shellHost.ActiveNativeStatusText}");
            }

            AssertResultReviewVisible("Threshold -> Contour detection", "Contour /", "검출", "중심", "박스");
            AssertResultReviewDoesNotContain("Threshold -> Contour detection", "검출 0", "컨투어 없음", "박스 512x384");
            AssertNoAutoDockedLayers(shellHost, "Contour preview from Threshold_Preview");

            using Bitmap contourLayer = shellHost.GetLayerImageCloneForTest("Contour_Preview");
            AssertBitmapPresent(contourLayer, "Contour_Preview layer after detection");
            SaveDiagnosticBitmap(outputPath, "threshold-to-contour-contour.png", contourLayer);
            WriteFloatingToolWindowCapture(outputPath);
        }, captureFloatingToolWindow: false);
    }

    private static CaptureResult CaptureShellHostBlobTool(string outputPath)
